window.TM_OFFLINE_KB = {"v":1,"modules":[{"m":"M0","slug":"00-binet","title":"比奈方程","tags":["中心力","比奈方程","圆锥曲线","进动"],"summary":"由中心力角动量守恒导出比奈方程 $u''+u=-(F(1/u))/(mh^2u^2)$，用于定量求解圆锥曲线轨道、近日点进动与轨道闭合条件。","href":"modules/00-binet/index.html","pdf":"modules/00-binet/binet.html"},{"m":"M1","slug":"01-effective-potential","title":"有效势与轨道稳定性","tags":["有效势","RK4","Bertrand","进动"],"summary":"将角动量离心项并入势能构成有效势 $V_eff(r)=V(r)+(L^2)/(2mr^2)$，由曲线几何直接读出转折点、圆轨道稳定性、径向小振动与伯特兰定理。","href":"modules/01-effective-potential/index.html","pdf":"modules/01-effective-potential/note.html"},{"m":"M2","slug":"02-scattering","title":"散射与俘获","tags":["散射","截面","俘获","RK4"],"summary":"分析中心力场中的散射偏转角 $Θ(b)$、微分散射截面 $dσdΩ$ 与吸引势垒俘获截面 $σ=π b_c^2$。","href":"modules/02-scattering/index.html","pdf":"modules/02-scattering/note.html"},{"m":"M3","slug":"03-two-body","title":"两体问题与系外行星","tags":["两体","RV","多普勒","系外行星"],"summary":"引入质心与约化质量 $μ=(M_1M_2)/(M_1+M_2)$ 将两体问题化为等效单体，导出开普勒第三定律并反演系外行星视向速度曲线。","href":"modules/03-two-body/index.html","pdf":"modules/03-two-body/note.html"},{"m":"M4","slug":"06-collisions","title":"碰撞与变质量","tags":["碰撞","变质量","恢复系数","雨滴"],"summary":"结合动量守恒与恢复系数 $e$ 分析一维与二维碰撞，并建立雨滴连续吸积等变质量系统的动力学方程。","href":"modules/06-collisions/index.html","pdf":"modules/06-collisions/note.html"},{"m":"M5","slug":"08-kinematics","title":"圆柱脱离与运动学","tags":["运动学","极坐标","圆柱脱离","约束"],"summary":"建立极坐标与自然坐标下的速度、加速度分解与伽利略变换，并以圆柱滑落脱离角 $cosθ=(2)/(3)$ 演示单面约束失效。","href":"modules/08-kinematics/index.html?mode=cylinder","pdf":"modules/08-kinematics/note.html"},{"m":"M6","slug":"14-foucault-rose","title":"傅科摆与玫瑰线","tags":["傅科摆","科里奥利力","转动参考系","进动"],"summary":"在地球转动参考系中计入科里奥利力，导出傅科摆进动周期 $T_F=(2π)/(Ω|sinλ|)$ 与地面玫瑰线轨迹。","href":"modules/14-foucault-rose/index.html","pdf":"chapters/01-newton/manuscripts/book.html"},{"m":"M7","slug":"15-lagrange-points","title":"拉格朗日点","tags":["拉格朗日点","限制性三体","有效势","蝌蚪轨道"],"summary":"研究旋转参考系下的圆限制性三体问题（CR3BP）：五个拉格朗日平稳点 $L_1$–$L_5$、雅可比常数零速度曲线与 $L_4/L_5$ 蝌蚪/马蹄轨道。","href":"modules/15-lagrange-points/index.html","pdf":"chapters/01-newton/manuscripts/book.html"},{"m":"M8","slug":"04-variational","title":"等时摆与摆线","tags":["变分","摆线","等时性","时间泛函"],"summary":"由变分法导出摆线为重力场中的最速降线，并证明沿摆线任意位置释放均严格等时，周期 $T=π√(a/g)$ 与振幅无关。","href":"modules/04-variational/index.html?mode=cycloid","pdf":"modules/04-variational/note.html"},{"m":"M9","slug":"04-variational","title":"折射定律","tags":["变分","费马原理","折射","Snell"],"summary":"将费马光程泛函 $∫ n ds$ 取驻值，直接导出光学折射的 Snell 定律 $n_1sinθ_1=n_2sinθ_2$。","href":"modules/04-variational/index.html?mode=refraction","pdf":"modules/04-variational/note.html"},{"m":"M10","slug":"04-variational","title":"最短路径","tags":["变分","测地线","最短路径","E–L"],"summary":"对弧长泛函 $$ 应用欧拉–拉格朗日方程，证明欧氏平面最短路径为直线，并推广至曲面测地线。","href":"modules/04-variational/index.html?mode=shortest","pdf":"modules/04-variational/note.html"},{"m":"M11","slug":"05-virtual-work","title":"虚功原理与静力学","tags":["虚功","静力学","梯子","平衡"],"summary":"利用理想约束力不做虚功的原理 $δ W=0$ 与势能驻值 $δ V=0$ 求解静力平衡，分析梯子临界角 $tanθ_min=(1)/(2μ)$ 与稳定性。","href":"modules/05-virtual-work/index.html","pdf":"modules/05-virtual-work/note.html"},{"m":"M12","slug":"09-atwood-pulley","title":"有转动惯量的 Atwood 机","tags":["Atwood","转动惯量","张力差","拉格朗日"],"summary":"以广义坐标求解含滑轮转动惯量 $I$ 的 Atwood 机，得等效质量 $m_1+m_2+I/R^2$ 与绳两端张力差 $T_2-T_1=Ia/R^2$。","href":"modules/09-atwood-pulley/index.html","pdf":"modules/09-atwood-pulley/note.html"},{"m":"M13","slug":"10-coupled-systems","title":"斜面上的滑块","tags":["耦合","循环坐标","斜面","约束"],"summary":"利用可动斜面的水平循环坐标 $X$ 得动量 $p_X$ 守恒，求解滑块相对加速度 $a_rel$ 与约束反力的动能分配。","href":"modules/10-coupled-systems/index.html?scene=wedge","pdf":"modules/10-coupled-systems/note.html"},{"m":"M14","slug":"10-coupled-systems","title":"弹簧摆","tags":["耦合","弹簧摆","简正坐标","小振动"],"summary":"对弹簧摆在平衡长度 $r_0=l_0+mg/k$ 附近线性化，分解径向 $ω_r=√(k/m)$ 与摆动 $ω_θ=√(g/r_0)$ 两支简正振动。","href":"modules/10-coupled-systems/index.html?scene=spring","pdf":"modules/10-coupled-systems/note.html"},{"m":"M15","slug":"10-coupled-systems","title":"小车与单摆","tags":["耦合","小车单摆","动量守恒","小振动"],"summary":"由水平动量守恒 $p_X=0$ 消去小车位移，导出小车–单摆耦合系统的小振动频率 $ω=√((g(M+m))/(Ml))$ 与反冲规律。","href":"modules/10-coupled-systems/index.html?scene=cart","pdf":"modules/10-coupled-systems/note.html"},{"m":"M16","slug":"08b-nonlinear","title":"单摆周期修正","tags":["单摆","周期修正","Lindstedt","相空间"],"summary":"用微扰展开与 Lindstedt 方法计算单摆大角周期修正 $T≈ T_0(1+(θ_0^2)/(16)+(11θ_0^4)/(3072))$，观察非线性相图。","href":"modules/08-kinematics/index.html?mode=pendulum","pdf":"modules/08-kinematics/note.html"},{"m":"M17","slug":"08b-nonlinear","title":"双摆混沌","tags":["双摆","混沌","初值敏感","相空间"],"summary":"模拟两自由度双摆在大振幅下的初值敏感性与轨迹指数分离，对比可积与混沌动力学行为。","href":"modules/08-kinematics/index.html?mode=double","pdf":"modules/08-kinematics/note.html"},{"m":"M18","slug":"07-rigid-body","title":"刚体几何与角动量","tags":["刚体","角动量","球壳","质心"],"summary":"建立刚体转动惯量、平行轴定理 $I=I_cm+md^2$ 与角动量守恒，涵盖球壳定理、球冠质心与薄圆盘角动量。","href":"modules/07-rigid-body/index.html","pdf":"modules/07-rigid-body/note.html"},{"m":"M19","slug":"17-free-rigid-body","title":"自由刚体与网球拍效应","tags":["欧拉方程","自由刚体","网球拍定理","角动量"],"summary":"在惯量主轴系中积分无力矩欧拉方程 $I_1ω_1=(I_2-I_3)ω_2ω_3$，演示中间轴不稳定与网球拍翻转效应。","href":"modules/17-free-rigid-body/index.html","pdf":"chapters/05-rigid-body/manuscripts/book.html"},{"m":"M20","slug":"11-rotation-and-field","title":"旋转圆环上的珠子","tags":["旋转参考系","有效势","分岔","雅可比积分"],"summary":"建立旋转圆环上珠子的有效势与雅可比积分，观察超过临界转速 $Ω_c=√(g/R)$ 时的超临界叉式分岔。","href":"modules/11-rotation-and-field/index.html?scene=ring","pdf":"modules/11-rotation-and-field/note.html"},{"m":"M21","slug":"11-rotation-and-field","title":"磁场中的带电粒子","tags":["磁场","回旋运动","诺特荷","正则动量"],"summary":"分析均匀磁场中带电粒子的规范正则动量与平移诺特荷 $Q_x,Q_y$，揭示守恒荷如何锁定回旋圆心位置。","href":"modules/11-rotation-and-field/index.html?scene=cyclotron","pdf":"modules/11-rotation-and-field/note.html"},{"m":"M22","slug":"18-phase-space","title":"相空间与刘维尔","tags":["相空间","刘维尔","单摆","面积保持"],"summary":"在单摆相平面 $(q,p)$ 中区分摆动、转动与分界线 $E=2K$，以相点云演化直观验证哈密顿流的刘维尔保面积定理。","href":"modules/18-phase-space/index.html?scene=phase","pdf":"chapters/06-hamiltonian/manuscripts/book.html"},{"m":"M23","slug":"18-phase-space","title":"辛积分器比较","tags":["辛积分","Verlet","能量误差","长期稳定性"],"summary":"对比显式 Euler、辛 Euler 与 Störmer–Verlet 积分器在谐振子上的相面积保持与长期能量误差行为。","href":"modules/18-phase-space/index.html?scene=integrator","pdf":"chapters/06-hamiltonian/manuscripts/book.html"},{"m":"M24","slug":"13-lightcone-worldlines","title":"光锥与世界线","tags":["光锥","世界线","时空间隔","同时性"],"summary":"在闵可夫斯基时空图中绘制光锥与世界线，实时判定类时/类光/类空间隔 $s^2=c^2t^2-x^2$、同时线倾斜与双生子固有时。","href":"modules/13-lightcone-worldlines/index.html","pdf":"chapters/07-relativity/manuscripts/book.html"},{"m":"M25","slug":"16-doppler-beaming","title":"相对论多普勒与车头灯效应","tags":["多普勒效应","光行差","车头灯效应","星场"],"summary":"由波四矢量洛伦兹变换导出相对论多普勒频移 $ω'=γω(1-βcosα)$，呈现星场光行差与车头灯集束效应。","href":"modules/16-doppler-beaming/index.html","pdf":"chapters/07-relativity/manuscripts/book.html"},{"m":"M26","slug":"19-relativistic-collisions","title":"相对论碰撞与不变质量","tags":["四动量","不变质量","阈能","碰撞"],"summary":"利用四动量守恒与系统不变质量 $M_inv=(∑ E)^2-()^2$ 分析弹性与完全非弹性相对论碰撞。","href":"modules/19-relativistic-collisions/index.html","pdf":"chapters/07-relativity/manuscripts/book.html"},{"m":"M27","slug":"20-forced-resonance","title":"受迫振动与共振","tags":["受迫振动","共振","品质因数","拍频"],"summary":"研究受迫阻尼振子 $q+2+ω_0^2 q=F_0cosω t$ 的稳态响应、幅值/功率双共振曲线、半功率带宽 $2γ$、品质因数 $Q$ 与拍频。","href":"modules/20-forced-resonance/index.html","pdf":"chapters/04-oscillations/manuscripts/book.html"},{"m":"M28","slug":"21-heavy-top","title":"重陀螺的进动与章动","tags":["进动","章动","睡眠陀螺","有效势"],"summary":"消去循环欧拉角得重对称陀螺倾角有效势 $V_eff(θ)$，演示稳恒进动慢支/快支、章动与睡眠陀螺阈值 $ω_3c=√(4I_1Mgl)I_3$。","href":"modules/21-heavy-top/index.html","pdf":"chapters/05-rigid-body/manuscripts/book.html"},{"m":"M29","slug":"22-legendre-routh","title":"勒让德变换与罗斯约化","tags":["勒让德变换","正则方程","罗斯约化","循环坐标"],"summary":"以切线构造展示勒让德变换 $L(q,q)rightarrow H(q,p)$，对照正则方程与拉格朗日方程，并用罗斯约化消去循环坐标。","href":"modules/22-legendre-routh/index.html","pdf":"chapters/06-hamiltonian/manuscripts/book.html"},{"m":"M30","slug":"23-hyperbolic-motion","title":"双曲运动与恒固有加速度","tags":["双曲运动","固有加速度","快度","Rindler视界"],"summary":"研究恒固有加速度双曲世界线 $x^2-(ct)^2=(c^2/a)^2$，演示快度线性增长 $η=aτ/c$、固有时与 Rindler 视界。","href":"modules/23-hyperbolic-motion/index.html","pdf":"chapters/07-relativity/manuscripts/book.html"},{"m":"S7","slug":"12-relativity","title":"狭义相对论","tags":["洛伦兹变换","同时性","四维动量","不变质量"],"summary":"由光速不变与相对性原理建立洛伦兹变换，串联同时性、时空间隔与光锥、相对论多普勒效应与四维动量动力学。","href":"chapters/07-relativity/index.html","pdf":"chapters/07-relativity/manuscripts/book.html"},{"m":"M31","slug":"31-rocket-massflow","title":"火箭方程与质量流","tags":["火箭方程","质量流","动量通量","齐奥尔科夫斯基"],"summary":"将喷气动量通量计入开放系统，导出齐奥尔科夫斯基火箭方程 $Δ v=v_eln(m_0/m)$，分析质量比与推进剂占比。","href":"modules/31-rocket-massflow/index.html","pdf":"modules/31-rocket-massflow/note.html"},{"m":"M32","slug":"32-two-link-jacobian","title":"二连杆雅可比与奇异位形","tags":["雅可比","奇异位形","机械臂","自由度"],"summary":"以二连杆机械臂演示位形映射 $=Jδθ$，当 $det J=l_1l_2sinθ_2=0$ 时出现奇异位形与自由度退化。","href":"modules/32-two-link-jacobian/index.html","pdf":"modules/32-two-link-jacobian/note.html"},{"m":"M33","slug":"33-rolling-cylinder","title":"圆柱沿斜面纯滚动","tags":["纯滚动","静摩擦","惯量","斜面"],"summary":"引入无量纲惯量系数 $k=I/(mR^2)$ 分析圆柱沿斜面纯滚动，给出加速度 $a=(gsinα)/(1+k)$ 与不打滑条件 $μ≥(ktanα)/(1+k)$。","href":"modules/33-rolling-cylinder/index.html","pdf":"modules/33-rolling-cylinder/note.html"},{"m":"M34","slug":"34-compton-scattering","title":"康普顿散射运动学","tags":["康普顿散射","四动量","波长增量","反冲电子"],"summary":"用四动量守恒推导康普顿散射波长增量 $Δλ=λ_C(1-cosθ)$ 与反冲电子能量分布。","href":"modules/34-compton-scattering/index.html","pdf":"modules/34-compton-scattering/note.html"},{"m":"M35","slug":"35-lattice-dispersion","title":"周期链色散与群速度","tags":["色散关系","群速度","波包","长波极限"],"summary":"将离散质量链推广至无限周期晶格，导出色散关系 $ω(k)=2√(K/m) |sin(ka/2)|$、群速度 $v_g$ 与长波声速极限。","href":"modules/35-lattice-dispersion/index.html","pdf":"modules/35-lattice-dispersion/note.html"},{"m":"M36","slug":"36-virial-power-law","title":"位力定理与幂次势","tags":["位力定理","幂次势","时间平均","束缚运动"],"summary":"对幂次中心势 $V∝ r^n$ 的束缚轨道做数值时间平均，实时验证位力定理 $2⟨ T⟩=n⟨ V⟩$。","href":"modules/36-virial-power-law/index.html","pdf":"modules/36-virial-power-law/note.html"},{"m":"M37","slug":"37-catenary-min-energy","title":"悬链线与最小势能","tags":["悬链线","最小势能","双曲余弦","张力"],"summary":"在绳长约束下极小化均匀柔绳的重力势能，导出悬链线方程 $y=acosh(x/a)$，反解参数 $a=T_0/(λ g)$ 与张力分布。","href":"modules/37-catenary-min-energy/index.html","pdf":"modules/37-catenary-min-energy/note.html"},{"m":"M38","slug":"38-three-atom-modes","title":"三原子链简正模","tags":["简正模","本征频率","相位","耦合振子"],"summary":"对三原子耦合质量链做质量加权对角化，求解三种离散简正振型与本征频率 $ω_p=2√(K/m)sin(pπ/8)$。","href":"modules/38-three-atom-modes/index.html","pdf":"modules/38-three-atom-modes/note.html"},{"m":"M39","slug":"39-physical-pendulum-period","title":"复摆周期与最短摆长","tags":["复摆","转动惯量","小角周期","大角修正"],"summary":"结合平行轴定理导出均匀杆复摆小角周期 $T_0=2π√((L^2/12+d^2)/(gd))$，求最短周期悬点 $d=L/√(12)$ 与大角修正。","href":"modules/39-physical-pendulum-period/index.html","pdf":"modules/39-physical-pendulum-period/note.html"},{"m":"M40","slug":"40-threshold-collider","title":"固定靶阈能与对撞机","tags":["阈能","对撞机","四动量","不变量s"],"summary":"利用四动量不变量 $s=(∑ E)^2-()^2$ 定量对比固定靶（$E∝ M^2$）与对撞机（$E∝ M$）产生重粒子所需的束流阈能。","href":"modules/40-threshold-collider/index.html","pdf":"modules/40-threshold-collider/note.html"}],"faq":[{"q":"什么是有效势？为什么能判断圆轨道稳定性？","a":"有效势把角动量项并进势能：$V_{eff}(r)=V(r)+L^2/(2mr^2)$。圆轨道要求 $V_{eff}'(r_0)=0$；若 $V_{eff}''(r_0)>0$，小扰动以 $\\omega_r=\\sqrt{V_{eff}''/m}$ 振动，轨道稳定；若小于 0 则不稳定。到 M1 拖 E 与 L 看曲线就明白了。","m":"M1","sec":"有效势"},{"q":"伯特兰定理是什么？","a":"在所有束缚轨道都闭合的中心力势中，只有两种幂律势：$V\\propto -1/r$（引力）与 $V\\propto r^2$（弹簧）。频率比 $\\omega_r/\\omega_\\theta=\\sqrt{k+2}$；只有 k=-2 与 k=2 给出有理比。","m":"M1","sec":"伯特兰定理"},{"q":"水星近日点进动对应广义相对论的哪个修正项？","a":"GR 的最低阶修正是 $u^2$ 项：$u''+u=GM/h^2+3GM\\,u^2/c^2$，不是 $u^3$。真实水星进动约 $5.02\\times10^{-7}$ rad/圈。页面里的 $\\mu u^3$ 是唯象进动项，用来演示“椭圆不闭合”，不要把它当成 GR。","m":"M0","sec":"GR 修正"},{"q":"离心势垒是什么？","a":"有效势里的 $L^2/(2mr^2)$ 在中心附近形成一堵“墙”，L 越大墙越高。高斯势 $V=-e^{-r^2/2}$ 的势垒只在 $L<2\\sqrt2/e\\approx1.04$ 时存在；超过它，势垒消失，粒子直坠中心。","m":"M1","sec":"离心势垒"},{"q":"散射截面为什么有时显示无穷大？","a":"对 $k/r^2$ 这种长程势，再远的粒子也会被偏转；前向 $\\Theta\\to0$ 的 $1/\\Theta^3$ 峰使总截面发散，所以显示“无有限截面”。这是物理结论，不是程序错误。","m":"M2","sec":"俘获截面"},{"q":"两体问题怎么化成单体？","a":"用约化质量 $\\mu=m_1m_2/(m_1+m_2)$ 和相对坐标 $r=r_1-r_2$，两体就化为“一个假想粒子绕固定中心转”。开普勒第三定律里的质量要用总质量 $M_1+M_2$。","m":"M3","sec":"约化质量"},{"q":"系外行星的 K 和 Δλ 是什么？","a":"恒星也绕共同质心转。视向速度半振幅 $K=\\frac{M_2}{M_1+M_2}\\frac{2\\pi a}{P\\sqrt{1-e^2}}\\sin i$；$\\Delta\\lambda$ 是 500nm 星光的多普勒偏移。到 M3 拖大 M2，看恒星小圈和 K 一起变大。","m":"M3","sec":"视向速度"},{"q":"等时摆为什么等时？","a":"沿摆线（cycloid）摆动时周期与振幅无关，是严格等时；普通单摆只在小角度近似等时。M8 里有不同高度的小球同时到达的演示。","m":"M8","sec":"等时摆"},{"q":"最速降线为什么不是直线？","a":"直线最短，但下降慢；摆线（brachistochrone）让小球先快速获得速度，整体用时更短。“更短 ≠ 更快”正是变分法的魅力。","m":"M8","sec":"最速降线"},{"q":"虚功原理为什么能求平衡？","a":"约束力不做功。给系统一个符合约束的虚位移，平衡时总虚功 $\\delta W=0$，于是广义力 $Q=0$；不用解出所有约束力就能得到平衡条件。","m":"M11","sec":"虚功"},{"q":"梯子临界角怎么推？","a":"力平衡给出 $N_w=P/(2\\tan\\theta)$，摩擦临界 $f=\\mu P=N_w$，所以 $\\tan\\theta_{min}=1/(2\\mu)$。临界是摩擦饱和，不是势能 Hessian 奇异。","m":"M11","sec":"梯子"},{"q":"恢复系数是什么？e=0 会粘住吗？","a":"$e$ 是碰后沿连心线的分离速度与碰前接近速度之比。光滑球 $e=0$ 只让法向速度相等，切向仍保留，所以一般不会粘住：$\\beta=\\arctan(2\\tan\\alpha)-\\alpha$，只有正碰 $\\alpha=0$ 才 $\\beta=0$。","m":"M4","sec":"恢复系数"},{"q":"雨滴为什么越落越快？","a":"雨滴质量随时间增加（$r=r_0+\\lambda t$），重力持续加速；在“静止雨水”模型（$u=0$）下 $v\\sim gt/4$，没有终端速度。","m":"M4","sec":"雨滴"},{"q":"转动惯量是什么？","a":"$I=\\sum mr^2$，是“难不难被转起来”的量度，地位相当于平动里的质量；平行轴定理 $I=I_{cm}+md^2$。","m":"M18","sec":"转动惯量"},{"q":"甲虫绕环一圈为什么环反转 120°、甲虫实验室方位转 240°？","a":"角动量守恒：自由环 $M=1$、甲虫 $m=1$ 时，环反转 $\\Delta\\theta_{\\rm ring}=-2\\pi m/(M+2m)=-120^\\circ$，甲虫相对质心的实验室方位转 $2\\pi(M+m)/(M+2m)=240^\\circ$（不是环只转 $180^\\circ$）。M18 的甲虫模式可以看拖尾与角度读数。","m":"M18","sec":"甲虫"},{"q":"球壳内部为什么没有引力？","a":"均匀球壳内部各方向引力抵消，势为常数 $-GM/R$，场强为零；壳外才等效为全部质量集中在球心。","m":"M18","sec":"球壳"},{"q":"圆柱脱离角为什么总是 48.19°？","a":"脱离条件 $N=0$ 给出 $\\cos\\theta=2/3$，所以 $\\theta=\\arccos(2/3)=48.19^\\circ$，与质量、半径、g 都无关。","m":"M5","sec":"圆柱脱离"},{"q":"单摆周期为什么随振幅变大？","a":"大角度不是简谐，周期 $T\\approx T_0(1+\\theta_0^2/16+\\cdots)$，振幅越大周期越长；小角度才近似等时。","m":"M16","sec":"单摆"},{"q":"双摆为什么混沌？","a":"对初值极端敏感：两条几乎相同的释放轨迹会指数分离；能量仍守恒，但长期不可预测。M17 的双摆模式能直接看到分道扬镳。","m":"M17","sec":"双摆"},{"q":"洛伦兹力和洛伦兹变换有什么区别？","a":"洛伦兹力 $F=-e(E+v\\times B)$ 描述电荷受力；洛伦兹变换是狭义相对论里两个惯性系的时间/坐标换算。两者不是一回事。","m":"M5","sec":"Lorentz 力"},{"q":"学理论力学先看哪章？","a":"推荐顺序：M0 比奈 → M1 有效势 → M2 散射 → M3 两体 → M4 碰撞 → M5 圆柱脱离 → M8 等时摆 → M11 虚功 → M12 Atwood → M13 斜面滑块 → M18 刚体几何 → M19 自由刚体 → M20 圆环珠子 → M22 相空间 → M24 光锥 → M25 多普勒。每章先读网页推导，再拖主滑块做实验。","m":"M0","sec":"学习路径"},{"q":"这些模拟用的是什么单位？","a":"多数是无量纲演示单位（如 $G=M=1$、$m=1$、$L=1$），方便看规律；真实单位的换算在推导网页版的数值例子里。","m":"M1","sec":"单位"},{"q":"为什么行星轨道是椭圆？","a":"平方反比引力下，比奈方程给出圆锥曲线：$e<1$ 椭圆、$e=1$ 抛物线、$e>1$ 双曲线。M0 改 λ/μ 可以看到轨道闭合与进动。","m":"M0","sec":"圆锥曲线"},{"q":"什么是掠面速度/开普勒第二定律？","a":"行星与中心连线单位时间扫过的面积 $dA/dt=L/(2m)$ 恒定，所以近心点快、远心点慢；这是角动量守恒的几何表述。","m":"M0","sec":"掠面速度"},{"q":"拉格朗日方程是什么？","a":"拉格朗日方程是 $\\frac{d}{dt}\\frac{\\partial L}{\\partial \\dot q}-\\frac{\\partial L}{\\partial q}=0$，其中 $L=T-V$。它从能量出发，自动处理约束，比逐個画受力更适合复杂系统；M8–M10 的变分法就是它的来源。","m":"M8","sec":"拉格朗日方程"},{"q":"最小作用量原理是什么？","a":"系统真实运动使作用量 $S=\\int L\\,dt$ 取驻值（$\\delta S=0$）。对 $S$ 做变分就得到拉格朗日方程；这是分析力学的核心出发点。","m":"M8","sec":"最小作用量"},{"q":"费马原理是什么？","a":"光走“时间最短”的路径。把时间写成路径的泛函并取驻值，就得到折射定律 $n_1\\sin\\theta_1=n_2\\sin\\theta_2$；M9 的折射模式可以直接拖折射率看光线弯折。","m":"M9","sec":"费马原理"},{"q":"角动量守恒是什么？","a":"合外力矩为零时，角动量 $L$ 保持不变。中心力场中 $L=mr^2\\dot\\theta$ 恒定，所以行星近心点快、远心点慢——这就是开普勒第二定律。","m":"M0","sec":"角动量守恒"},{"q":"平行轴定理是什么？","a":"$I=I_{cm}+md^2$：绕任意平行轴的转动惯量，等于绕质心轴的转动惯量加上 $md^2$。M18 的球壳/圆盘模式会用到它。","m":"M18","sec":"平行轴定理"},{"q":"简谐振动和阻尼振动有什么区别？","a":"简谐：$x''+\\omega_0^2x=0$，等幅振荡；阻尼：$x''+2\\gamma x'+\\omega_0^2x=0$，振幅指数衰减。M16 的单摆大角度还会出现周期随振幅变长。","m":"M27","sec":"阻尼振动"},{"q":"伽利略变换和洛伦兹变换有什么区别？","a":"伽利略变换 $x'=x-Vt$ 是低速近似；洛伦兹变换在接近光速时修正时间与长度。M5 所在的运动学模块讲的是洛伦兹力 $F=-e(E+v\\times B)$，不要和洛伦兹变换混为一谈。","m":"S7","sec":"参考系变换"},{"q":"M4 的两个球为什么现在会碰上了？","a":"碰撞判定改用真实半径 $R$，并用二维法向冲量求解；视觉半径与物理半径一致，还加了 0.5s 接触停顿与闪光。","m":"M4","sec":"碰撞接触"},{"q":"球冠高度 h 为什么可以到 2R？","a":"切割平面距球心 $b=R-h$，$b$ 可以从 $R$ 变到 $-R$，所以 $h$ 的范围是 $[0,2R]$；$h>R$ 时球冠超过半球，$h=2R$ 就是整个球。M18 的滑块上限已按直径 2R 限制。","m":"M18","sec":"球冠"},{"q":"HUD 里的数字和单位怎么看？","a":"多数模拟用无量纲演示单位（如 $G=M=1$、$m=1$、$L=1$），方便看规律；HUD 标签已写成“中文 + 符号”，真实单位换算在推导网页版的数值例子里。","m":"M1","sec":"单位"},{"q":"最大偏转角 β_max 怎么来的？","a":"对 $\\beta=\\arctan(2\\tan\\alpha)-\\alpha$ 求极值，得 $\\tan^2\\alpha=(1-e)/2$。$e=0$ 时 $\\beta_{max}=19.47^\\circ$，$e=0.5$ 时约 $36.87^\\circ$。","m":"M4","sec":"最大偏转"},{"q":"俘获截面怎么理解？","a":"$\\sigma=\\pi b_c^2$ 是一张“有效靶面积”：瞄准距离 $b<b_c$ 的入射粒子都会被势场俘获。M2 可以切到俘获模式拖 b 看螺旋。","m":"M2","sec":"俘获截面"},{"q":"为什么轨道会进动？","a":"当势不是严格的 $1/r^2$（例如加了 $\\lambda u^2$ 或 $\\mu u^3$ 修正），轨道不再闭合，近心点每圈转过一个角度，这就是进动。M0 拖 λ/μ 可以直接看。","m":"M0","sec":"进动"},{"q":"诺特定理是什么？","a":"每种连续对称性对应一个守恒量：时间平移对应能量，空间平移对应动量，旋转对应角动量。讲义没有展开证明，但 M8–M10 的变分法与 M18 的角动量守恒都用到了这个思想。","m":"M8","sec":"诺特定理"},{"q":"开普勒第一定律是什么？","a":"行星轨道是椭圆，太阳位于一个焦点上。它来自平方反比引力下的比奈方程；偏心率 $e<1$ 就是椭圆，$e=1$ 抛物线，$e>1$ 双曲线。","m":"M0","sec":"开普勒第一定律"},{"q":"开普勒第二定律是什么？","a":"行星与太阳连线单位时间扫过的面积恒定（掠面速度守恒），所以近心点快、远心点慢；本质是角动量守恒。","m":"M0","sec":"开普勒第二定律"},{"q":"开普勒第三定律是什么？","a":"$P^2=\\frac{4\\pi^2 a^3}{G(M_1+M_2)}$；太阳系里近似为 $T^2\\propto a^3$。两体问题里质量要用总质量 $M_1+M_2$。","m":"M3","sec":"开普勒第三定律"},{"q":"中心力是什么？","a":"力只沿径向（指向或背离中心），横向分力为零；因此角动量 $L=mr^2\\dot\\theta$ 守恒，轨道在一平面内，开普勒第二定律成立。","m":"M0","sec":"中心力"},{"q":"比奈方程是什么？","a":"把 $u=1/r$ 代入中心力径向方程得到 $u''+u=-F(1/u)/(m h^2u^2)$（$h=L/m$）。它把轨道形状与力律直接联系起来，是 M0 的主方程。","m":"M0","sec":"比奈方程"},{"q":"微分散射截面是什么？","a":"$d\\sigma/d\\Omega=(b/\\sin\\Theta)|db/d\\Theta|$：把“瞄准距离在 $b\\sim b+db$ 的粒子”映射到“散射到 $\\Theta\\sim\\Theta+d\\Theta$ 的立体角”，是散射实验的核心观测量。","m":"M2","sec":"微分散射截面"},{"q":"什么是混沌？","a":"确定性系统对初值极端敏感：两条几乎相同的轨迹会指数分离。双摆就是典型例子——能量仍守恒，但长期运动不可预测。M17 的双摆模式能直接看到两条轨迹分道扬镳。","m":"M17","sec":"混沌"},{"q":"Lorentz 力的漂移方向怎么判断？","a":"漂移速度 $v_d=E\\times B/B^2$，方向由右手定则给出。例如 $E=E\\hat y$、$B=B\\hat z$ 时 $\\hat y\\times\\hat z=\\hat x$，漂移沿 $+x$。运动学模块的 Lorentz 模式会画出电子轨迹。","m":"M5","sec":"Lorentz 漂移"},{"q":"什么是变质量系统？","a":"质量随时间变化的系统，方程是 $d(mv)/dt=F+u\\,dm/dt$，$u$ 是加入质量的绝对速度。雨滴取 $u=0$（静止雨水），得到 $v\\sim gt/4$。","m":"M4","sec":"变质量"},{"q":"相空间的分界线是什么？","a":"单摆相图里分隔“振荡”和“旋转”的临界轨道：$E=mgL$，对应刚好到达最高点 $\\theta=\\pi$ 且速度为零。$E<mgL$ 振荡，$E>mgL$ 旋转。","m":"M16","sec":"分界线"},{"q":"有转动惯量的 Atwood 机，加速度怎么算？","a":"取 $m_2$ 向下位移 $s$，$L=\\frac12(m_1+m_2+I/R^2)\\dot s^2+(m_2-m_1)gs$，故 $a=\\frac{(m_2-m_1)g}{m_1+m_2+I/R^2}$。$I/R^2$ 相当于附加质量。","m":"M12","sec":"等效质量"},{"q":"为什么有转动惯量的滑轮两端张力不相等？","a":"滑轮需要角加速度：$(T_2-T_1)R=I\\alpha$，绳不打滑 $\\alpha=a/R$，所以 $T_2-T_1=Ia/R^2$；$I=0$ 时退化为 $T_1=T_2$。","m":"M12","sec":"张力差"},{"q":"Atwood 机里 I 变大，加速度怎么变？","a":"分母 $m_1+m_2+I/R^2$ 变大，$a$ 变小；当 $m_1=m_2$ 时仍有 $a=0$，但张力差随 $I$ 增大。","m":"M12","sec":"转动惯量"},{"q":"斜面滑块为什么水平方向动量守恒？","a":"地面光滑，水平方向无外力，$p_X=(M+m)\\dot X+m\\dot s\\cos\\alpha=0$。由此 $a_{\\rm rel}=\\frac{(M+m)g\\sin\\alpha}{M+m\\sin^2\\alpha}$，$a_X=-\\frac{mg\\sin\\alpha\\cos\\alpha}{M+m\\sin^2\\alpha}$。","m":"M13","sec":"循环坐标"},{"q":"弹簧摆的平衡位置和两个小振动频率是什么？","a":"平衡 $r_0=l_0+mg/k$；径向 $\\omega_r=\\sqrt{k/m}$，摆角 $\\omega_\\theta=\\sqrt{g/r_0}=\\sqrt{g/(l_0+mg/k)}$。","m":"M14","sec":"小振动"},{"q":"小车单摆的小振动频率是多少？","a":"水平动量守恒后线性化得 $\\omega=\\sqrt{\\frac{g(M+m)}{Ml}}$；$M\\to\\infty$ 时回到 $\\sqrt{g/l}$。","m":"M15","sec":"小振动"},{"q":"旋转圆环上的珠子临界角速度是多少？","a":"有效势给出 $\\Omega_c=\\sqrt{g/R}$。$\\Omega<\\Omega_c$ 时 $\\theta=0$ 稳定；$\\Omega>\\Omega_c$ 时 $\\theta=0$ 失稳，出现 $\\theta_{\\rm eq}=\\arccos\\!\\left(g/(\\Omega^2R)\\right)$。","m":"M20","sec":"临界角速度"},{"q":"雅可比积分和机械能有什么区别？","a":"$\\mathcal E=\\frac12mR^2\\dot\\theta^2-\\frac12mR^2\\Omega^2\\sin^2\\theta-mgR\\cos\\theta$ 守恒；机械能 $E_{\\rm mech}=\\mathcal E+mR^2\\Omega^2\\sin^2\\theta$ 不守恒，差值是电机维持 $\\Omega$ 输入的功。","m":"M20","sec":"雅可比积分"},{"q":"磁场中的诺特荷和回旋圆心是什么？","a":"$Q_x=m\\dot x-qBy$，$Q_y=m\\dot y+qBx$ 守恒；回旋圆心 $X_c=x+\\dot y/\\omega_c$，$Y_c=y-\\dot x/\\omega_c$，满足 $Q_y=m\\omega_cX_c$、$Q_x=-m\\omega_cY_c$，$\\omega_c=qB/m$。","m":"M21","sec":"诺特荷"}],"glossary":[{"t":"有效势","d":"真实势能与角动量项 L²/2r² 合成的曲线，把二维轨道变成“小球沿曲线滚动”的一维问题。","m":"M1"},{"t":"离心势垒","d":"有效势里因角动量在中心附近凸起的部分，像一堵墙，拦着带角动量的粒子掉进中心。","m":"M1"},{"t":"掠面速度","d":"行星与中心连线单位时间扫过的面积；中心力场里它不变，这就是开普勒第二定律。","m":"M0"},{"t":"伯特兰定理","d":"所有束缚轨道都闭合的中心力势只有两种：牛顿引力（∝1/r²）与弹簧（∝r²）。","m":"M1"},{"t":"约化质量","d":"μ=m₁m₂/(m₁+m₂)：把两个天体互绕化成“一个假想粒子绕固定中心转”的换算质量。","m":"M3"},{"t":"恢复系数","d":"e＝碰后沿连心线的分离速度与碰前接近速度之比：e=1 完全弹性，e=0 碰后法向速度相同（不是粘住）。","m":"M4"},{"t":"虚功","d":"给系统一个符合约束的“想象中的”微小位移时各力做的功；总虚功为零即平衡。","m":"M11"},{"t":"广义力","d":"虚功 Q·δq 中与每个广义坐标配对的 Q：它推动这个坐标，但不必是牛顿意义上的力。","m":"M11"},{"t":"转动惯量","d":"I=Σmr²：物体“难不难被转起来”的量度，地位相当于平动里的质量。","m":"M18"},{"t":"等时摆","d":"周期与摆幅无关的摆：单摆只在小角度近似等时，沿摆线摆动则严格等时。","m":"M8"},{"t":"洛伦兹变换","d":"两个相对匀速运动的观测者之间换算时间与坐标的公式（注意与“洛伦兹力”是两回事）。","m":"S7"},{"t":"俘获截面","d":"σ=πb_c²：一张“有效靶面积”，入射粒子瞄准进来就必被势场俘获。","m":"M2"},{"t":"等效质量","d":"Atwood 机里把滑轮转动惯量折算成平动质量：m₁+m₂+I/R²。","m":"M12"},{"t":"循环坐标","d":"拉格朗日量中不显含的广义坐标；对应的共轭动量守恒（如斜面滑块的水平动量）。","m":"M13"},{"t":"内共振","d":"弹簧摆的 ω_r≈2ω_θ 时，两自由度非线性耦合出现拍频与能量交换。","m":"M14"},{"t":"雅可比积分","d":"旋转参考系中守恒的能量型量 E−ΩL_z；与惯性系机械能相差电机输入功。","m":"M20"},{"t":"诺特荷","d":"连续对称性对应的守恒量；均匀磁场中平移对称性给出的 Q_x、Q_y 锁定回旋圆心。","m":"M21"},{"t":"回旋圆心","d":"带电粒子在均匀磁场中圆周运动的圆心；由 Q_x、Q_y 守恒确定。","m":"M21"}],"chunks":[{"m":"M0","sec":"模块概览","t":"从极坐标下的牛顿第二定律出发，利用中心力场角动量守恒 $L=mr^2θ=const$，引入倒数半径变量 $u(θ)=1/r$，消去时间即得比奈方程（Binet equation）： $$d^2 udθ^2 + u = -(F(1/u))/(m h^2 u^2), h=(L)/(m)$$ ### 核心物理图像 - 当 $F(r)=-GMm/r^2$ 时，方程化为常系数线性方程 $u''+u=GM/h^2$，通解给出圆锥曲线轨道 $r=(p)/(1+ecos(θ-θ_0))$。 - 偏心率 $e=√(1+(2EL^2)/(G^2M^2m^3))$ 由总能量 $E$ 直接决定轨道类型（圆、椭圆、抛物线、双曲线）。 - 若平方反比力叠加微小摄动 $δ F∝ r^-3$ 或 $r^-4$，轨道不再闭合，产生近日点进动。"},{"m":"M0","sec":"书稿精读","t":"【定理】幂次中心力圆轨道稳定性。线性化得ξ″+(3-n)ξ=0，仅n<3时圆轨道稳定。（书稿 ch01.tex:2373）"},{"m":"M0","sec":"万有引力与圆锥曲线轨道","t":"对行星绕太阳运动，万有引力为 F_r(r) = -GMmr^2 = -GMm u^2 其中 $G$ 为引力常量，$M$ 为太阳质量，负号表示吸引力。 代入比奈方程 式（binet）： u''+u = -m(-GMm u^2)L^2u^2 = GMm^2L^2 . 定义 p ≡ L^2GMm^2 则方程化为常系数线性方程 d^2udθ^2 + u = (1)/(p) 其通解为 u(θ) = (1)/(p) + Acosθ + Bsinθ 其中 $A,B$ 为积分常数。令 A = (e)/(p)cosθ_0 B = (e)/(p)sinθ_0 则 u(θ) = (1)/(p)[1+ecos(θ-θ_0)] 从而 r(θ) = (p)/(1+ecos(θ-θ_0)) 这正是圆锥曲线的极坐标方程，其中 $p$ 为半通径， $e≥ 0$ 为偏心率，$θ_0$ 为轨道近心点方向。"},{"m":"M0","sec":"角动量守恒","t":"对中心力场，力只沿径向，横向分力为零： F_θ = 0 . 由式（transverse） 得 m(2rθ + rθ)=0 . 注意到 (d)/(dt)(r^2θ) = 2rrθ + r^2θ = r(2rθ + rθ) 于是 (d)/(dt)(m r^2θ)=0 . 定义角动量 L ≡ m r^2θ = 常量. 式（L） 由此可得角速度与半径的关系 θ = Lm r^2 . 这正是开普勒第二定律（面积定律）的微分形式。"},{"m":"M0","sec":"轨道类型与偏心率","t":"由式（conic） 可知，轨道类型完全由偏心率 $e$ 决定： · 偏心率 | 轨道类型 | 说明 · $e=0$ | 圆 | 半径 $r=p$ 的圆周运动 · $0<e<1$ | 椭圆 | 行星、多数卫星的轨道 · $e=1$ | 抛物线 | 临界逃逸轨道 · $e>1$ | 双曲线 | 非束缚的散射轨道 对于椭圆轨道，半长轴 $a$ 与半通径 $p$ 满足 p = a(1-e^2) 近日点与远日点距离分别为 r_min=(p)/(1+e)=a(1-e) r_max=(p)/(1-e)=a(1+e). 偏心率与总能量 $E$ 的关系为 e = 1+2E L^2G^2M^2m^3 . 当 $E<0$ 时 $e<1$，轨道为椭圆；当 $E=0$ 时 $e=1$； 当 $E>0$ 时 $e>1$。这体现了能量对轨道束缚性质的判据。 将已得的轨道解代入机械能即可消去极角。 r=-(L)/(m)u', u'=-(e)/(p)sin(θ-θ_0) E=(L^2)/(2m)[(u')^2+u^2]-GMm u E=(L^2)/(2mp^2)(e^2-1)=(G^2M^2m^3)/(2L^2)(e^2-1) e^2=1+(2EL^2)/(G^2M^2m^3)"},{"m":"M0","sec":"书稿精读","t":"【定理】开普勒三定律与能量-偏心率关系。平方反比轨道为圆锥曲线，E的符号决定束缚、临界与散射。（书稿 ch01.tex:2232）"},{"m":"M0","sec":"比奈方程的推导","t":"引入新变量 u ≡ (1)/(r), 即 r=(1)/(u). 记 $u'=(du)/(dθ)$，$u''=d^2udθ^2$。 由链式法则与式（thetadot）， u = (du)/(dθ)θ = u' θ 而 r = -1u^2u = -u'u^2θ . 代入 $θ = (L)/(m)u^2$，得 r = -u'u^2·(L)/(m)u^2 = -(L)/(m)u' . 对式（rdot） 再求时间导数： r = -(L)/(m)(d u')/(dt) = -(L)/(m)u''θ = -(L)/(m)u''·(L)/(m)u^2 即 r = -L^2m^2u^2u'' 同时 rθ^2 = (1)/(u)((L)/(m)u^2)^2 = L^2m^2u^3 . 将式（rddot） 与式（rthetadot2） 代入径向方程 式（radial）： m(-L^2m^2u^2u'' - L^2m^2u^3)=F_r 整理得 -L^2mu^2(u''+u)=F_r . 两边同除以 $-L^2mu^2$，得到比奈方程： d^2udθ^2 + u = -m F_r(1/u)L^2u^2 其中 $F_r(1/u)$ 表示把径向力 $F_r(r)$ 中的 $r$ 用 $1/u$ 替换。 式（binet） 把二维轨道问题化为一维关于 $u(θ)$ 的常微分方程。"},{"m":"M1","sec":"模块概览","t":"在中心力场中，角动量守恒将二维平面运动约化为径向一维运动，引入包含离心势的有效势： $$V_eff(r) = V(r) + (L^2)/(2mr^2), E = (1)/(2)mr^2 + V_eff(r)$$ ### 曲线几何与轨道判据 - **圆轨道条件**：极值点满足 $V'_eff(r_0)=0$；若二阶导 $V''_eff(r_0)>0$，则圆轨道稳定，径向小振动频率为 $ω_r=V''_eff(r_0)/m$。 - **伯特兰定理**：在所有中心幂次势中，只有开普勒势 $V∝ -1/r$ 与各向同性谐振子势 $V∝ r^2$ 能令一切束缚轨道严格闭合。 - **势垒与逃逸**：高阶吸引项或高斯势在高角动量下会出现有限势垒甚至失去极小值，决定粒子的束缚窗口与坠落阈值。"},{"m":"M1","sec":"作业映射","t":"本模块覆盖以下作业题（题面为原文简述，记号与原文一致；公式均已在原文中给出或要求证明）： · 来源 | 题面简述 | 核心知识点 | 对应小节 · 作业-2 Q1 | 判断 $F(r)=F(r)e_r$ 是否保守 | 保守力判据、旋度、环路做功 · 作业-2 Q2 | 线性力场 $F_i=∑_j a_ijx_j$（$a_ij$ 常数）：满足什么条件才有势能？求其势能 | 旋度为零 $$ 系数矩阵对称 · 作业-2 Q3 | 高斯势 $V=-V_0e^-λ^2r^2$：(a) 给定 $L$ 何时存在稳定圆轨道；(b) 证明 $L$ 过大时不存在圆轨道，求允许的最大角动量 | 有效势极值与二阶判据、临界 $L$ · 作业-2 Q4 | 幂律势 $V=β r^k$：求圆轨道半径 $r_0$ 与径向振动频率 $ω_r$；设 $a=ω_r/ω_θ$，求 $a=1$ 与 $a=2$ 对应的势能 | 圆轨道、径向小振动、闭合条件 · 作业-2 Q5 | 抛物线彗星近日点为地球轨道半径的 $1/n$：证其在地球轨道内停留时间为 $T_E(2(n+2))/(3π n)√((n-1)/(2n))$，并证最长停留为 $(2)/(3π)$ 年 | 面积定律、抛物线轨道几何 · 作业-2 Q6 | 平方反比引力场中沿椭圆运动，最大角速度与最小角速度之比为 $n$：证离心率 $e=( n-1)/( n+1)$ | 角动量守恒、近/远心点 · 作业-2 Q7 | $V=-α/r$（轨道 $r=p/(1+ecosθ)$）加小修正 $δ V$ 后轨道不再闭合，每圈近心点改变小角度 $δθ$：求 (a) $δ V"},{"m":"M1","sec":"数值验证","t":"各项的实验设置与要点： · $r_0$（牛顿法）：对 $V_eff'(r)=α/r^2-L^2/r^3=0$ 牛顿迭代（$α=1$，$L=1.2$，初值 $0.8$，8 步）， 残差 $|V_eff'(r_0)|=1.110×10^-16<10^-9$（机器精度）。 · $ω_r$（近圆轨道）：初始 $r(0)=r_0+δ$、$r(0)=0$， RK4 积分约 20 个径向周期，用抛物线顶点定位相邻 $r$ 极大， $ω_r=2π/T_r$。Kepler（$r_0=L=α=1$）解析值 $V_eff''(r_0)=1$；高斯势（$r_0=1$， $L=√(2/e)$）解析值 $2/√(e)=1.2130613$。 两行偏差 $1.47×10^-4$、$7.21×10^-5$ 是有限振幅的 $O(δ^2)$ 修正（Kepler 行恰为 $32δ^2=1.5×10^-4$，见 第 derive 节 节 式（omegar） 的适用条件），不是积分误差。 · 频率比 $a$：幂律势取 $β=1/k$、$L=1$、$r_0=1$ （此时 $ω_θ=1$），$δ=0.01$，积分 10 个径向周期， $a=2π/Δθ$（$Δθ$ 为相邻远心点极角差）。 $k=-1$（Kepler）与 $k=2$（谐振子）的轨道对所有振幅严格闭合， 误差为机器精度 $10^-13$；$k=1$ 的 $8.2×10^-6$ 同样是 $O(δ^2)$ 修正。 · 进动 $δθ$：直接积分比奈方程 （$u(0)=(1+e)/p=1.3$，$u'(0)=0$，$e=0.3$，$p=1$ $h_θ=2π/5000$，"},{"m":"M1","sec":"讨论","t":"极限行为。 $k→-2^+$ 时 $a=√(k+2)→0$：径向振动频率趋于零， 圆轨道趋于临界稳定（这与高斯势 $L→ L_max^-$ 时 $ω_r→0$、$r_0→2/λ$ 的行为一致）。 $e→0$ 时进动公式（precessgamma） 仍有限 （一阶 $γ/r^3$ 进动与 $e$ 无关，与广义相对论进动仅依赖 $p$ 一致）。 彗星问题中 $n→1^+$ 时 $t→0$（掠射），$n→∞$ 时 $t→(2)/(3π)T_E≈0.150 T_E$（径向往返极限，有限值）； $t_max=(2)/(3π)T_E$ 在 $n=2$ 取得，是货真价实的内部极大。 误差来源。 三类偏差各有明确量级：(i) RK4 截断误差 $O(h^4)$——20 个周期能量漂移 $2.6×10^-14$；(ii) 周期测量的抛物线顶点误差 $O(h^2)$—— 被闭合轨道行的 $10^-13$ 水平证实；(iii) 模型本身的近似—— 小振动 $O(δ^2)$（Kepler 行 $1.47×10^-4≈32δ^2$） 与一阶摄动 $O(γ)$（$γ/r^3$ 行 $1.5×10^-2$， $γ$ 减半偏差比 $1.983$）。数值验证的价值正在于把 (iii) 与 (i)(ii) 清楚地区分开。 与作业题的对照。 表 numeric 覆盖了 第 map 节 节全部 9 道题的核心结论： 作业-2 Q3 的 $L_max=2√(2mV_0)/(λ e)$（二分法复现到 $4.5×10^-15$）；Q4 的 $a=√(k+2)$ 与 $a=1,2$ 对应 $k=-1,2$； Q5 的停留时间"},{"m":"M1","sec":"模型与假设","t":"考虑质量为 $m$ 的质点在中心力场中运动。以力心为原点建立平面极坐标 $(r,θ)$ （角动量守恒保证运动限于一个平面，见 veff 小节）， 位矢 $r=re_r$，$e_r$ 为径向单位矢量， $e_θ$ 为横向单位矢量。基本假设与适用条件如下： · 有心力假设：$F=F(r)e_r$，力的大小只依赖 $r$。 这排除了各向异性与耗散性；何时这样的力存在势能，由 conservative 小节的判据回答（作业-2 Q1/Q2）。 · 保守力假设：所考虑的力场在 $r>0$ 的单连通区域内旋度为零， 从而存在势能 $V(r)$，$F=-∇ V$。 力心处的奇点（如 $1/r$ 型势）不影响 $r>0$ 区域内的全部结论。 · 单位制：解析推导保留 $m$ 与各势参数（$α$、$β$、$k$、$V_0$、$λ$ 等）； 数值验证统一取无量纲约定 $m=1$、Kepler 强度 $α=1$、 高斯势 $V_0=λ=1$ 等，表 numeric 同此约定。 · 记号约定：自然对数的底记作 $e$，离心率记作 $e$； circular 小节的 $a$ 是频率比 $ω_r/ω_θ$（作业-2 Q4 的记号）， omegaratio、virial 小节的 $a$ 是椭圆半长轴（作业-5 Q4 的记号）， 两处含义不同，各自在首次出现处重新定义；$T$ 表示动能（作业-5 Q4 记号）， 周期类量用 $T_r$（径向）、$T_E$（地球年）、$τ$（轨道周期）区分。 · 小振动线性化：径向小振动频率 $ω_r$ 由 $V_eff$ 在 $r_0$ 处的泰勒展开保留到二阶项得到，适用条件"},{"m":"M1","sec":"位力定理与椭圆轨道的时间平均（作业-5 Q4）","t":"对周期为 $τ$ 的束缚运动，定义时间平均 $⟨ f⟩≡1τ∫_0^τ f dt$。 由 $l⟨(d)/(dt) (mr)r⟩=0$ （周期函数全周期平均下导数的平均为零）得位力定理 2⟨ T⟩=l⟨ r·∇ Vr⟩ 其中 $T=12mv^2$ 为动能（作业-5 Q4 记号）。对引力势 $V=-k/r$ （$k>0$）：$r·∇ V=k/r=-V$，故 $2⟨ T⟩=-⟨ V⟩$。 $⟨1/r⟩$ 用面积定律计算：$dt=(m/L)r^2 dθ$， 轨道 式（keporbit）（$p=a(1-e^2)$，半长轴 $a$、半短轴 $b=a√(1-e^2)$， 周期 $τ=2π ab m/L$ 即面积除以面积速率），则 ⟨1r⟩ =(m/L)/(τ)∫_0^2π r dθ =(1)/(2π ab)·2π p√(1-e^2) =(1)/(a) 其中用了标准积分 $∫_0^2π(dθ)/(1+ecosθ)=2π√(1-e^2)$ （$0≤ e<1$）。于是 ⟨ V⟩=-(k)/(a) ⟨ T⟩=(k)/(2a) 2⟨ T⟩=-⟨ V⟩ 位力定理得到验证，且 $E=⟨ T⟩+⟨ V⟩=-k/(2a)$。 适用条件：束缚椭圆轨道（$0≤ e<1$）、时间平均取整周期。"},{"m":"M1","sec":"圆轨道、稳定性与径向小振动（作业-2 Q4）","t":"圆轨道 $r(t)≡ r_0$ 要求 $r=r=0$，即 $V_eff$ 取驻值： V_eff'(r_0)=0 ω_θ≡θ=(L)/(mr_0^2) 其中 $ω_θ$ 为圆周运动角频率。给径向一个小扰动 $r=r_0+δ r$ （$|δ r| r_0$），把 式（E） 中的 $V_eff$ 在 $r_0$ 处 泰勒展开保留到二阶： 12ml(δ rr)^2 +12V_eff''(r_0)(δ r)^2 =E-V_eff(r_0) 即扰动以频率 ω_r=V_eff''(r_0)/m 绕 $r_0$ 简谐振动。这正是稳定条件 V_eff''(r_0)>0 的物理内容：$V_eff''(r_0)<0$ 时 式（lin） 左端第二项为负， 扰动按 $e^|ω_r|t$ 指数发散（不稳定）；$V_eff''(r_0)=0$ 为临界情形。式（omegar） 的适用条件是线性化 $|δ r| r_0$； 有限振幅的频率修正为 $O(δ^2)$（见 第 numeric 节 节的数值证据）。 对幂律势 $V=β r^k$（作业-2 Q4；$β$、$k$ 为常数）： $V_eff'=β k r^k-1-L^2/(mr^3)=0$ 给出圆轨道半径 r_0=((L^2)/(mkβ))^ (1)/(k+2) 要求 $kβ>0$（势足够吸引，否则无圆轨道）。在 $r_0$ 处 ω_r^2=V_eff''(r_0)m =((k+2) kβ)/(m) r_0^ k-2 与 $ω_θ=L/(mr_0^2)$ 之比为（用 式（r0power） 消去 $L$） a≡(ω_r)/(ω_θ)=√(k+2) （此处 $a"},{"m":"M2","sec":"讨论","t":"长程势的总截面发散。 $V=k/r^2$ 的总散射截面发散，是因为势的衰减慢于 $1/r$； 任何有限 $b$ 都被偏转。物理上需要截断（如原子屏蔽或有限靶尺寸）。 这与 Rutherford 散射（$V∝ 1/r$）不同：Coulomb 势的总截面也发散， 但微分散射截面在 $Θ→0$ 时 $∼ 1/Θ^4$，比 $k/r^2$ 势的 $∼ 1/Θ^3$ 更强。 俘获的物理意义。 $V=-α/r^4$ 在 $r→0$ 时 $V→-∞$，粒子一旦越过势垒就螺旋坠入； $b_c$ 给出俘获的``靶面积''半径。这种势在原子/分子碰撞中出现 （如 van der Waals 吸引尾），俘获截面 $σ∝ E^-1/2$， 能量越低俘获截面越大。 散射角与碰撞参数的关系。 式（theta-k） 给出 $Θ$ 随 $b$ 单调递减：$b=0$ 时 $Θ=π$ （正碰回弹），$b→∞$ 时 $Θ→0$（掠射）。微分散射截面 式（diffcross-k） 在 $Θ→0$ 处按 $1/Θ^3$ 发散（前向峰，源于长程势）， 在 $Θ=π$ 处有限（背散射有限）。 与 Rutherford 散射的比较。 Coulomb 势 $V=α/r$ 的散射角为 $Θ=2arctan(α/(2Eb))$， 微分散射截面 $dσ/dΩ=(α/(4E))^2/sin^4(Θ/2)$。 相比之下，$V=k/r^2$ 势的微分散射截面在 $Θ→0$ 时发散更慢 （$∼ 1/Θ^3$ vs $∼ 1/Θ^4$），反映势的衰减更快。 与作业题的对照。 表 numeric 覆盖了作业-3 Q2 的散射角与微分散射截面、 "},{"m":"M2","sec":"模块概览","t":"考虑能量 $E>0$、碰撞参数为 $b$ 的入射粒子在中心力场中的非束缚运动。粒子绕力心偏转的角度 $Θ(b)$ 由轨道积分决定，并由此定义微分散射截面： $$dσdΩ = (b)/(sinΘ)|dbdΘ|$$ ### 两类典型行为 - **排斥势散射**（如 $V(r)=k/r^2$ 或库仑排斥势）：粒子无法抵达力心，每个碰撞参数 $b$ 对应唯一的偏转角 $Θ(b)$。 - **吸引势垒俘获**（如 $V(r)=-α/r^4$）：当 $b$ 小于临界值 $b_c$ 时，入射能量越过有效势垒顶点，粒子螺旋坠入中心，定义总俘获截面 $σ_cap=π b_c^2$。"},{"m":"M2","sec":"散射的基本公式","t":"对中心力散射，粒子从无穷远处入射，能量 $E>0$，碰撞参数 $b$。 轨道在极坐标下由比奈方程描述。散射角 $Θ$（入射与出射渐近线夹角）由 积分公式给出： Θ = π - 2∫_r_min^∞ b drr^2√(1-V(r)/E-b^2/r^2) 其中 $r_min$ 是转折点（最近距离），满足 $V_eff(r_min)=E$。 截面的定义。 微分散射截面 $dσ/dΩ$ 描述散射到立体角 $dΩ$ 中的粒子数占比。几何上，碰撞参数在 $[b,b+db]$ 环带内的粒子被散射到 $[Θ,Θ+dΘ]$ 角度范围， 因此 2π b |db| = (dσ)/(dΩ) 2πsinΘ |dΘ| 即 式（diffcross）。总散射截面 $σ=∫(dσ/dΩ) dΩ$。 俘获截面。 对吸引势，若存在有效势垒且 $E>V_eff,max$，粒子越过势垒 到达 $r=0$（俘获）。临界碰撞参数 $b_c$ 满足 $E=V_eff,max$， 俘获截面为 $σ=π b_c^2$（圆盘面积）。 其中 $r_min$ 是转折点（最近距离），满足 $V_eff(r_min)=E$，即 1-V(r_min)E-b^2r_min^2=0. 微分散射截面定义为 (dσ)/(dΩ) = (b)/(sinΘ)|(db)/(dΘ)| 总散射截面为 $σ=∫ (dσ/dΩ) dΩ$。 取无穷远势能为零，入射速率记为 $v_0$，由能量与角动量守恒求轨道的角度变化。 E=12mv_0^2, L=mv_0b, r^2=v_0^2(1-(V(r))/(E)-(b^2)/(r^2)) |(dθ)/(dr)|=(L)/"},{"m":"M2","sec":"作业映射","t":"· 来源 | 题面简述 | 核心知识点 | 对应小节 · 作业-3 Q2 | 质量为 $m$ 的粒子以能量 $E$ 入射，受到中心排斥势 $V=k/r^2$ 的散射； 碰撞参数为 $b$：(a) 求散射角与 $b$ 的关系；(b) 推导微分散射截面 · $dσ/dΩ$；(c) 求总散射截面 $σ$ | 比奈方程、散射角、截面定义 · 作业-3 Q3 | 在势场 $V=-α/r^4$ 中运动，质量为 $m$，能量为 $E$； 存在临界碰撞参数 $b_c$，当 $b<b_c$ 时粒子不受势垒阻挡而越过有效势垒而``螺旋坠入''力心； · 推导 $b_c$ 的表达式，以及计算对应的总俘获截面 $σ$ | 有效势垒、俘获条件、截面"},{"m":"M2","sec":"书稿精读","t":"【定理】卢瑟福散射公式。库仑散射微分截面正比于sin⁻⁴(Θ/2)，总截面发散。（书稿 ch01.tex:2540）"},{"m":"M2","sec":"吸引势 $V=-α/r^4$ 的俘获（作业-3 Q3）","t":"势能 $V(r)=-α/r^4$（$α>0$，吸引，短程奇异）。有效势 V_eff(r)=-(α)/(r^4)+(L^2)/(2mr^2) =-(α)/(r^4)+(Eb^2)/(r^2) 其中 $L=mv_0 b$、$E=12 mv_0^2$。 令 $u=1/r^2$，则 V_eff(u)=-α u^2+Eb^2 u 这是 $u$ 的下开口抛物线，在 u_*=(Eb^2)/(2α) r_*=√((2α)/(Eb^2)) 处取得极大值（有效势垒）： V_eff,max = -α((Eb^2)/(2α))^2 + Eb^2((Eb^2)/(2α)) = (E^2 b^4)/(4α). 俘获条件：粒子能量 $E$ 超过势垒，即 $E>V_eff,max$： E > (E^2 b^4)/(4α) b^4 < (4α)/(E). 因此临界碰撞参数为 b_c=((4α)/(E))^1/4 （作业-3 Q3 所求）。$b<b_c$ 时粒子越过势垒，$r→0$ 螺旋坠入力心（俘获）； $b≥ b_c$ 时粒子被势垒反射（散射）。 总俘获截面为圆盘面积： σ=π b_c^2 =π√((4α)/(E)) =2π√((α)/(E)) （作业-3 Q3 所求）。"},{"m":"M2","sec":"模型与假设","t":"考虑质量为 $m$ 的质点在中心力场中运动。以力心为原点建立平面极坐标 $(r,θ)$。基本假设： · 有心力假设：$F=F(r)e_r$，力的大小只依赖 $r$。 · 保守力假设：力场在 $r>0$ 区域旋度为零，存在势能 $V(r)$， $F=-∇ V$。 · 单位制：解析推导保留 $m$、$k$、$α$、$E$ 等参数； 数值验证统一取无量纲约定 $m=1$、$k=1$、$α=1$、$E=1$。 · 散射设定：粒子从无穷远处入射，能量 $E>0$，碰撞参数 $b≥0$； 入射方向为 $x$ 轴，力心在原点，轨道对 $x$ 轴对称。 · 俘获设定：吸引势 $V=-α/r^4$（$α>0$）， 粒子能量 $E>0$；有效势存在势垒，$b<b_c$ 时粒子越过势垒到达 $r=0$ （俘获），$b≥ b_c$ 时粒子被势垒反射（散射）。 · 小角/远场近似：散射角 $Θ$ 为入射与出射渐近线的夹角， $0≤Θ≤π$；$Θ=0$ 对应无偏转，$Θ=π$ 对应正碰回弹。"},{"m":"M3","sec":"模块概览","t":"孤立两体系统（质量 $M_1,M_2$，相对位矢 $r=r_1-r_2$）在质心系中可精确分解为质心匀速运动与约化质量 $μ$ 的等效单体运动： $$μ = (M_1 M_2)/(M_1 + M_2), μr = F_12(r), T^2 = (4π^2)/(G(M_1+M_2))a^3$$ ### 天体物理应用：系外行星视向速度法 - 恒星与行星绕共同质心旋转，恒星摆动速度幅值 $K∝ (M_2)/(M_1+M_2)v_orb$ 引起谱线周期性多普勒频移 $(Δλ)/(λ)=(v_r)/(c)$。 - 通过观测恒星视向速度曲线的周期与幅值，可反演系外行星的轨道半长轴与最小质量。"},{"m":"M3","sec":"讨论","t":"约化质量与等效单体问题。 两体问题通过质心分离与约化质量 $μ=M_1M_2/(M_1+M_2)$ 等价为单体中心力问题。这一技巧在天体力学、分子物理中广泛使用。 相对运动的轨道形状与单体 Kepler 问题相同，仅时间尺度由总质量决定。 质心在太阳表面之外。 木星引起的太阳摆动幅度 $r_1≈7.4×10^8 m>R_☉$， 太阳绕质心的轨道半径超过太阳半径，恒星的`` Reflex motion'' 可观。 类地行星的挑战。 地球信号 $∼0.09 m/s$，比太阳表面噪声 $∼1 m/s$ 小一个数量级，需要长时间积分与多普勒测量精度 $∼0.1 m/s$。 系外行星探测方法。 径向速度法（RV）是最成功的系外行星探测方法之一，发现了数千颗行星。 其精度要求随行星质量与轨道距离变化：热木星（$M_p∼ M_J$，$a∼0.05 AU$） 信号 $∼ 50 m/s$，地球类似行星信号 $∼ 0.1 m/s$。 其他方法包括凌星法（transit）、直接成像、微引力透镜等。 径向速度曲线的形状。 对圆轨道，$v_r(t)$ 为正弦函数，振幅 $K=v_1$（式（v1））。对椭圆轨道， $v_r(t)$ 非正弦，振幅为 $K=(M_2)/(M_1+M_2)2π aP√(1-e^2)sin i$。 实际观测中拟合 Kepler 轨道得到 $K$、$P$、$e$，再反推 $M_2sin i$（最小质量）， 不直接使用圆轨道公式（v1b）。 与作业题的对照。 表 numeric 覆盖了作业题 (a)—(e) 的全部数值结果。 H. Goldstein, C. P. Poole, J."},{"m":"M3","sec":"两体能量与 virial","t":"两体系统的总能量（圆轨道）： E = -(GM_1M_2)/(2a). 动能 $T=12 M_1 v_1^2+12 M_2 v_2^2 =12 μ v_rel^2$ 势能 $V=-GM_1M_2/a$。virial 定理 $2⟨ T⟩=-⟨ V⟩$ 成立。 圆轨道的相对速率为 $v_rel=ω a$，代入两体 Kepler 定律。 T=12μω^2a^2=12(M_1M_2)/(M_1+M_2)(G(M_1+M_2))/(a)=(GM_1M_2)/(2a) E=T+V=(GM_1M_2)/(2a)-(GM_1M_2)/(a)=-(GM_1M_2)/(2a) 2⟨ T⟩=2T=-V=-⟨ V⟩"},{"m":"M3","sec":"书稿精读","t":"【定理】位力定理。有界运动满足2⟨T⟩+⟨ΣF·r⟩=0，n次齐次势给2⟨T⟩=n⟨V⟩。（书稿 ch01.tex:1731）"},{"m":"M3","sec":"太阳--木星系统（作业题 (a)(b)(c)）","t":"给定：$M_☉=1.989×10^30 kg$， $M_J=1.898×10^27 kg$ $a_J=7.78×10^11 m$ $P_J=11.86 yr=11.86×3.156×10^7 s$。 (a) 质心距离。 由 式（r1r2）： r_1=(M_J)/(M_☉+M_J) a_J =1.898×10^271.989×10^30+1.898×10^27×7.78×10^11 ≈ 7.42×10^8 m. 太阳半径 $R_☉=6.96×10^8 m$，比值 (r_1)/(R_☉)≈(7.42×10^8)/(6.96×10^8)≈1.07. $r_1>R_☉$：太阳质心在太阳表面之外，太阳绕质心的``摆动''幅度 超过太阳半径。 (b) 角速度与摆动速度。 由 式（kepler2）： ω=√((G(M_☉+M_J))/(a_J^3)) =(2π)/(P_J)≈1.68×10^-8 rad/s. 摆动速度 v_1=ω r_1≈1.68×10^-8×7.42×10^8 ≈ 12.5 m/s. (c) 多普勒位移。 取 $λ=500 nm$，$v_1≈12.5 m/s$： Δλ=λ(v_1)/(c) =500 nm×(12.5)/(3.0×10^8) ≈ 2.08×10^-5 nm."},{"m":"M3","sec":"质心与约化质量","t":"两质量 $M_1$（恒星）、$M_2$（行星）相距 $a$。质心条件 M_1 r_1 = M_2 r_2, r_1+r_2=a 解得 r_1=(M_2)/(M_1+M_2) a r_2=(M_1)/(M_1+M_2) a. $r_1$ 为恒星到质心的距离，$r_2$ 为行星到质心的距离。 引入约化质量 $μ=M_1M_2/(M_1+M_2)$，两体问题等价于质量 $μ$ 的 质点在中心势 $-GM_1M_2/r$ 中运动： μ r=-(GM_1M_2)/(r^2) e_r. 令两体位置矢量之差为 $r=r_2-r_1$，相减两条牛顿方程。 M_1r_1=(GM_1M_2)/(r^3)r, M_2r_2=-(GM_1M_2)/(r^3)r r=-G(M_1+M_2)(r)/(r^3) =-(GM_1M_2)/(r^2)e_r, μ=(M_1M_2)/(M_1+M_2)"},{"m":"M3","sec":"太阳--地球系统（作业题 (d)(e)）","t":"给定：$M_E=5.97×10^24 kg$， $a_E=1.496×10^11 m$，$P_E=1 yr$。 (d) 重算。 r_1=(M_E)/(M_☉+M_E) a_E ≈5.97×10^241.989×10^30×1.496×10^11 ≈ 4.49×10^5 m (449 km). ω=(2π)/(P_E)≈1.99×10^-7 rad/s v_1=ω r_1≈ 0.089 m/s (8.9 cm/s). 与走路速度 $1.4 m/s$ 相比，地球引起的太阳摆动慢约 16 倍； 与蜗牛速度 $1.3 cm/s$ 相比，快约 7 倍。 一句话：地球拖动太阳的摆动速度仅 $9 cm/s$， 比人走路慢一个数量级，但比蜗牛快。 (e) 为什么需要 $0.1 m/s$ 精度。 · 信号本身仅 $∼ 0.09 m/s$（地球），仪器噪声必须优于信号， 否则无法分辨。 · 太阳表面噪声（米粒组织、$p$ 模振荡等）量级 $∼ 1 m/s$， 远大于地球信号，需要长时间平均与建模扣除。"},{"m":"M4","sec":"模块概览","t":"动量定理既支配瞬时相互作用的碰撞，也支配质量连续交换的开放变质量系统。 $$m_1v_1+m_2v_2 = m_1v'_1+m_2v'_2, e = -v'_2n-v'_1nv_2n-v_1n$$ ### 核心模型 - **光滑球斜碰**：切向速度分量守恒、法向由恢复系数 $e∈[0,1]$ 控制；当入射角满足 $tan^2α=(1-e)/(2)$ 时偏转角达到极大值。 - **变质量雨滴**：下落过程中连续吸积静止水汽（$dr/dt=λ$），质量按 $m∝ t^3$ 增长，运动方程 $d(mv)dt=mg$ 给出渐近加速度 $a=g/7$。"},{"m":"M4","sec":"光滑球碰撞（作业-5 Q1）","t":"质量相等的光滑球，球 1 以速度 $v$ 入射，球 2 静止。 入射方向与两球中心连线夹角为 $α$。恢复系数 $e$。 分解为法向（沿中心连线）与切向： v_1n=vcosα, v_1t=vsinα, v_2n=v_2t=0. 碰撞后（等质量，恢复系数 $e$）： v_1n'=(1-e)/(2)vcosα v_2n'=(1+e)/(2)vcosα v_1t'=vsinα, v_2t'=0. 球 1 偏转角 $β$（与原方向夹角）： cosβ=v_1nv_1n'+v_1tv_1t'v· v_1' =(1-e)/(2)cos^2α+sin^2α √(((1-e)/(2)cosα)^2+sin^2α). $β$ 最大时满足 $dβ/dα=0$，解得 tan^2α=(1-e)/(2). 代入得 $β_max$。 对 $0≤ e<1$，联立法向动量守恒与恢复系数定义，再对偏转角求极值。 v_1n'+v_2n'=vcosα, v_2n'-v_1n'=evcosα v_1n'=(1-e)/(2)vcosα, v_2n'=(1+e)/(2)vcosα tanβ=(1+e)/(2)tanαtan^2α+(1-e)/(2) (d(tanβ))/(dα)=(1+e)/(2)sec^2α((1-e)/(2)-tan^2α)(tan^2α+(1-e)/(2))^2=0 tan^2α=(1-e)/(2)"},{"m":"M4","sec":"变质量系统的通用公式","t":"一般变质量系统：$d(mv)/dt=F+u dm/dt$， 其中 $u$ 为增加质量的绝对速度。雨滴问题中 $u=0$（静止雨水）。 把在 $dt$ 内并入的质量 $dm$ 一并纳入动量收支，并略去二阶微量。 mv+u dm+F dt=(m+dm)(v+dv) m dv+v dm=F dt+u dm (d(mv))/(dt)=F+u(dm)/(dt)"},{"m":"M4","sec":"附录：碰撞公式汇总","t":"· 一维弹性碰撞：$v_1'=(m_1-m_2)v_1/(m_1+m_2)$，$v_2'=2m_1 v_1/(m_1+m_2)$。 · 二维光滑球碰撞：法向恢复系数 $e$，切向不变。 · 变质量方程：$d(mv)/dt=F+m u$。 · 雨滴：$r=r_0+λ t$，$v=g/(4λ)[(r_0+λ t)-r_0^4/(r_0+λ t)^3]$。 · 碰撞链：$H=4h$（$m_2 m_1$）。"},{"m":"M4","sec":"解析结果","t":"· 球碰撞偏转角：$cosβ$ 公式（collision）， $β_max$ 时 $tan^2α=(1-e)/2$（式（alpha-max））。 · 雨滴速度：$v(t)=(g)/(4λ)[(r_0+λ t)-r_0^4/(r_0+λ t)^3]$ （式（raindrop-v）），$t→∞$ 时 $v∼ gt/4$。 · 弹性碰撞链：$H≈ 4h$（$m_2 m_1$）。"},{"m":"M4","sec":"数值验证","t":"全部数值实验由配套脚本 qa/numeric_check.py 完成（仅依赖 numpy）。 · 物理量 | 解析值 | 数值值 · $β_max$（$e=0.5$） | $36.9^∘$ | $36.8699^∘$ · $v(t)$（雨滴，$t=10$） | 公式值 | 数值积分一致 · $H/h$（碰撞链） | $4.0$ | $4.0$ 数值验证汇总。全部数值取自 qa/numeric_check.py 的实际输出。"},{"m":"M4","sec":"弹性碰撞链（作业-5 Q3）","t":"球 B1 质量 $m_1$，B2 质量 $m_2$（$m_2 m_1$）。B1 从高度 $h$ 落下， 与地面弹性碰撞后上升速度 $v_1=√(2gh)$，再与 B2（静止）弹性碰撞。 一维弹性碰撞公式： v_2'=(2m_1)/(m_1+m_2)v_1≈ 2v_1 (m_2 m_1). B2 反弹高度 H=(v_2'^2)/(2g)≈(4v_1^2)/(2g)=4h. H≈ 4h"},{"m":"M5","sec":"模块概览","t":"质点运动学给出位置、速度与加速度在不同坐标系下的分量表达，是建立牛顿动力学方程的几何基础。 $$v = re_r + rθe_θ, a = (r - rθ^2)e_r + (rθ + 2rθ)e_θ$$ ### 约束脱离与参考系 - **圆柱脱离问题**：小球从光滑圆柱顶端静止滑下，联立机械能守恒与法向方程 $mgcosθ - N = mv^2/R$，支持力 $N=0$ 给出脱离角 $cosθ=(2)/(3)$。 - 同时涵盖自然坐标法向/切向加速度、伽利略相对运动与正交电磁场中的 $E$ 摆线漂移。"},{"m":"M5","sec":"运动学的几何意义","t":"速度是轨迹的切向量，加速度分解为切向（改变速率）与法向（改变方向）： a = v e_t + (v^2)/(ρ) e_n. 曲率 $κ=1/ρ=|v|/v^3$。 令 $s$ 为沿轨迹的弧长，利用单位切向量沿弧长的变化率定义曲率。 v=ve_t, (ds)/(dt)=v, (de_t)/(ds)=(e_n)/(ρ) a=(d(ve_t))/(dt)=ve_t+v(de_t)/(ds)(ds)/(dt)=ve_t+(v^2)/(ρ)e_n |v|=(v^3)/(ρ) κ=1ρ=(|v|)/(v^3)"},{"m":"M5","sec":"极坐标运动学","t":"极坐标 $(r,θ)$ 中的速度与加速度： v = r e_r + rθ e_θ a = (r-rθ^2) e_r + (rθ+2rθ) e_θ. 作业-1 Q1 的椭圆交点速度即用此公式计算。"},{"m":"M5","sec":"圆柱脱离（作业-1 Q6）","t":"质点从圆柱顶部（$r=R$）静止滑下，圆柱光滑。设滑下角度为 $θ$（从顶点量）。 能量守恒：$12 mv^2=mgR(1-cosθ)$，故 $v^2=2gR(1-cosθ)$。 径向牛顿方程（向心为正）： mgcosθ - N = (mv^2)/(R). 脱离条件 $N=0$： gcosθ = (v^2)/(R) = 2g(1-cosθ) 3cosθ=2 cosθ=23, θ=arccos23≈48.2^∘"},{"m":"M5","sec":"Lorentz 力（作业-1 Q4）","t":"电子在相互垂直的匀强 $E$、$B$ 场中， 初速度 $v,B$。 Lorentz 力 $F=-e(E+v)$。 设 $E=Ey$，$B=Bz$，$v=(v_0,0,0)$。 运动方程：$mv=-e(E+v)$。 $x$-$y$ 平面：$mv_x=-eB v_y$，$mv_y=-eE+eB v_x$。 解为回旋运动叠加 $E$ 漂移： v_d=(E)/(B^2). 回旋半径 $r_c=mv_⊥/(eB)$，回旋频率 $ω_c=eB/m$。 将 $v_x$ 平移 $E/B$，原方程即化为简谐振动方程。 ω_c=(eB)/(m), v_x=-ω_c v_y, v_y=ω_c(v_x- EB) (d^2)/(dt^2)(v_x- EB)+ω_c^2(v_x- EB)=0 v_x= EB+(v_0- EB)cosω_ct, v_y=(v_0- EB)sinω_ct ⟩= EBx=(E)/(B^2), r_c=(|v_0-E/B|)/(ω_c)"},{"m":"M5","sec":"相对运动与伽利略变换","t":"伽利略变换：$r'=r-V t$， $v'=v-V$，$a'=a$。 作业-1 Q3 的渡河问题即相对运动的应用：船对地速度 = 船对水速度 + 水对地速度。 渡河最短时间。 船相对水速度 $v_2$，水流速度 $v_1$。最短渡河时间 $T=d/v_2$（垂直渡河）， 设船头与河岸法线夹角为 $θ$，则渡河时间 $T=d/(v_2cosθ)$， 沿河漂移 $x=(v_1-v_2sinθ)T$。对 $θ$ 求极小，当 $v_1>v_2$ 时 x_min=(d)/(v_2)√(v_1^2-v_2^2). 例如 $v_1=2, v_2=1$ 时 $x_min=3 d≈1.732d$， 而不是垂直船头时的 $d v_1/v_2=2d$。"},{"m":"M5","sec":"圆周运动（作业-1 Q2）","t":"质点在半径 $r$ 的圆周上运动，加速度与速度夹角 $α$ 保持不变。 切向加速度 $a_t=v$，法向加速度 $a_n=v^2/r$。 $tanα=a_n/a_t=v^2/(rv)$，故 a_t=(a_n)/(tanα)=(v^2)/(rtanα) (dv)/(dt)=(v^2)/(rtanα) (dv)/(v^2)=(dt)/(rtanα). 积分得 $-1/v=t/(rtanα)+C$。 初值 $v(0)=v_0$：$C=-1/v_0$。 v(t)=(v_0)/(1-v_0 t/(rtanα)) （要求 $t<rtanα/v_0$，否则发散。）"},{"m":"M6","sec":"模块概览","t":"在以角速度 $Ω$ 自转的地球参考系中，运动质点除真实外力外还受到科里奥利力 $F_C=-2mΩ$ 与离心力作用。对纬度 $λ$ 处的长单摆，水平面内的小角方程为： $$x - 2Ω_zy + ω_0^2 x = 0, y + 2Ω_zx + ω_0^2 y = 0, Ω_z = Ωsinλ$$ ### 进动与玫瑰线 - 科里奥利耦合使摆动平面以角速度 $-Ωsinλ$ 缓慢进动，周期 $T_F = (2π)/(Ω|sinλ|)$。 - 北半球俯视顺时针旋转、南半球逆时针、赤道处不进动，极点处恰好一个恒星日转满一圈，摆尖在地面绘出玫瑰线。"},{"m":"M6","sec":"傅科摆方程与进动周期","t":"方程组 $ x=-(g)/(L)x+2Ωsinλ y, y=-(g)/(L)y-2Ωsinλ x $。合并为复变量 $ z=x+iy $：$ z+2iΩsinλ z+(g)/(L)z=0 $；令 $ z=A(t) e^-iΩsinλ t $ 且视 $ A(t) $ 慢变，则摆动平面以角速率 $ -Ωsinλ $ 相对地面进动（北半球顺时针），进动周期 $ T_F=(2π)/(Ω|sinλ|)=23.93 h|sinλ| $，其中 23.93 h 即一个恒星日。数值上用固定步长 RK4（步长不超过摆周期的 1/60），无阻尼时 $ 10^4 s $ 模拟内能量相对漂移约 $ 10^-4 $。"},{"m":"M6","sec":"转动参考系与科里奥利力","t":"在随地球以角速度 $ Ω $ 转动的参考系中，运动方程补充惯性项：$ ma'=F-2mΩ'-mΩ×(Ω) $。科里奥利项 $ -2mΩ' $ 与速度垂直、不做功，只持续把速度向右（北半球）偏转。取东为 $ x $、北为 $ y $，$ Ω $ 的当地垂直分量是 $ Ωsinλ $，它给出的水平科氏加速度恰为 $ ( 2Ωsinλ y, -2Ωsinλ x ) $，与回复力 $ -(g/L)(x,y) $ 相加即得页面上的方程组。"},{"m":"M6","sec":"纬度表与 1851 年先贤祠实验","t":"纬度表（$ T_F=23.93 h/|sinλ| $，速率 $ 15.04sinλ ^∘/h $）：北极 $ λ=90^∘ $：23.93 h，一个恒星日旋转一整圈，摆动平面几乎相对恒星固定；巴黎 $ 48.85^∘ $：31.9 h（约 $ 11.3^∘/h $）；北京 $ 39.9^∘ $：37.5 h；赤道 $ 0^∘ $：$ T_F→∞ $，水平科氏力为零、无进动。1851 年傅科在巴黎先贤祠悬挂约 67 m 的摆，摆尖划过沙槽的轨迹随时间偏转，首次在实验室里直接证明了地球自转。"},{"m":"M6","sec":"玫瑰线如何编码进动","t":"每个摆动周期 $ T=2π√(L/g) $，摆动平面转过 $ Δθ=Ωsinλ T $（例如 $ L=2 m $、$ λ=45^∘ $ 时约 $ 4.1×10^-4 $ rad）。摆尖轨迹是一族细长椭圆（近似直线往返），每圈相对地面旋转 $ Δθ $，叠加成玫瑰线：花瓣（叶）数正比于一个进动周期内的摆动次数 $ T_F/T $，$ L=2 m $、$ λ=45^∘ $ 时约 4.3 万。加阻尼后包络指数收缩，花瓣首尾内卷成螺旋玫瑰——玫瑰的角向缺口间距就是进动的直接读数。"},{"m":"M6","sec":"书稿精读","t":"【概念】转动参考系三种惯性力。科里奥利、离心与欧拉力源于基矢转动，不是真实相互作用。（书稿 ch01.tex:1891）"},{"m":"M7","sec":"模块概览","t":"圆限制性三体问题（CR3BP）研究质量可忽略的第三体在两个做圆轨道运动的主天体（归一化质量 $1-μ$ 与 $μ$）引力场中的运动。在随两主天体共转的坐标系中引入有效势 $U(x,y)$ 与雅可比积分 $C_J$： $$x - 2y = (∂ U)/(∂ x), y + 2x = (∂ U)/(∂ y), C_J = 2U(x,y) - (x^2+y^2)$$ ### 平稳点与稳定性 - 有效势存在五个驻点：共线点 $L_1,L_2,L_3$（鞍点，线性不稳定）与等边三角形点 $L_4,L_5$。 - 当质量比 $μ < μ_c = (1)/(2)(1-√((23)/(27)))≈ 0.03852$ 时，科里奥利力使 $L_4,L_5$ 稳定，小天体可沿蝌蚪形或马蹄形轨道长期驻留。"},{"m":"M7","sec":"雅可比常数与零速度曲线","t":"雅可比积分 $C_J=2U-v^2$ 沿轨迹守恒，$U=(1-μ)/r_1+μ/r_2+12(x^2+y^2)$。给定 $C$，速度平方 $v^2=2U-C≥ 0$ 定义允许区，边界 $U=C/2$ 即零速度曲线：小天体不能穿越它。随能量升高（$C$ 减小），零速度曲线依次越过临界值 $C(L_3)$、$C(L_2)$ 打开 L3 与 L2 颈口，最终贯通内外。页面上金色粗曲线为选定 $C$ 的零速度曲线，拖动滑杆可实时观察其开合；细等势线则展示势能地形。 将两个运动方程分别乘以 $x$、$y$ 后相加，科里奥利项相消。 xx+yy=U_xx+U_yy+2-2=(dU)/(dt) (d)/(dt)[12(x^2+y^2)-U]=0 (dC_J)/(dt)=(d)/(dt)[2U-(x^2+y^2)]=0"},{"m":"M7","sec":"L4/L5 稳定性、蝌蚪与马蹄轨道","t":"对 L4 线性化得到特征方程判别式 $1-27μ(1-μ)$：当 $μ<μ_c=12(1-√(23/27))≈0.038521$（鲁斯判据）时 L4/L5 线性稳定，小扰动以频率 $ν=12(1+√(1-27μ(1-μ)))$ librates，形成绕 L4/L5 的蝌蚪形轨道；模块按 L4 复本征模构造小振幅蝌蚪初条件，长时积分验证有界。振幅更大时出现马蹄形共轨轨道：粒子在 L4 弧与 L5 弧之间越过 L3 一侧的大回环，与 $M_2$ 周期性交换角动量，模块以日–木星质量比演示。若 $μ$ 超过 $μ_c$，页面红色警示 L4/L5 失稳。 在 L4 处计算有效势的二阶导数，并令线性扰动按 $e^σ t$ 变化。 U_xx=34, U_yy=94, U_xy=(33)/(4)(1-2μ) -2=U_xxδ x+U_xyδ y +2=U_xyδ x+U_yyδ y detσ^2-U_xx -2σ-U_xy 2σ-U_xy σ^2-U_yy=σ^4+σ^2+(27)/(4)μ(1-μ)=0 σ^2=-1±√(1-27μ(1-μ))2 μ∈(0,12(1-√((23)/(27)))) σ^2<0"},{"m":"M7","sec":"转动参考系与有效势","t":"在随两天体转动的参考系中，$M_1$ 固定于 $(-μ,0)$，$M_2$ 固定于 $(1-μ,0)$。引力势与离心势合并为有效势 $Φ_eff=-(1-μ)/r_1-μ/r_2-12(x^2+y^2)$，其中 $r_1,r_2$ 为到两天体的距离。小天体的运动方程为 $x-2=-∂Φ_eff/∂ x$，$y+2=-∂Φ_eff/∂ y$，含科里奥利力 $∓ 2,∓ 2$。科里奥利力不做功，因此存在雅可比积分。页面热力图即有效势 $U=-Φ_eff$ 的对数拉伸分布。"},{"m":"M7","sec":"五个平稳点及其数值","t":"平稳点要求转动系中速度为零且有效势梯度为零。共线的 L1、L2、L3 满足关于 $x$ 的五次代数方程（等价于对 $U_x(x,0)=0$ 数值求根），地–月质量比下数值解为 L1 位于 $x≈0.836913$、L2 位于 $x≈1.155684$、L3 位于 $x≈-1.005063$；L1 到 $M_2$ 的距离近似为 $(μ/3)^1/3$。L4、L5 与两天体构成等边三角形：$(12-μ,±3/2)$。共线三点是有效势的鞍点，L4、L5 是极大点（对 $U=-Φ$ 而言为极小）。"},{"m":"M7","sec":"书稿精读","t":"【极限】拉格朗日点与L4线性稳定性。共线点不稳定；三角点在μ<0.03852时靠科里奥利力稳定。（书稿 ch01.tex:2649）"},{"m":"M8","sec":"模块概览","t":"在均匀重力场中，滑块沿曲线 $y(x)$ 从静止无摩擦滑下的时间泛函为 $T[y]=∫ √(1+y'^2)√(2gy) dx$。由欧拉–拉格朗日方程（或 Beltrami 恒等式）求驻值，得最速降线为摆线： $$x(φ) = a(φ - sinφ), y(φ) = a(1 - cosφ)$$ ### 严格的等时性（Tautochrone） - 以弧长 $s$ 为坐标，摆线满足 $s^2∝ y$，重力切向分量严格正比于弧长 $s$，构成无近似的严格简谐振子。 - 无论从摆线上任意高度静止释放，到达最低点的时间恒为 $T/4=(π)/(2)√(a/g)$，与初振幅完全无关。"},{"m":"M8","sec":"摆线的等时性（作业-6 Q3）","t":"摆线参数方程： x=a(θ-sinθ) h=a(1+cosθ), 0≤θ≤π $h$ 为相对最低点（$θ=π$）的竖直高度。弧长从最低点向上： s=∫_θ^π 2asin(t/2) dt =4acos(θ/2). 高度： h=a(1+cosθ)=2acos^2(θ/2)=(s^2)/(8a). （作业-6 Q3(a)：$s=4acos(θ/2)$，$h=s^2/(8a)$） 能量守恒：从 $s_0$ 释放，到达 $s$ 时下降高度为 $h_0-h=(s_0^2-s^2)/(8a)$，故 v(s)=√(2g(h_0-h))=√((g)/(4a)) √(s_0^2-s^2). 下滑时间从 $s_0$ 到 $0$： T=∫_0^s_0(ds)/(v(s)) =√((4a)/(g))∫_0^s_0ds√(s_0^2-s^2) =√((4a)/(g))·(π)/(2) =π√((a)/(g)). $T$ 与 $s_0$ 无关，等时性得证（作业-6 Q3(c)）。"},{"m":"M8","sec":"Euler--Lagrange 方程","t":"变分原理的核心工具。给定泛函 $J[y]=∫_x_1^x_2 L(x,y,y') dx$， 驻值条件 $δ J=0$ 导出 (∂ L)/(∂ y)-(d)/(dx)(∂ L)/(∂ y')=0. 这是 Euler—Lagrange 方程。本模块的折射定律、最短路径、等时摆 均由此方程导出。 取端点固定的变分 $δ y(x_1)=δ y(x_2)=0$，对含 $δ y'$ 的项分部积分。 δ J=∫_x_1^x_2((∂ L)/(∂ y)δ y+(∂ L)/(∂ y')(dδ y)/(dx))dx δ J=[(∂ L)/(∂ y')δ y]_x_1^x_2+∫_x_1^x_2[(∂ L)/(∂ y)- ddx((∂ L)/(∂ y'))]δ y dx δ J=0 for all δ y (∂ L)/(∂ y)- ddx((∂ L)/(∂ y'))=0"},{"m":"M8","sec":"最短路径（作业-6 Q2）","t":"二维平面中，两点间最短路径使弧长泛函 S=∫ ds=∫√(x^2+y^2) dt 取驻值。Euler-Lagrange 方程：$L=√(x^2+y^2)$， $∂ L/∂ x=0$，$∂ L/=x/√(x^2+y^2)$ $d/dt(∂ L/)=0$，故 $x/√(x^2+y^2)=const$。 同理 $y/√(x^2+y^2)=const$。两式相除：$y/x=const$， 即 $y=kx+c$，直线。 极坐标证明。 弧长 $ds=√(r^2+r^2θ^2) dt$。 Lagrange 方程对 $θ$：$∂ L/∂θ=0$（旋转对称）， 故 $∂ L/∂θ=r^2θ/√(r^2+r^2θ^2)=const=h$。 这给出角动量守恒。结合径向方程，积分得 $rsin(θ-θ_0)=const$， 即直线的极坐标方程。"},{"m":"M8","sec":"最速降线（Brachistochrone）","t":"最速降线问题：给定两点 $A$、$B$，求使质点从 $A$ 滑到 $B$ 时间最短的曲线。 变分法给出摆线为解。时间泛函 T=∫_A^B ds√(2g h(s)) 其中 $h(s)$ 为下降高度。Euler-Lagrange 方程求解得摆线参数方程。 这与等时摆的关系：等时摆是等时性（时间与振幅无关）， 最速降线是极值性（时间取最小值）。 最速降线中以释放点为原点、$h$ 为向下的下降高度，记 $h'=dh/dx$，利用被积函数不显含 $x$ 的第一积分。 L=√(1+h'^2)√(2gh) L-h'(∂ L)/(∂ h')=1√(2gh(1+h'^2))=const h(1+h'^2)=2a h=a(1-cosθ), h'=cotθ2 (dx)/(dθ)=(dh/dθ)/(h')=a(1-cosθ) x=a(θ-sinθ), h=a(1-cosθ)"},{"m":"M8","sec":"费马原理与折射定律（作业-6 Q1）","t":"光在介质中速度 $v=c/n$（$n$ 为折射率）。费马原理：光程时间 T=∫ (n(s))/(c) ds 取驻值。考虑两层介质界面（$y=0$），折射率 $n_1$（上）、$n_2$（下）。 路径从 $A=(x_1,y_1)$ 到 $B=(x_2,y_2)$，在界面点 $(x,0)$ 折射。 时间泛函 T(x)=(n_1)/(c)√((x-x_1)^2+y_1^2) +(n_2)/(c)√((x-x_2)^2+y_2^2). 驻值条件 $dT/dx=0$： (n_1)/(c)x-x_1√((x-x_1)^2+y_1^2) +(n_2)/(c)x-x_2√((x-x_2)^2+y_2^2)=0. 设入射角 $θ_1$、折射角 $θ_2$（均与法线夹角），则 n_1sinθ_1=n_2sinθ_2 即 Snell 折射定律。"},{"m":"M8","sec":"数值验证","t":"全部数值实验由配套脚本 qa/numeric_check.py 完成（仅依赖 numpy）。 · 物理量 | 解析值 | 数值值 · $T$（摆线，$a=1,g=1,s_0=1$） | $π=3.14159$ | $3.14159$ · $T$（摆线，$a=1,g=1,s_0=0.5$） | $π=3.14159$ | $3.14159$ · $T_0$（$C=1/8,g=1$） | $π=3.14159$ | $3.14159$ · $T_0$（$C=1/4,g=1$） | $π/(2√(0.5))=2.221$ | $2.221$ 数值验证汇总。全部数值取自 qa/numeric_check.py 的实际输出。"},{"m":"M9","sec":"模块概览","t":"费马原理指出：光线在折射率分布 $n(r)$ 的介质中沿光程泛函取驻值的路径传播： $$δ∫ n(r) ds = 0$$ ### 从泛函驻值到 Snell 定律 - 当介质仅沿 $y$ 方向分层（$n=n(y)$）时，被积函数不含 $x$，由循环变量对应的守恒量直接给出 $n(y)sinθ(y)=const$。 - 在两均匀介质分界面上即退化为经典的折射定律 $n_1sinθ_1 = n_2sinθ_2$；若取 $n∝ 1/√(y)$，同一规律直接导出力学中的摆线最速降线。"},{"m":"M9","sec":"摆线的等时性（作业-6 Q3）","t":"摆线参数方程： x=a(θ-sinθ) h=a(1+cosθ), 0≤θ≤π $h$ 为相对最低点（$θ=π$）的竖直高度。弧长从最低点向上： s=∫_θ^π 2asin(t/2) dt =4acos(θ/2). 高度： h=a(1+cosθ)=2acos^2(θ/2)=(s^2)/(8a). （作业-6 Q3(a)：$s=4acos(θ/2)$，$h=s^2/(8a)$） 能量守恒：从 $s_0$ 释放，到达 $s$ 时下降高度为 $h_0-h=(s_0^2-s^2)/(8a)$，故 v(s)=√(2g(h_0-h))=√((g)/(4a)) √(s_0^2-s^2). 下滑时间从 $s_0$ 到 $0$： T=∫_0^s_0(ds)/(v(s)) =√((4a)/(g))∫_0^s_0ds√(s_0^2-s^2) =√((4a)/(g))·(π)/(2) =π√((a)/(g)). $T$ 与 $s_0$ 无关，等时性得证（作业-6 Q3(c)）。"},{"m":"M9","sec":"Euler--Lagrange 方程","t":"变分原理的核心工具。给定泛函 $J[y]=∫_x_1^x_2 L(x,y,y') dx$， 驻值条件 $δ J=0$ 导出 (∂ L)/(∂ y)-(d)/(dx)(∂ L)/(∂ y')=0. 这是 Euler—Lagrange 方程。本模块的折射定律、最短路径、等时摆 均由此方程导出。 取端点固定的变分 $δ y(x_1)=δ y(x_2)=0$，对含 $δ y'$ 的项分部积分。 δ J=∫_x_1^x_2((∂ L)/(∂ y)δ y+(∂ L)/(∂ y')(dδ y)/(dx))dx δ J=[(∂ L)/(∂ y')δ y]_x_1^x_2+∫_x_1^x_2[(∂ L)/(∂ y)- ddx((∂ L)/(∂ y'))]δ y dx δ J=0 for all δ y (∂ L)/(∂ y)- ddx((∂ L)/(∂ y'))=0"},{"m":"M9","sec":"最短路径（作业-6 Q2）","t":"二维平面中，两点间最短路径使弧长泛函 S=∫ ds=∫√(x^2+y^2) dt 取驻值。Euler-Lagrange 方程：$L=√(x^2+y^2)$， $∂ L/∂ x=0$，$∂ L/=x/√(x^2+y^2)$ $d/dt(∂ L/)=0$，故 $x/√(x^2+y^2)=const$。 同理 $y/√(x^2+y^2)=const$。两式相除：$y/x=const$， 即 $y=kx+c$，直线。 极坐标证明。 弧长 $ds=√(r^2+r^2θ^2) dt$。 Lagrange 方程对 $θ$：$∂ L/∂θ=0$（旋转对称）， 故 $∂ L/∂θ=r^2θ/√(r^2+r^2θ^2)=const=h$。 这给出角动量守恒。结合径向方程，积分得 $rsin(θ-θ_0)=const$， 即直线的极坐标方程。"},{"m":"M9","sec":"最速降线（Brachistochrone）","t":"最速降线问题：给定两点 $A$、$B$，求使质点从 $A$ 滑到 $B$ 时间最短的曲线。 变分法给出摆线为解。时间泛函 T=∫_A^B ds√(2g h(s)) 其中 $h(s)$ 为下降高度。Euler-Lagrange 方程求解得摆线参数方程。 这与等时摆的关系：等时摆是等时性（时间与振幅无关）， 最速降线是极值性（时间取最小值）。 最速降线中以释放点为原点、$h$ 为向下的下降高度，记 $h'=dh/dx$，利用被积函数不显含 $x$ 的第一积分。 L=√(1+h'^2)√(2gh) L-h'(∂ L)/(∂ h')=1√(2gh(1+h'^2))=const h(1+h'^2)=2a h=a(1-cosθ), h'=cotθ2 (dx)/(dθ)=(dh/dθ)/(h')=a(1-cosθ) x=a(θ-sinθ), h=a(1-cosθ)"},{"m":"M9","sec":"费马原理与折射定律（作业-6 Q1）","t":"光在介质中速度 $v=c/n$（$n$ 为折射率）。费马原理：光程时间 T=∫ (n(s))/(c) ds 取驻值。考虑两层介质界面（$y=0$），折射率 $n_1$（上）、$n_2$（下）。 路径从 $A=(x_1,y_1)$ 到 $B=(x_2,y_2)$，在界面点 $(x,0)$ 折射。 时间泛函 T(x)=(n_1)/(c)√((x-x_1)^2+y_1^2) +(n_2)/(c)√((x-x_2)^2+y_2^2). 驻值条件 $dT/dx=0$： (n_1)/(c)x-x_1√((x-x_1)^2+y_1^2) +(n_2)/(c)x-x_2√((x-x_2)^2+y_2^2)=0. 设入射角 $θ_1$、折射角 $θ_2$（均与法线夹角），则 n_1sinθ_1=n_2sinθ_2 即 Snell 折射定律。"},{"m":"M9","sec":"数值验证","t":"全部数值实验由配套脚本 qa/numeric_check.py 完成（仅依赖 numpy）。 · 物理量 | 解析值 | 数值值 · $T$（摆线，$a=1,g=1,s_0=1$） | $π=3.14159$ | $3.14159$ · $T$（摆线，$a=1,g=1,s_0=0.5$） | $π=3.14159$ | $3.14159$ · $T_0$（$C=1/8,g=1$） | $π=3.14159$ | $3.14159$ · $T_0$（$C=1/4,g=1$） | $π/(2√(0.5))=2.221$ | $2.221$ 数值验证汇总。全部数值取自 qa/numeric_check.py 的实际输出。"},{"m":"M10","sec":"模块概览","t":"连接两定点的曲线弧长可写成泛函 $S[y]=∫_x_1^x_2√(1+y'^2) dx$。对其应用欧拉–拉格朗日方程： $$(∂ L)/(∂ y) - ddx((∂ L)/(∂ y')) = 0 y'√(1+y'^2) = const$$ ### 从直线到曲面测地线 - 在欧氏平面上，斜率 $y'=const$ 证明两点之间直线最短。 - 将弧长泛函推广至弯曲流形（如球面、柱面），同一变分方程给出的短程极值曲线即为测地线（如球面大圆弧）。"},{"m":"M10","sec":"摆线的等时性（作业-6 Q3）","t":"摆线参数方程： x=a(θ-sinθ) h=a(1+cosθ), 0≤θ≤π $h$ 为相对最低点（$θ=π$）的竖直高度。弧长从最低点向上： s=∫_θ^π 2asin(t/2) dt =4acos(θ/2). 高度： h=a(1+cosθ)=2acos^2(θ/2)=(s^2)/(8a). （作业-6 Q3(a)：$s=4acos(θ/2)$，$h=s^2/(8a)$） 能量守恒：从 $s_0$ 释放，到达 $s$ 时下降高度为 $h_0-h=(s_0^2-s^2)/(8a)$，故 v(s)=√(2g(h_0-h))=√((g)/(4a)) √(s_0^2-s^2). 下滑时间从 $s_0$ 到 $0$： T=∫_0^s_0(ds)/(v(s)) =√((4a)/(g))∫_0^s_0ds√(s_0^2-s^2) =√((4a)/(g))·(π)/(2) =π√((a)/(g)). $T$ 与 $s_0$ 无关，等时性得证（作业-6 Q3(c)）。"},{"m":"M10","sec":"Euler--Lagrange 方程","t":"变分原理的核心工具。给定泛函 $J[y]=∫_x_1^x_2 L(x,y,y') dx$， 驻值条件 $δ J=0$ 导出 (∂ L)/(∂ y)-(d)/(dx)(∂ L)/(∂ y')=0. 这是 Euler—Lagrange 方程。本模块的折射定律、最短路径、等时摆 均由此方程导出。 取端点固定的变分 $δ y(x_1)=δ y(x_2)=0$，对含 $δ y'$ 的项分部积分。 δ J=∫_x_1^x_2((∂ L)/(∂ y)δ y+(∂ L)/(∂ y')(dδ y)/(dx))dx δ J=[(∂ L)/(∂ y')δ y]_x_1^x_2+∫_x_1^x_2[(∂ L)/(∂ y)- ddx((∂ L)/(∂ y'))]δ y dx δ J=0 for all δ y (∂ L)/(∂ y)- ddx((∂ L)/(∂ y'))=0"},{"m":"M10","sec":"最短路径（作业-6 Q2）","t":"二维平面中，两点间最短路径使弧长泛函 S=∫ ds=∫√(x^2+y^2) dt 取驻值。Euler-Lagrange 方程：$L=√(x^2+y^2)$， $∂ L/∂ x=0$，$∂ L/=x/√(x^2+y^2)$ $d/dt(∂ L/)=0$，故 $x/√(x^2+y^2)=const$。 同理 $y/√(x^2+y^2)=const$。两式相除：$y/x=const$， 即 $y=kx+c$，直线。 极坐标证明。 弧长 $ds=√(r^2+r^2θ^2) dt$。 Lagrange 方程对 $θ$：$∂ L/∂θ=0$（旋转对称）， 故 $∂ L/∂θ=r^2θ/√(r^2+r^2θ^2)=const=h$。 这给出角动量守恒。结合径向方程，积分得 $rsin(θ-θ_0)=const$， 即直线的极坐标方程。"},{"m":"M10","sec":"最速降线（Brachistochrone）","t":"最速降线问题：给定两点 $A$、$B$，求使质点从 $A$ 滑到 $B$ 时间最短的曲线。 变分法给出摆线为解。时间泛函 T=∫_A^B ds√(2g h(s)) 其中 $h(s)$ 为下降高度。Euler-Lagrange 方程求解得摆线参数方程。 这与等时摆的关系：等时摆是等时性（时间与振幅无关）， 最速降线是极值性（时间取最小值）。 最速降线中以释放点为原点、$h$ 为向下的下降高度，记 $h'=dh/dx$，利用被积函数不显含 $x$ 的第一积分。 L=√(1+h'^2)√(2gh) L-h'(∂ L)/(∂ h')=1√(2gh(1+h'^2))=const h(1+h'^2)=2a h=a(1-cosθ), h'=cotθ2 (dx)/(dθ)=(dh/dθ)/(h')=a(1-cosθ) x=a(θ-sinθ), h=a(1-cosθ)"},{"m":"M10","sec":"书稿精读","t":"【定理】二阶变分与勒让德条件。极小需δ²I≥0，而F_y′y′≥0必要但不充分。（书稿 ch02.tex:319）"},{"m":"M10","sec":"书稿精读","t":"【定理】曲面测地线方程。弧长变分给出含克里斯托费尔符号的测地线方程。（书稿 ch02.tex:385）"},{"m":"M11","sec":"模块概览","t":"对理想约束系统，约束反力在一切符合约束的虚位移上总虚功为零，静力学平衡的充要条件为虚功原理： $$δ W = ∑_i F_i·_i = 0 保守力 δ V = 0$$ ### 静力平衡与稳定性判据 - **稳定性**：势能驻点 $V'(q_0)=0$ 处，若 $V''(q_0)>0$ 为稳定平衡，$V''(q_0)<0$ 为不稳定平衡。 - **经典应用**：靠墙梯子在摩擦系数 $μ$ 下的临界不滑倾角满足 $tanθ_min=(1)/(2μ)$；同框架可直接处理半球碗均质棒、直角摆与弹簧杆平衡。"},{"m":"M11","sec":"解析结果","t":"· 虚功原理：$δ W=0$，保守系统 $δ V=0$（式（virtual-work）、式（stationary-V））。 · 梯子临界角：$tanθ_min=1/(2μ)$（式（ladder-critical））。 · 弹簧杆平衡：$dV/dθ=0$（spring-rod）。 · 圆柱平衡：$φ=0$（底部，稳定）。"},{"m":"M11","sec":"稳定性的判定","t":"平衡稳定 iff 势能 Hessian 矩阵正定： (∂^2 V)/(∂ q_i∂ q_j)g|_ eq 0. 注意：梯子靠摩擦维持平衡，临界状态是摩擦饱和 $f=μ N$，不是势能 Hessian 奇异；势能 $V=P(l/2)sinθ$ 在该处并没有极小。"},{"m":"M11","sec":"Lagrange 乘子法","t":"约束 $φ_k(q)=0$ 下的平衡：$∂ V/∂ q_j=∑_k λ_k ∂φ_k/∂ q_j$。 $λ_k$ 为约束力（Lagrange 乘子）。这等价于虚功原理。 对相互独立的完整约束引入增广势能，其对 $q_j$ 和 $λ_k$ 的驻值条件给出平衡与约束方程。 V=V-∑_kλ_kφ_k(q) ()/(∂ q_j)=0 (∂ V)/(∂ q_j)=∑_kλ_k(∂φ_k)/(∂ q_j), ()/(∂λ_k)=-φ_k=0 δ W=-δ V=-∑_j∑_kλ_k(∂φ_k)/(∂ q_j)δ q_j=-∑_kλ_kδφ_k=0"},{"m":"M11","sec":"书稿精读","t":"【定理】理想约束与虚功原理。冻结时间取约束容许虚位移，主动力总虚功为零即为平衡条件。（书稿 ch03.tex:163）"},{"m":"M11","sec":"书稿精读","t":"【定理】达朗贝尔原理。把惯性力并入静力平衡并投影到理想约束方向，可消去约束力。（书稿 ch03.tex:241）"},{"m":"M11","sec":"圆槽中的两圆柱（作业-7 Q3）","t":"半径 $R$ 的光滑圆槽，两圆柱半径 $r$，重量 $P_1$、$P_2$。 两柱相切且都与槽相切时，几何关系固定： sinφ=(r)/(R-r) 其中 $φ$ 为每柱中心与槽底方向的夹角。两柱作为整体还可绕槽心转动角度 $α$， 势能 $V=-(P_1+P_2)(R-r)cosφcosα$ 在 $α=0$ 取极小， 故平衡时两柱关于槽底对称；$φ$ 由几何决定，不能由 $dV/dφ=0$ 定出 （$φ=0$ 意味着两柱中心重合，几何上不可能）。 对等重 $P_1=P_2=P$ 的情形，单柱径向平衡给出 N=Pcosφ+Fsinφ, F=Ptanφ N=(P)/(cosφ). $P_1≠ P_2$ 时接触力不再水平，需联立两柱的径向与切向平衡消去 $F$ 后求 $N_1,N_2$。"},{"m":"M12","sec":"模块概览","t":"考虑滑轮具有质量与转动惯量 $I$、半径 $R$ 的 Atwood 机。绳不打滑时滑轮转角 $ϕ=s/R$，以 $m_2$ 向下位移 $s$ 为唯一广义坐标，拉格朗日量为： $$L = (1)/(2)(m_1 + m_2 + (I)/(R^2))s^2 + (m_2 - m_1)gs$$ ### 核心结论 - 由欧拉–拉格朗日方程直接得加速度 $a = ((m_2-m_1)g)/(m_1+m_2+I/R^2)$，滑轮转动惯量以等效质量 $I/R^2$ 计入总惯性。 - 绳两端张力不再相等：$T_1=m_1(g+a)$、$T_2=m_2(g-a)$，张力差 $T_2-T_1=Ia/R^2$ 正好提供滑轮的角加速度力矩。"},{"m":"M12","sec":"数值验证","t":"配套交互页对 $s=a$ 作四阶 Runge—Kutta 积分（步长 $10^-5 s$）， 把 $t=0.4 s$ 的位移与解析解 $s=12 at^2$ 比较；同时用 式（res-T1–res-dT） 计算张力。 · $m_1,m_2,I,R$ | $M_eff$ | $a$ | $T_1$ | $T_2$ | 相对误差 · $1,2,0.5,0.2$ | 15.500 | 0.632903 | 10.442903 | 18.354194 | $1.4×10^-12$ · $0.5,4,1.2,0.3$ | 17.833 | 1.925327 | 5.867664 | 31.538692 | $1.5×10^-12$ · $2,2,1,0.25$ | 20.000 | 0 | 19.620000 | 19.620000 | $0$ 表中单位：质量 kg，长度 m，时间 s，力 N，加速度 m/s$^2$。 相对误差定义为 $|s_ num-s_ ana|/|s_ ana|$（$s_ ana≠0$）。"},{"m":"M12","sec":"讨论","t":"· 等效质量. $M_eff=m_1+m_2+I/R^2$ 把滑轮的转动惯量折算成平动质量。 $I$ 越大，加速度越小，张力差越大。 · 能量. 机械能 $E=12M_effs^2-(m_2-m_1)gs$ 守恒； 重力势能减少量转化为两物体与滑轮的动能。 · 极限. $I→0$ 时 $T_1=T_2$；$m_2→ m_1$ 时 $a→0$，但张力仍为 $mg$。 · 为什么绳两端张力不同. 滑轮有角加速度，必须有净力矩； 绳对轮两侧的切向力差提供这个力矩。 L. D. Landau, E. M. Lifshitz, Mechanics, 3rd ed., Pergamon, 1976. H. Goldstein, C. Poole, J. Safko, Classical Mechanics, 3rd ed., Addison-Wesley, 2002."},{"m":"M12","sec":"书稿精读","t":"【定理】含边界项的诺特定理。作用量只差端点项时，守恒荷为pξ-ELτ-B，漏掉B会得错结论。（书稿 ch03.tex:917）"},{"m":"M12","sec":"书稿精读","t":"【定理】广义动量与循环积分。L不显含某坐标时其共轭动量守恒，角度坐标给出角动量。（书稿 ch03.tex:392）"},{"m":"M12","sec":"拉格朗日量","t":"两物体的速度大小都是 $|s|$，滑轮角速度为 $s/R$。动能为 T=12 m_1s^2+12 m_2s^2+12 I((s)/(R))^2 =12(m_1+m_2+(I)/(R^2))s^2 . 取 $s=0$ 时势能为零，$m_2$ 下降、$m_1$ 上升，势能为 V=-(m_2-m_1)gs . 于是 L=T-V=12 M_effs^2+(m_2-m_1)gs M_eff≡ m_1+m_2+(I)/(R^2)."},{"m":"M12","sec":"运动方程","t":"$L$ 含 $s$ 的一次项，故 $s$ 不是循环坐标。拉格朗日方程 $(d)/(dt)(∂ L)/()-(∂ L)/(∂ s)=0$ 给出 M_effs=(m_2-m_1)g a=s=((m_2-m_1)g)/(m_1+m_2+I/R^2) . $I=0$ 时退化为理想滑轮 $a=(m_2-m_1)g/(m_1+m_2)$。 滑轮转动惯量相当于给系统增加了一个等效质量 $I/R^2$，它只让加速度变小，不改变方向。"},{"m":"M13","sec":"模块概览","t":"质量为 $m$ 的滑块沿置于光滑水平面的斜面（质量 $M$、倾角 $α$）下滑。取斜面水平位移 $X$ 与滑块沿斜面位移 $s$ 为广义坐标： $$L = (1)/(2)(M+m)X^2 + mXscosα + (1)/(2)ms^2 + mgssinα$$ ### 循环坐标与动能分配 - 拉格朗日量不含 $X$，故水平广义动量 $p_X=(M+m)X + mscosα = 0$ 守恒。 - 消去 $X$ 得相对加速度 $a_rel=((M+m)gsinα)/(M+msin^2α)$ 与斜面反冲加速度 $a_X=-(mgsinαcosα)/(M+msin^2α)$；可动斜面的约束反力对滑块做负功、对斜面做等大反号的正功。"},{"m":"M13","sec":"动能分配与约束力做功","t":"下降高度 $h$ 时 $s=h/sinα$，机械能守恒给出总动能 $K=mgh$。 把 式（w-Xdot） 代入动能，可得分给斜面的比例 η≡K_ wedgemgh =(Mk^2)/(Mk^2+m(1-2kcosα+k^2)) k≡(mcosα)/(M+m). 当 $M=2m, α=30^∘$ 时 $k=cosα/3=3/6$，代入得 η=(2)/(9)≈0.2222 . 支持力对物块做负功（物块位移有逆法向分量），其反作用力对斜面做正功； 两者是内力，总功为零，所以系统机械能仍守恒，只是能量在斜面与物块之间转移。"},{"m":"M13","sec":"讨论","t":"· 循环坐标的共同作用. Q3 与 Q5 都因平移对称性得到守恒的水平动量； 它把两自由度问题降为一自由度，再线性化得到小振动频率。 · 约束力做功. Q3 的支持力是内力，对物块做负功、对斜面做正功； 总机械能守恒，能量在两者之间转移。 · 弹簧摆的耦合. 线性阶 $ω_r$ 与 $ω_θ$ 独立； 非线性耦合在 $ω_r≈2ω_θ$ 附近最强。 · 大质量极限. Q5 的 $M→∞$ 给出固定悬点单摆，是检验公式的简单极限。 L. D. Landau, E. M. Lifshitz, Mechanics, 3rd ed., Pergamon, 1976. H. Goldstein, C. Poole, J. Safko, Classical Mechanics, 3rd ed., Addison-Wesley, 2002. J. R. Taylor, Classical Mechanics, University Science Books, 2005."},{"m":"M13","sec":"平衡位置与两种小振动","t":"静平衡取 $θ=0, r=θ=0$，由 式（s-r） 得 k(r_0-l_0)=mg r_0=l_0+(mg)/(k) . 在 $r=r_0+δ, θ1$ 处线性化：$δ=-(k/m)δ$， $r_0θ=-gθ$，两种模式解耦，频率为 ω_r=√((k)/(m)) ω_θ=√((g)/(r_0))=√((g)/(l_0+mg/k)) . 线性阶两种振动独立；非线性项（$θ^2$ 与 $2rθ$）会让它们耦合， 当 $ω_r≈2ω_θ$ 时出现内共振，交互页可直接看到拍频与能量交换。"},{"m":"M13","sec":"数值验证","t":"交互页对 Q3 用解析加速度驱动动画，对 Q4、Q5 用四阶 Runge—Kutta（步长 $2×10^-3 s$ 与 $4×10^-3 s$）积分非线性方程。 · 量 | 参数 | 解析值 | 数值/检查值 · Q3 $a_ rel$ | $M=2m,α=30^∘$ | $6.5400 m/s^2$ | $6.5400$ · Q3 $a_X$ | $M=2m,α=30^∘$ | $-1.8879 m/s^2$ | $-1.8879$ · Q3 $η$ | $M=2m,α=30^∘$ | $2/9=0.222222$ | $0.222222$ · Q3 动量残差 | 同上 | 0 | $0$ · Q4 $r_0$ | $k=80,l_0=0.5,m=1$ | $0.622625 m$ | $0.622625$ · Q4 $ω_r$ | 同上 | $8.9443 rad/s$ | $8.9443$ · Q4 $ω_θ$ | 同上 | $3.9694 rad/s$ | $3.9694$ · Q5 $ω$ | $M/m=3,l=1$ | $3.6166 rad/s$ | $3.6166$ · Q5 $M→∞$ | $l=1$ | $3.1321 rad/s$ | $3.1321$ · Q5 $p_X$ | 任意 $θ,θ$ | 0 | $<10^-12$"},{"m":"M13","sec":"拉格朗日量与水平动量","t":"小车质量 $M$、单摆质量 $m$、摆长 $l$；取小车位置 $X$ 与摆角 $θ$ 为坐标。 摆球位置为 $x=X+lsinθ, y=-lcosθ$，故 L=12(M+m)X^2+mlcosθ Xθ+12ml^2θ^2+mglcosθ . $X$ 是循环坐标，水平总动量守恒： p_X=(M+m)X+mlcosθ θ=常量. 总水平动量为零时 X=-(mlcosθ)/(M+m)θ . $θ$ 的方程为 θ=-(M+m)gsinθ+mlsinθcosθ θ^2 l(M+msin^2θ). 先保留小车加速度列出两条拉格朗日方程，再用水平动量守恒消去 $X$。 (M+m)X+ml(cosθ θ-sinθ θ^2)=0 lθ+Xcosθ+gsinθ=0 l(M+msin^2θ)θ+(M+m)gsinθ+mlsinθcosθ θ^2=0"},{"m":"M13","sec":"书稿精读","t":"【定理】非完整系统的达朗贝尔乘子方程。仿射速度约束的虚位移取系数齐次核，反力落在约束行空间。（书稿 ch03.tex:972）"},{"m":"M14","sec":"模块概览","t":"质量 $m$ 的小球悬于原长 $l_0$、劲度 $k$ 的轻弹簧末端在竖直平面内运动，广义坐标取径长 $r$ 与摆角 $θ$： $$L = (1)/(2)m(r^2 + r^2θ^2) - (1)/(2)k(r-l_0)^2 + mgrcosθ$$ ### 平衡位置与两支简正频率 - 静平衡位置为 $r_0 = l_0 + (mg)/(k)$、$θ_0=0$。 - 在平衡点附近做二阶小振动展开，径向伸缩与角向摆动退耦为两支独立简正模：$ω_r = √(k/m)$、$ω_θ = √(g/r_0)$；大振幅时当 $ω_r≈ 2ω_θ$ 会出现显著的参量共振能量交换。"},{"m":"M14","sec":"动能分配与约束力做功","t":"下降高度 $h$ 时 $s=h/sinα$，机械能守恒给出总动能 $K=mgh$。 把 式（w-Xdot） 代入动能，可得分给斜面的比例 η≡K_ wedgemgh =(Mk^2)/(Mk^2+m(1-2kcosα+k^2)) k≡(mcosα)/(M+m). 当 $M=2m, α=30^∘$ 时 $k=cosα/3=3/6$，代入得 η=(2)/(9)≈0.2222 . 支持力对物块做负功（物块位移有逆法向分量），其反作用力对斜面做正功； 两者是内力，总功为零，所以系统机械能仍守恒，只是能量在斜面与物块之间转移。"},{"m":"M14","sec":"讨论","t":"· 循环坐标的共同作用. Q3 与 Q5 都因平移对称性得到守恒的水平动量； 它把两自由度问题降为一自由度，再线性化得到小振动频率。 · 约束力做功. Q3 的支持力是内力，对物块做负功、对斜面做正功； 总机械能守恒，能量在两者之间转移。 · 弹簧摆的耦合. 线性阶 $ω_r$ 与 $ω_θ$ 独立； 非线性耦合在 $ω_r≈2ω_θ$ 附近最强。 · 大质量极限. Q5 的 $M→∞$ 给出固定悬点单摆，是检验公式的简单极限。 L. D. Landau, E. M. Lifshitz, Mechanics, 3rd ed., Pergamon, 1976. H. Goldstein, C. Poole, J. Safko, Classical Mechanics, 3rd ed., Addison-Wesley, 2002. J. R. Taylor, Classical Mechanics, University Science Books, 2005."},{"m":"M14","sec":"书稿精读","t":"【定理】广义本征值与质量加权正交。KA=λMA经M^-1/2对称化，振型按质量内积正交并归一化为简正坐标。（书稿 ch04.tex:305）"},{"m":"M14","sec":"平衡位置与两种小振动","t":"静平衡取 $θ=0, r=θ=0$，由 式（s-r） 得 k(r_0-l_0)=mg r_0=l_0+(mg)/(k) . 在 $r=r_0+δ, θ1$ 处线性化：$δ=-(k/m)δ$， $r_0θ=-gθ$，两种模式解耦，频率为 ω_r=√((k)/(m)) ω_θ=√((g)/(r_0))=√((g)/(l_0+mg/k)) . 线性阶两种振动独立；非线性项（$θ^2$ 与 $2rθ$）会让它们耦合， 当 $ω_r≈2ω_θ$ 时出现内共振，交互页可直接看到拍频与能量交换。"},{"m":"M14","sec":"数值验证","t":"交互页对 Q3 用解析加速度驱动动画，对 Q4、Q5 用四阶 Runge—Kutta（步长 $2×10^-3 s$ 与 $4×10^-3 s$）积分非线性方程。 · 量 | 参数 | 解析值 | 数值/检查值 · Q3 $a_ rel$ | $M=2m,α=30^∘$ | $6.5400 m/s^2$ | $6.5400$ · Q3 $a_X$ | $M=2m,α=30^∘$ | $-1.8879 m/s^2$ | $-1.8879$ · Q3 $η$ | $M=2m,α=30^∘$ | $2/9=0.222222$ | $0.222222$ · Q3 动量残差 | 同上 | 0 | $0$ · Q4 $r_0$ | $k=80,l_0=0.5,m=1$ | $0.622625 m$ | $0.622625$ · Q4 $ω_r$ | 同上 | $8.9443 rad/s$ | $8.9443$ · Q4 $ω_θ$ | 同上 | $3.9694 rad/s$ | $3.9694$ · Q5 $ω$ | $M/m=3,l=1$ | $3.6166 rad/s$ | $3.6166$ · Q5 $M→∞$ | $l=1$ | $3.1321 rad/s$ | $3.1321$ · Q5 $p_X$ | 任意 $θ,θ$ | 0 | $<10^-12$"},{"m":"M14","sec":"拉格朗日量与水平动量","t":"小车质量 $M$、单摆质量 $m$、摆长 $l$；取小车位置 $X$ 与摆角 $θ$ 为坐标。 摆球位置为 $x=X+lsinθ, y=-lcosθ$，故 L=12(M+m)X^2+mlcosθ Xθ+12ml^2θ^2+mglcosθ . $X$ 是循环坐标，水平总动量守恒： p_X=(M+m)X+mlcosθ θ=常量. 总水平动量为零时 X=-(mlcosθ)/(M+m)θ . $θ$ 的方程为 θ=-(M+m)gsinθ+mlsinθcosθ θ^2 l(M+msin^2θ). 先写出摆角的欧拉—拉格朗日方程，再用水平动量方程消去小车加速度。 lθ+Xcosθ+gsinθ=0 (M+m)X+ml(cosθθ-sinθθ^2)=0 l(M+msin^2θ)θ+(M+m)gsinθ+mlsinθcosθθ^2=0"},{"m":"M15","sec":"模块概览","t":"质量 $m$、摆长 $l$ 的单摆悬挂于光滑水平面上质量 $M$ 的小车上，广义坐标取小车位移 $X$ 与摆角 $θ$： $$L = (1)/(2)(M+m)X^2 + mlcosθ Xθ + (1)/(2)ml^2θ^2 + mglcosθ$$ ### 水平动量守恒与耦合频率 - 坐标 $X$ 循环，水平总动量 $p_X = (M+m)X + mlcosθ θ = 0$ 守恒，小车与摆球反向摆动保持质心水平静止。 - 小角度线性化后消去 $X$，得耦合小振动频率 $ω = √((g(M+m))/(Ml))$；当 $M→∞$ 时严格退化为固定悬点单摆 $√(g/l)$。"},{"m":"M15","sec":"动能分配与约束力做功","t":"下降高度 $h$ 时 $s=h/sinα$，机械能守恒给出总动能 $K=mgh$。 把 式（w-Xdot） 代入动能，可得分给斜面的比例 η≡K_ wedgemgh =(Mk^2)/(Mk^2+m(1-2kcosα+k^2)) k≡(mcosα)/(M+m). 当 $M=2m, α=30^∘$ 时 $k=cosα/3=3/6$，代入得 η=(2)/(9)≈0.2222 . 支持力对物块做负功（物块位移有逆法向分量），其反作用力对斜面做正功； 两者是内力，总功为零，所以系统机械能仍守恒，只是能量在斜面与物块之间转移。"},{"m":"M15","sec":"讨论","t":"· 循环坐标的共同作用. Q3 与 Q5 都因平移对称性得到守恒的水平动量； 它把两自由度问题降为一自由度，再线性化得到小振动频率。 · 约束力做功. Q3 的支持力是内力，对物块做负功、对斜面做正功； 总机械能守恒，能量在两者之间转移。 · 弹簧摆的耦合. 线性阶 $ω_r$ 与 $ω_θ$ 独立； 非线性耦合在 $ω_r≈2ω_θ$ 附近最强。 · 大质量极限. Q5 的 $M→∞$ 给出固定悬点单摆，是检验公式的简单极限。 L. D. Landau, E. M. Lifshitz, Mechanics, 3rd ed., Pergamon, 1976. H. Goldstein, C. Poole, J. Safko, Classical Mechanics, 3rd ed., Addison-Wesley, 2002. J. R. Taylor, Classical Mechanics, University Science Books, 2005."},{"m":"M15","sec":"书稿精读","t":"【定理】周期链色散与群速度。ω=2√(k/m)|sin(pa/2)|，第一布里渊区足够，区边界群速度为零。（书稿 ch04.tex:698）"},{"m":"M15","sec":"平衡位置与两种小振动","t":"静平衡取 $θ=0, r=θ=0$，由 式（s-r） 得 k(r_0-l_0)=mg r_0=l_0+(mg)/(k) . 在 $r=r_0+δ, θ1$ 处线性化：$δ=-(k/m)δ$， $r_0θ=-gθ$，两种模式解耦，频率为 ω_r=√((k)/(m)) ω_θ=√((g)/(r_0))=√((g)/(l_0+mg/k)) . 线性阶两种振动独立；非线性项（$θ^2$ 与 $2rθ$）会让它们耦合， 当 $ω_r≈2ω_θ$ 时出现内共振，交互页可直接看到拍频与能量交换。"},{"m":"M15","sec":"数值验证","t":"交互页对 Q3 用解析加速度驱动动画，对 Q4、Q5 用四阶 Runge—Kutta（步长 $2×10^-3 s$ 与 $4×10^-3 s$）积分非线性方程。 · 量 | 参数 | 解析值 | 数值/检查值 · Q3 $a_ rel$ | $M=2m,α=30^∘$ | $6.5400 m/s^2$ | $6.5400$ · Q3 $a_X$ | $M=2m,α=30^∘$ | $-1.8879 m/s^2$ | $-1.8879$ · Q3 $η$ | $M=2m,α=30^∘$ | $2/9=0.222222$ | $0.222222$ · Q3 动量残差 | 同上 | 0 | $0$ · Q4 $r_0$ | $k=80,l_0=0.5,m=1$ | $0.622625 m$ | $0.622625$ · Q4 $ω_r$ | 同上 | $8.9443 rad/s$ | $8.9443$ · Q4 $ω_θ$ | 同上 | $3.9694 rad/s$ | $3.9694$ · Q5 $ω$ | $M/m=3,l=1$ | $3.6166 rad/s$ | $3.6166$ · Q5 $M→∞$ | $l=1$ | $3.1321 rad/s$ | $3.1321$ · Q5 $p_X$ | 任意 $θ,θ$ | 0 | $<10^-12$"},{"m":"M15","sec":"拉格朗日量与水平动量","t":"小车质量 $M$、单摆质量 $m$、摆长 $l$；取小车位置 $X$ 与摆角 $θ$ 为坐标。 摆球位置为 $x=X+lsinθ, y=-lcosθ$，故 L=12(M+m)X^2+mlcosθ Xθ+12ml^2θ^2+mglcosθ . $X$ 是循环坐标，水平总动量守恒： p_X=(M+m)X+mlcosθ θ=常量. 总水平动量为零时 X=-(mlcosθ)/(M+m)θ . $θ$ 的方程为 θ=-(M+m)gsinθ+mlsinθcosθ θ^2 l(M+msin^2θ). 先写出摆角的欧拉—拉格朗日方程，再用水平动量方程消去小车加速度。 lθ+Xcosθ+gsinθ=0 (M+m)X+ml(cosθθ-sinθθ^2)=0 l(M+msin^2θ)θ+(M+m)gsinθ+mlsinθcosθθ^2=0"},{"m":"M16","sec":"模块概览","t":"单摆精确运动方程为 $θ + ω_0^2sinθ = 0$（$ω_0=√(g/l)$）。大振幅下 $sinθ≈θ-(θ^3)/(6)$ 的软化非线性使恢复力弱于线性弹簧，周期随最大摆角 $θ_0$ 增长： $$T(θ_0) = T_0(1 + (1)/(16)θ_0^2 + (11)/(3072)θ_0^4 + ⋯), T_0 = 2π√((l)/(g))$$ ### 非线性微扰与相图 - 常规微扰展开会产生随时间发散的久期项，Lindstedt–Poincaré 方法通过同步展开频率 $ω(θ_0)$ 消除久期项并导出周期修正。 - 精确周期由第一类完全椭圆积分给出，当 $θ_0→π$ 趋近相空间分界线时周期对数发散。"},{"m":"M16","sec":"讨论","t":"非线性振荡的重要性。 单摆周期的振幅修正 $θ_0^2/16$ 是非线性效应的体现。 大振幅时需用椭圆积分精确计算。 Lorentz 力的应用。 回旋运动与 $E$ 漂移是等离子体物理、 加速器物理的基础。 圆柱脱离的物理解释。 质点在圆柱上滑动时，法向力 $N=mgcosθ-mv^2/R$。 当 $N=0$ 时脱离，即 $mgcosθ=mv^2/R$。 结合能量守恒 $v^2=2gR(1-cosθ)$，得 $cosθ=2/3$。 单摆的非线性效应。 大振幅单摆周期比小振幅长。振幅 $θ_0=90^∘$ 时， 周期增加约 $18%$。 与作业题的对照。 表 numeric 覆盖了作业-1 Q4—Q6 的核心结论。 H. Goldstein, C. P. Poole, J. L. Safko Classical Mechanics, 3rd ed., Pearson, 2002. （运动学与非线性振动。） J. D. Jackson, Classical Electrodynamics, 3rd ed., Wiley, 1999. （Lorentz 力。） 周衍柏，《理论力学教程》（第三版），高等教育出版社，2009. （运动学与振动。）"},{"m":"M16","sec":"相空间与非线性振荡","t":"单摆相空间：$(θ,θ)$ 平面。小振幅：椭圆（简谐）。 大振幅：扭曲的闭合曲线。分界线（separatrix） separates 振荡与旋转。 能量 $E=12 m L^2 θ^2 - mgLcosθ$。 $E<-mgL$ 不允许；$-mgL<E<mgL$：振荡；$E>mgL$：旋转；$E=mgL$：分界线（过最高点 $θ=π$ 的临界轨道）。"},{"m":"M16","sec":"非线性振荡的近似方法","t":"Lindstedt-Poincaré 方法。 对 $x+ω_0^2 x+ε x^3=0$，设 $ω=ω_0+εω_1+⋯$， $x=x_0+ε x_1+⋯$，消除长期项（secular term）得频率修正。 多尺度方法。 引入快时间 $T_0=t$ 与慢时间 $T_1=ε t$，分离不同时间尺度。 数值积分。 RK4 等数值方法可直接积分非线性振荡方程，无需解析近似。 令振幅为 $A$，用伸缩时间展开，并要求一阶方程没有共振驱动项。 τ=ω t, x_0=Acosτ ω_0^2((d^2x_1)/(dτ^2)+x_1)=(2ω_0ω_1A-34A^3)cosτ-14A^3cos3τ 2ω_0ω_1A-34A^3=0 ω_1=(3A^2)/(8ω_0) ω=ω_0+(3ε A^2)/(8ω_0)+O(ε^2)"},{"m":"M16","sec":"单摆周期修正（作业-1 Q5）","t":"单摆运动方程：$θ+(g/L)sinθ=0$。 精确周期（椭圆积分）： T=4√((L)/(g)) K(sin^2(θ_0/2)) 其中 $K$ 为第一类完全椭圆积分。展开到 $θ_0^2$ 阶： K(k)≈ (π)/(2)(1+(k)/(4)+(9k^2)/(64)+⋯) k=sin^2(θ_0/2)≈ θ_0^2/4. T≈ 2π√((L)/(g))(1+(θ_0^2)/(16)+⋯). T≈ 2π√((L)/(g))(1+(θ_0^2)/(16))"},{"m":"M16","sec":"书稿精读","t":"【极限】零曲率平衡的三种命运。q^4稳定、-q^4不稳定、零势能则任意小初速都漂离，二阶判据失效。（书稿 ch04.tex:67）"},{"m":"M16","sec":"书稿精读","t":"【例题】双摆的精确耦合方程。逐项微分cosΔ项后速度二次项抵消，质量矩阵行列式恒正可解加速度。（书稿 ch03.tex:547）"},{"m":"M17","sec":"模块概览","t":"双摆由两根刚性轻杆串联构成两自由度保守系统，能量严格守恒，但拉格朗日方程含强烈的非线性惯性耦合。 ### 从规则振动到确定性混沌 - **小振幅区**：系统分解为同相与反相两支规则简正模，相轨线局限在不变环面上。 - **大振幅混沌区**：轨道对初始条件呈现指数敏感分离（正 Lyapunov 指数 $λ>0$），微小的初角差异会在数个周期内放大至完全不同的运动形态。"},{"m":"M17","sec":"讨论","t":"非线性振荡的重要性。 单摆周期的振幅修正 $θ_0^2/16$ 是非线性效应的体现。 大振幅时需用椭圆积分精确计算。 Lorentz 力的应用。 回旋运动与 $E$ 漂移是等离子体物理、 加速器物理的基础。 圆柱脱离的物理解释。 质点在圆柱上滑动时，法向力 $N=mgcosθ-mv^2/R$。 当 $N=0$ 时脱离，即 $mgcosθ=mv^2/R$。 结合能量守恒 $v^2=2gR(1-cosθ)$，得 $cosθ=2/3$。 单摆的非线性效应。 大振幅单摆周期比小振幅长。振幅 $θ_0=90^∘$ 时， 周期增加约 $18%$。 与作业题的对照。 表 numeric 覆盖了作业-1 Q4—Q6 的核心结论。 H. Goldstein, C. P. Poole, J. L. Safko Classical Mechanics, 3rd ed., Pearson, 2002. （运动学与非线性振动。） J. D. Jackson, Classical Electrodynamics, 3rd ed., Wiley, 1999. （Lorentz 力。） 周衍柏，《理论力学教程》（第三版），高等教育出版社，2009. （运动学与振动。）"},{"m":"M17","sec":"相空间与非线性振荡","t":"单摆相空间：$(θ,θ)$ 平面。小振幅：椭圆（简谐）。 大振幅：扭曲的闭合曲线。分界线（separatrix） separates 振荡与旋转。 能量 $E=12 m L^2 θ^2 - mgLcosθ$。 $E<-mgL$ 不允许；$-mgL<E<mgL$：振荡；$E>mgL$：旋转；$E=mgL$：分界线（过最高点 $θ=π$ 的临界轨道）。"},{"m":"M17","sec":"非线性振荡的近似方法","t":"Lindstedt-Poincaré 方法。 对 $x+ω_0^2 x+ε x^3=0$，设 $ω=ω_0+εω_1+⋯$， $x=x_0+ε x_1+⋯$，消除长期项（secular term）得频率修正。 多尺度方法。 引入快时间 $T_0=t$ 与慢时间 $T_1=ε t$，分离不同时间尺度。 数值积分。 RK4 等数值方法可直接积分非线性振荡方程，无需解析近似。 令振幅为 $A$，用伸缩时间展开，并要求一阶方程没有共振驱动项。 τ=ω t, x_0=Acosτ ω_0^2((d^2x_1)/(dτ^2)+x_1)=(2ω_0ω_1A-34A^3)cosτ-14A^3cos3τ 2ω_0ω_1A-34A^3=0 ω_1=(3A^2)/(8ω_0) ω=ω_0+(3ε A^2)/(8ω_0)+O(ε^2)"},{"m":"M17","sec":"单摆周期修正（作业-1 Q5）","t":"单摆运动方程：$θ+(g/L)sinθ=0$。 精确周期（椭圆积分）： T=4√((L)/(g)) K(sin^2(θ_0/2)) 其中 $K$ 为第一类完全椭圆积分。展开到 $θ_0^2$ 阶： K(k)≈ (π)/(2)(1+(k)/(4)+(9k^2)/(64)+⋯) k=sin^2(θ_0/2)≈ θ_0^2/4. T≈ 2π√((L)/(g))(1+(θ_0^2)/(16)+⋯). T≈ 2π√((L)/(g))(1+(θ_0^2)/(16))"},{"m":"M17","sec":"书稿精读","t":"【例题】旋转圆环小珠的分岔。超临界转速出现两支新平衡，最低点线性恢复项变号须查高阶。（书稿 ch03.tex:592）"},{"m":"M18","sec":"模块概览","t":"刚体绕定轴或定点的转动动力学以惯量张量 $I_ij=∑ m(r^2δ_ij-x_ix_j)$ 为核心几何量。 $$I = I_cm + md^2, L = Iω, T_rot = (1)/(2)ωω$$ ### 核心主题 - **平行轴定理与质量分布**：由对称性与积分计算球冠质心、薄圆盘惯量与复合刚体转动惯量。 - **角动量守恒与球壳定理**：涵盖圆环上甲虫爬行的内力角动量守恒，以及牛顿均匀球壳外部等效质点、内部引力为零的几何证明。"},{"m":"M18","sec":"讨论","t":"角动量守恒的普遍性。 甲虫-圆环问题是角动量守恒的经典演示。系统初始角动量为零， 甲虫运动时环反向旋转，保持总角动量为零。 Newton 球壳定理的意义。 球壳定理是 Newton 万有引力理论的基石，解释了为什么行星可视为质点， 以及为什么球壳内部引力为零。 球冠质心的应用。 球冠质心公式用于计算球形天体（如行星、恒星）的引力势与转动惯量。 Newton 球壳定理的应用。 球壳定理解释了为什么行星内部（r<R）引力随 r 线性增加（$g∝ r$）， 而外部（r>R）按 $1/r^2$ 衰减。 与作业题的对照。 表 numeric 覆盖了作业-4 Q1—Q4 的全部数值结果。 H. Goldstein, C. P. Poole, J. L. Safko Classical Mechanics, 3rd ed., Pearson, 2002. （刚体、角动量、引力势。） I. Newton, Principia Mathematica, 1687. （球壳定理。） 周衍柏，《理论力学教程》（第三版），高等教育出版社，2009. （刚体几何与角动量。）"},{"m":"M18","sec":"转动惯量与平行轴定理","t":"平行轴定理：$I=I_ cm+Md^2$，其中 $d$ 为新轴到质心轴的距离。 对圆盘：$I_ cm=12 MR^2$（中心轴），$I_ edge=I_ cm+MR^2=32 MR^2$（边缘轴）。 取质心为原点、两平行轴沿 $z$ 方向，新轴在横截面内位于 $(d,0)$。 I=[(x-d)^2+y^2r] dm I=∫(x^2+y^2) dm-2d∫ x dm+d^2 ∫ x dm=0 I=I_ cm+Md^2"},{"m":"M18","sec":"Newton 球壳定理的证明概要","t":"球壳定理的证明利用高斯定律类比：引力场 $g$ 的通量 $∮ g=-4π GM_ enc$。 壳内 $M_ enc=0$，故 $g=0$；壳外 $M_ enc=M$， 故 $g=-GM/r^2 e_r$。"},{"m":"M18","sec":"Newton 球壳定理（作业-4 Q4）","t":"质量为 $M$ 的均匀球壳，半径 $a$。质点质量 $m$ 在距中心 $r$ 处。取无穷远处势能为 0，即 $V(∞)=0$。 壳内（$r<a$）： 引力势能为常数： V=-(GMm)/(a). 引力为零。 壳外（$r>a$）： 等效于质量 $M$ 集中于中心： V=-(GMm)/(r). 球壳表面（$r=a$）： $V=-GMm/a$，与壳内连续。"},{"m":"M18","sec":"书稿精读","t":"【定理】平行轴与垂直轴定理。I_O=I_C+M(R²1−RRᵀ)，薄板另满足I_z=I_x+I_y。（书稿 ch05.tex:485）"},{"m":"M18","sec":"书稿精读","t":"【定理】刚体动能分解（柯尼希定理）。T=½Mv_C²+½ωᵀI_Cω，平动与绕质心转动分离。（书稿 ch05.tex:850）"},{"m":"M19","sec":"模块概览","t":"在固连于刚体的惯量主轴系（主转动惯量 $I_1 < I_2 < I_3$）中，无外力矩自由刚体的角速度演化服从欧拉动力学方程： $$I_1ω_1 = (I_2-I_3)ω_2ω_3, I_2ω_2 = (I_3-I_1)ω_3ω_1, I_3ω_3 = (I_1-I_2)ω_1ω_2$$ ### 网球拍定理（Dzhanibekov 效应） - 空间总角动量 $J$ 与转动动能 $T=(1)/(2)∑ I_iω_i^2$ 同时守恒，角速度矢量在惯量椭球与角动量椭球的交线（波因索极迹）上运动。 - 绕最大轴（$I_3$）与最小轴（$I_1$）的定轴转动线性稳定；绕中间轴（$I_2$）的转动不稳定，微小扰动即诱发周期性 $180^∘$ 翻转。"},{"m":"M19","sec":"书稿精读","t":"【定理】网球拍定理。绕最大或最小主轴的转动稳定，绕中间主轴不稳定。（书稿 ch05.tex:1309）"},{"m":"M19","sec":"中间轴稳定性","t":"主惯量满足 I1<I2<I3 时，绕中间主轴 2 的转动不稳定。给 ω2 一个很小的横向扰动，扰动会指数增长，刚体表现为周期性的翻转（网球拍效应）；绕最大或最小主轴的转动则是稳定的。 在 $ω_2=Ω$ 的匀速转动附近，仅保留横向扰动的一阶项。 I_1δω_1=-(I_3-I_2)Ωδω_3, I_3δω_3=-(I_2-I_1)Ωδω_1 δω_1=((I_3-I_2)(I_2-I_1))/(I_1I_3)Ω^2δω_1≡λ^2δω_1 λ^2>0 δω_1=C_+e^λ t+C_-e^-λ t"},{"m":"M19","sec":"书稿精读","t":"【定理】欧拉方程。体主轴系中Iω̇+ω×Iω=M，非线性项来自坐标转动。（书稿 ch05.tex:1175）"},{"m":"M19","sec":"姿态更新","t":"欧拉方程给出体轴角速度后，用单位四元数 q 更新姿态：q̇=½ q⊗(0,ω_b)，每步归一化。用 q 而不是欧拉角可避免万向节死锁，但归一化并不自动保证能量和角动量长期准确，因此仍要单独监控 J 与 T。"},{"m":"M20","sec":"稳定性与临界角速度","t":"定义有效势 V_ eff(θ)=-12mR^2Ω^2sin^2θ-mgRcosθ 使 $θ=-(1)/(mR^2)V_ eff'(θ)$。其二阶导数为 V_ eff''(θ)=-mR^2Ω^2cos2θ+mgRcosθ . 在三个平衡点处： · V_ eff''(0) | =mR(g-RΩ^2) >0, | Ω<Ω_c (稳定), · <0, | Ω>Ω_c (不稳定); V_ eff''(π) | =-mR(g+RΩ^2)<0 (恒不稳定); 式（r-stpi） · V_ eff''(θ_ eq) | =mR^2Ω^2sin^2θ_ eq>0 (稳定). 式（r-steq） 所以 $Ω_c=√(g/R)$ 是分岔点：低于它最低点稳定；高于它最低点失稳， 出现一对对称的稳定斜平衡 $±θ_ eq$。"},{"m":"M20","sec":"模块概览","t":"质量 $m$ 的珠子套在半径 $R$、以恒角速度 $Ω$ 绕竖直直径旋转的光滑圆环上，拉格朗日量与旋转系有效势为： $$L = (1)/(2)mR^2θ^2 + (1)/(2)mR^2Ω^2sin^2θ + mgRcosθ, V_eff(θ) = -mgRcosθ - (1)/(2)mR^2Ω^2sin^2θ$$ ### 超临界叉式分岔与雅可比积分 - 当 $Ω < Ω_c = √(g/R)$ 时，最低点 $θ=0$ 是唯一稳定平衡。 - 当 $Ω > Ω_c$ 时，$θ=0$ 失稳，分岔出两个对称稳定平衡点 $θ_eq=±arccos(g/Ω^2 R)$；尽管机械能不守恒（电机做功），雅可比积分 $E=(1)/(2)mR^2θ^2+V_eff(θ)$ 严格守恒。"},{"m":"M20","sec":"守恒量与回旋圆心","t":"定义回旋圆心 X_c=x+(y)/(ω_c) Y_c=y-(x)/(ω_c). 用 式（c-Qx–c-Qy） 可得 Q_y=mω_c X_c, Q_x=-mω_c Y_c . 所以两个守恒的诺特荷（相差常数因子）就是回旋圆心的坐标： 平移对称性锁定的是圆心，而不是粒子的瞬时动量。"},{"m":"M20","sec":"讨论","t":"· 两个“能量”. 圆环问题里 $E$ 守恒而 $E_ mech$ 不守恒， 差值由电机做功补上；这与“约束随时间变化时机械能不守恒”是同一件事。 · 两个“动量”. 磁场问题里机械动量与规范动量都不守恒， 但平移导致的诺特荷守恒；守恒量对应回旋圆心，而非瞬时速度。 · 分岔. $Ω$ 从下方穿过 $Ω_c$ 时，$θ=0$ 由稳定变不稳定， 一对斜平衡同时出现，是典型的超临界叉式分岔。 L. D. Landau, E. M. Lifshitz, Mechanics, 3rd ed., Pergamon, 1976. H. Goldstein, C. Poole, J. Safko, Classical Mechanics, 3rd ed., Addison-Wesley, 2002. J. D. Jackson, Classical Electrodynamics, 3rd ed., Wiley, 1999."},{"m":"M20","sec":"动量守恒与诺特荷","t":"机械动量 $p_ mech=mv$ 的方向不断改变，不守恒； 正则动量 p_x=mx-(qB)/(2)y, p_y=my+(qB)/(2)x 也不守恒，因为 $L$ 显含 $x,y$。但 $x,y$ 平移只让 $L$ 改变一个全导数， 诺特荷仍然存在： · Q_x | =mx-qBy · Q_y | =my+qBx. 直接求导可验证 $Q_x=Q_y=0$。 平移参数取 $ϵ$，若 $δ L=ϵ dF/dt$，诺特荷就是相应正则动量减去 $F$。 δ_xL=ϵ(qB)/(2)y=ϵ(d)/(dt)((qB)/(2)y), Q_x=p_x-(qB)/(2)y=mx-qBy δ_yL=-ϵ(qB)/(2)x=ϵ(d)/(dt)(-(qB)/(2)x), Q_y=p_y+(qB)/(2)x=my+qBx"},{"m":"M20","sec":"数值验证","t":"交互页对圆环方程 式（r-eom） 作四阶 Runge—Kutta 积分（步长 $2×10^-3 s$）， 对磁场问题用解析解 式（c-eom） 采样。 · 量 | 参数 | 解析值 | 数值/检查值 · Q5 $Ω_c$ | $R=1.2$ | $2.8592 rad/s$ | $2.8592$ · Q5 $θ_ eq$ | $Ω=3.0$ | $24.72^∘$ | $24.72^∘$ · Q5 $V_ eff''(0)$ | $Ω>Ω_c$ | $<0$ | 失稳 · Q5 $V_ eff''(θ_ eq)$ | $Ω=3.0$ | $2.267>0$ | 稳定 · Q5 $$ | RK4，$2 s$ | 0 | $<10^-6$ · Q6 $r_c$ | $B=1.2,v_0=1$ | $0.8333$ | $0.8333$ · Q6 $Q_x$ | 同上 | $1$ | $1$（$Δ Q_x<10^-12$） · Q6 $Q_y$ | 同上 | $0$ | $0$（$Δ Q_y<10^-12$） · Q6 $Δ p_x$ | 一个回旋周期 | $≠0$ | $1.000$ · Q6 $Q_y=mω_cX_c$ | 圆心 $(0,-0.8333)$ | $0$ | 一致"},{"m":"M20","sec":"雅可比积分 $E$","t":"由于 $∂ L/∂ t=0$，雅可比积分守恒： E=θ(∂ L)/(∂θ)-L =12mR^2θ^2-12mR^2Ω^2sin^2θ-mgRcosθ . 而惯性系中的机械能为 E_ mech=12mR^2(θ^2+Ω^2sin^2θ)-mgRcosθ =E+mR^2Ω^2sin^2θ . 二者不相等：差值 $mR^2Ω^2sin^2θ$ 是珠子随环转动的方位动能， 由电机维持 $Ω$ 时输入。$E$ 是旋转约束下的有效能量，不是惯性系机械能。"},{"m":"M21","sec":"稳定性与临界角速度","t":"定义有效势 V_ eff(θ)=-12mR^2Ω^2sin^2θ-mgRcosθ 使 $θ=-(1)/(mR^2)V_ eff'(θ)$。其二阶导数为 V_ eff''(θ)=-mR^2Ω^2cos2θ+mgRcosθ . 在三个平衡点处： · V_ eff''(0) | =mR(g-RΩ^2) >0, | Ω<Ω_c (稳定), · <0, | Ω>Ω_c (不稳定); V_ eff''(π) | =-mR(g+RΩ^2)<0 (恒不稳定); 式（r-stpi） · V_ eff''(θ_ eq) | =mR^2Ω^2sin^2θ_ eq>0 (稳定). 式（r-steq） 所以 $Ω_c=√(g/R)$ 是分岔点：低于它最低点稳定；高于它最低点失稳， 出现一对对称的稳定斜平衡 $±θ_ eq$。"},{"m":"M21","sec":"守恒量与回旋圆心","t":"定义回旋圆心 X_c=x+(y)/(ω_c) Y_c=y-(x)/(ω_c). 用 式（c-Qx–c-Qy） 可得 Q_y=mω_c X_c, Q_x=-mω_c Y_c . 所以两个守恒的诺特荷（相差常数因子）就是回旋圆心的坐标： 平移对称性锁定的是圆心，而不是粒子的瞬时动量。"},{"m":"M21","sec":"模块概览","t":"电荷 $q$、质量 $m$ 的粒子在沿 $z$ 轴的均匀磁场 $B=Bz$ 中运动，取对称规范 $A=(1)/(2)B$，拉格朗日量为： $$L = (1)/(2)m(x^2+y^2) + (qB)/(2)(xy - yx)$$ ### 规范正则动量与回旋圆心守恒 - 正则动量 $p=mv+qA$ 依赖规范选择，但空间平移对称性给出的诺特荷 $Q_x=mx-qBy$ 与 $Q_y=my+qBx$ 严格守恒。 - 两守恒荷直接锁定回旋圆心坐标 $(x_c,y_c)=(Q_y/qB, -Q_x/qB)$，粒子以回旋频率 $ω_c=qB/m$ 做匀速圆周运动。"},{"m":"M21","sec":"讨论","t":"· 两个“能量”. 圆环问题里 $E$ 守恒而 $E_ mech$ 不守恒， 差值由电机做功补上；这与“约束随时间变化时机械能不守恒”是同一件事。 · 两个“动量”. 磁场问题里机械动量与规范动量都不守恒， 但平移导致的诺特荷守恒；守恒量对应回旋圆心，而非瞬时速度。 · 分岔. $Ω$ 从下方穿过 $Ω_c$ 时，$θ=0$ 由稳定变不稳定， 一对斜平衡同时出现，是典型的超临界叉式分岔。 L. D. Landau, E. M. Lifshitz, Mechanics, 3rd ed., Pergamon, 1976. H. Goldstein, C. Poole, J. Safko, Classical Mechanics, 3rd ed., Addison-Wesley, 2002. J. D. Jackson, Classical Electrodynamics, 3rd ed., Wiley, 1999."},{"m":"M21","sec":"动量守恒与诺特荷","t":"机械动量 $p_ mech=mv$ 的方向不断改变，不守恒； 正则动量 p_x=mx-(qB)/(2)y, p_y=my+(qB)/(2)x 也不守恒，因为 $L$ 显含 $x,y$。但 $x,y$ 平移只让 $L$ 改变一个全导数， 诺特荷仍然存在： · Q_x | =mx-qBy · Q_y | =my+qBx. 直接求导可验证 $Q_x=Q_y=0$。 平移参数取 $ϵ$，若 $δ L=ϵ dF/dt$，诺特荷就是相应正则动量减去 $F$。 δ_xL=ϵ(qB)/(2)y=ϵ(d)/(dt)((qB)/(2)y), Q_x=p_x-(qB)/(2)y=mx-qBy δ_yL=-ϵ(qB)/(2)x=ϵ(d)/(dt)(-(qB)/(2)x), Q_y=p_y+(qB)/(2)x=my+qBx"},{"m":"M21","sec":"数值验证","t":"交互页对圆环方程 式（r-eom） 作四阶 Runge—Kutta 积分（步长 $2×10^-3 s$）， 对磁场问题用解析解 式（c-eom） 采样。 · 量 | 参数 | 解析值 | 数值/检查值 · Q5 $Ω_c$ | $R=1.2$ | $2.8592 rad/s$ | $2.8592$ · Q5 $θ_ eq$ | $Ω=3.0$ | $24.72^∘$ | $24.72^∘$ · Q5 $V_ eff''(0)$ | $Ω>Ω_c$ | $<0$ | 失稳 · Q5 $V_ eff''(θ_ eq)$ | $Ω=3.0$ | $2.267>0$ | 稳定 · Q5 $$ | RK4，$2 s$ | 0 | $<10^-6$ · Q6 $r_c$ | $B=1.2,v_0=1$ | $0.8333$ | $0.8333$ · Q6 $Q_x$ | 同上 | $1$ | $1$（$Δ Q_x<10^-12$） · Q6 $Q_y$ | 同上 | $0$ | $0$（$Δ Q_y<10^-12$） · Q6 $Δ p_x$ | 一个回旋周期 | $≠0$ | $1.000$ · Q6 $Q_y=mω_cX_c$ | 圆心 $(0,-0.8333)$ | $0$ | 一致"},{"m":"M21","sec":"雅可比积分 $E$","t":"由于 $∂ L/∂ t=0$，雅可比积分守恒： E=θ(∂ L)/(∂θ)-L =12mR^2θ^2-12mR^2Ω^2sin^2θ-mgRcosθ . 而惯性系中的机械能为 E_ mech=12mR^2(θ^2+Ω^2sin^2θ)-mgRcosθ =E+mR^2Ω^2sin^2θ . 二者不相等：差值 $mR^2Ω^2sin^2θ$ 是珠子随环转动的方位动能， 由电机维持 $Ω$ 时输入。$E$ 是旋转约束下的有效能量，不是惯性系机械能。"},{"m":"M22","sec":"模块概览","t":"单摆的哈密顿量在相空间 $(q,p)$ 中写作： $$H(q,p) = (p^2)/(2I) + K(1 - cos q), q = (∂ H)/(∂ p), p = -(∂ H)/(∂ q)$$ ### 相图拓扑与刘维尔定理 - 能量 $E<2K$ 对应闭合的往复摆动轨线；$E>2K$ 对应开口的连续转动；$E=2K$ 为连接不稳定倒立点的分界线（separatrix）。 - 哈密顿向量场的散度恒为零（$()/(∂ q)+()/(∂ p)=0$），任意初始相点团在演化中虽被剪切拉伸，但相面积严格保持不变（刘维尔定理）。"},{"m":"M22","sec":"刘维尔定理","t":"哈密顿流的相空间速度散度为零，因此任意相区域在演化中保持面积：dA/dt=0。取初始相点周围的一小团点，随时间它会被拉伸、折叠，但包围面积保持不变；加入阻尼后这一结论不再成立。 对随哈密顿流运动的区域 $A(t)$，用混合偏导相等和面积输运公式即可证明。 q=(∂ H)/(∂ p), p=-(∂ H)/(∂ q) ()/(∂ q)+()/(∂ p)=(∂^2H)/(∂ q∂ p)-(∂^2H)/(∂ p∂ q)=0 (dA)/(dt)=∫_A(t)(()/(∂ q)+()/(∂ p)) dq dp=0"},{"m":"M22","sec":"书稿精读","t":"【定理】辛条件。正则变换须满足JΩJᵀ=Ω，逐对基本括号保持强于保体积。（书稿 ch06.tex:414）"},{"m":"M22","sec":"书稿精读","t":"【定理】刘维尔定理。哈密顿流散度为零，相空间体积沿演化保持不变。（书稿 ch06.tex:274）"},{"m":"M22","sec":"书稿精读","t":"【方法】哈密顿–雅可比方程。S_t+H(q,S_q,t)=0，完全积分含s个参数并可反解轨道。（书稿 ch06.tex:521）"},{"m":"M22","sec":"书稿精读","t":"【方法】作用角变量。J=∮p dq/2π，θ=W_J，得θ̇=2π/T、J̇=0。（书稿 ch06.tex:620）"},{"m":"M23","sec":"模块概览","t":"以标准谐振子 $H(q,p)=(1)/(2)(q^2+p^2)$ 检验三类数值积分器在离散时间步长 $h$ 下的几何保结构性质： $$det(∂(q_n+1,p_n+1)∂(q_n,p_n)) = 1 （辛性条件）$$ ### 长期稳定性对比 - **显式 Euler**：单步映射行列式为 $1+h^2>1$，相面积与能量随时间指数膨胀。 - **辛 Euler 与 Störmer–Verlet**：严格保持离散相面积（$det M=1$），能量不发生长期单调漂移而是在真值附近有界振荡；Verlet 更具时间可逆性与二阶精度 $O(h^2)$。"},{"m":"M23","sec":"辛性与稳定","t":"辛方法的单步映射满足 MᵀΩM=Ω，det M=1。辛性保证相面积和长期结构，但不保证任意步长稳定；例如辛 Euler 的稳定条件为 |h|<2。Verlet 还时间可逆，通常具有二阶精度。 对本页谐振子，采用先更新动量的辛 Euler，考察其单步矩阵特征值。 p_n+1=p_n-hq_n, q_n+1=q_n+hp_n+1 q_n+1 p_n+1=Mq_n p_n, M=1-h^2 h -h 1 det M=1, trM=2-h^2, λ^2-(2-h^2)λ+1=0 |trM|<2 0<|h|<2 λ_±=e^± iϕ M(0)=1, M(±2)≠-1, [M(±2)+1]^2=0"},{"m":"M23","sec":"书稿精读","t":"【方法】辛欧拉法与Verlet。分裂流复合保持辛结构；Verlet二阶、时间对称但有相位误差。（书稿 ch06.tex:795）"},{"m":"M24","sec":"模块概览","t":"狭义相对论将时间与空间统一为闵可夫斯基时空，任意两事件的不变时空间隔定义为： $$s^2 = c^2Δ t^2 - Δ x^2$$ ### 光锥、同时性与固有时 - $s^2>0$ 为类时间隔（存在因果联系，光锥内部），$s^2=0$ 为类光间隔（光锥面），$s^2<0$ 为类空间隔（无因果联系，先后次序依赖参考系）。 - 运动参考系的 $ct'$ 轴斜率为 $1/β$、$x'$ 轴（同时线）斜率为 $β$；沿世界线积分固有时 $τ=∫√(1-u^2/c^2) dt$，双生子佯谬中惯性直世界线的固有时极大。"},{"m":"M24","sec":"时空间隔与光锥","t":"在闵可夫斯基图中，事件用 (x, ct) 表示（本页取 c = 1，ct 与 x 同单位）。两事件的时空间隔定义为 $s^2 = c^2 t^2 - x^2$，它是洛伦兹变换下的不变量：所有惯性系测得的 s² 相同。s² > 0 为类时间隔，两事件可有因果联系；s² = 0 为类光间隔，事件恰在光锥面 x = ±ct 上；s² < 0 为类空间隔，两事件无法因果关联。光锥把时空分成未来锥、过去锥与锥外区域。 将洛伦兹变换代入间隔，并保留本页 $c=1$ 的约定。 t'=γ(t-β x), x'=γ(x-β t) t'^2-x'^2=γ^2l[(t-β x)^2-(x-β t)^2r] t'^2-x'^2=γ^2(1-β^2)(t^2-x^2)=t^2-x^2=s^2"},{"m":"M24","sec":"固有时与双生子佯谬","t":"沿世界线的固有时由 $τ = ∫ √(1 - u^2/c^2) dt$ 给出，是路径的积分而非坐标差。对类时间隔，惯性观测者走直世界线，其钟读出原时 $τ = √(s^2)$。双生子佯谬中，留守者走 O→P 的直线，旅行者经折点折返走折线世界线；直线固有时最长、折线更短。几何本质：闵氏时空中直世界线是固有时极大而非极小，这与时空的赝欧几里得签名 (−,+,+) 有关。 在两端事件同地的惯性系中比较所有连接它们的未来类时路径，仍取 $c=1$。 Δ x=0, Δ t=√(s^2) τ=∫_t_1^t_2√(1-u(t)^2) dt≤∫_t_1^t_2dt=Δ t τ=Δ t u(t)=0 几乎处处"},{"m":"M24","sec":"同时性与倾斜坐标轴","t":"运动系 S′ 的 x′ 轴就是 t′ = 0 的同时线，在图中是斜率为 β 的直线；ct′ 轴（x′ = 0 的世界线）斜率为 1/β，两者关于 45° 光速线对称地向其收拢。时间变换为 $Δ t' = γ(Δ t - β Δ x)$，其中 $γ = 1/√(1-β^2)$。对类空间隔可取 β_sim = Δt/Δx（|β_sim| < 1）使 Δt′ = 0，即两事件在该系中同时；β 越过 β_sim 时先后次序翻转——同时性是相对的。"},{"m":"M24","sec":"相对论速度合成","t":"若物体在 S′ 系内速度为 u′，S′ 相对 S 系速度为 v，由洛伦兹变换导出相对论速度合成 $u = (u' + v)/(1 + u'v/c^2)$。分母保证合成速度永不超光速：当 |u′| ≤ 1 且 |v| < 1（c = 1）时恒有 |u| < 1；若 u′ = 1（光），则对任意 v 都有 u = 1，光速不变。经典伽利略合成 u′ + v 在高速下会越过 ±1，与光速极限矛盾——这正是相对论修正的关键项。"},{"m":"M24","sec":"书稿精读","t":"【方法】速度合成与光行差。u′=(u−v)/(1−vu/c²)，横向分量也变，光方向随系偏转。（书稿 ch07.tex:334）"},{"m":"M24","sec":"书稿精读","t":"【概念】不变间隔与因果分类。Δs²=c²Δt²−Δr²不变；类时、类光、类空决定因果联系。（书稿 ch07.tex:206）"},{"m":"M25","sec":"模块概览","t":"光波相位 $φ=ω t-k$ 为洛伦兹标量，波四矢量 $k^μ=(ω/c,k)$ 按洛伦兹变换给出相对论多普勒频移与光行差公式： $$ω' = γω(1 - βcosα), cosα' = (cosα - β)/(1 - βcosα)$$ ### 视觉与天体效应 - 当 $α=π/2$ 时仍存在纯时间膨胀引起的横向多普勒红移 $ω'=ω/γ$。 - 当 $β→ 1$ 时，光行差将四面八方的星光强烈汇聚到运动前方并显著增亮蓝移（车头灯效应 / 相对论集束），解释了活动星系核喷流的单侧可见性。"},{"m":"M25","sec":"光行差与车头灯效应","t":"光行差公式 $$cosα'=(cosα-β)/(1-βcosα)$$ 把天球向前进方向挤压：cosα=0 的星（α=90）变到 cosα′=−β；cosα=β 的星变到 α′=90，故视场内 α′<90 的锥（半角 arccosβ）里装下了原天球中 α<90 的全部……β=0.99 时 arccosβ=8.1°：一半的星星挤进 8° 的帽子里。立体角变换由方向变换求雅可比： $$(dΩ')/(dΩ)=(1)/(γ^2(1-βcosα)^2)=(1)/(D^2)$$ 前方小立体角汇聚（dΩ′/dΩ<1 处星数密度增大），后方稀疏。光子数守恒与每光子能量 ω′/ω=D、到达率同样乘 D、加上面积汇聚，给出比强度变换 I′=D³I（谱强度 I_ν/ν³ 为相对论不变量，积分后 D³ D⁴）。前方因此「车头灯」式增亮：本页画布按 D²·⁵ 增亮并做色相/波长映射（移出可见区钳制为深红或紫白），深度剔除只保留视场内（cosα′<0）的星。"},{"m":"M25","sec":"波四矢量与多普勒公式的推导","t":"多普勒公式是波四矢量的洛伦兹变换，一行可推出。平面波相位 φ=ωt−**k**·**x** 是标量（波峰计数与参考系无关），故 k^μ=(ω, **k**)（c=1）构成四矢量。对沿 x 方向速度 β 的观察者做洛伦兹 boost： $$ω'=γ(ω-β k_x)=γω(1-βcosα)$$ 其中 cosα=k_x/|**k**| 即光线方向与速度的夹角——这就是手稿 ch07 的约定：α 按「光线方向」量，迎面来光（传播方向与速度反向）α=180，得 ω′=γ(1+β)ω，蓝移。用不变量写成标量积 k^μu_μ：观察者四速 u^μ=γ(1,**v**)，测得 ω′=k·u，两系之比即 D=ω′/ω=γ(1−βcosα)。同一 boost 也给波矢方向变换：k_x′=γ(k_x−βω)，除以 ω′ 得 cosα′=(cosα−β)/(1−βcosα)，与光行差公式同形。"},{"m":"M25","sec":"天文学应用：喷流束流与单侧性","t":"相对论喷流（射电星系、blazar、GRB）把车头灯效应搬到天空：源以速度 β 运动、与视线夹角 θ_obs 时，束流因子通常写成 $$δ=1γ(1-βcosθ_obs)$$ 与本页 D=γ(1−βcosα) 是同一多普勒因子的对偶约定（运动观测者 ↔ 运动辐射源，α=π−θ_obs 时相等）。观测流量密度 S′∝δ³（谱流量 S_ν′∝δ^2+α_s）：接近侧被放大数十倍，退行侧 δ<1 几乎熄灭——双模射电星系「只见一瓣」的单侧性由此解释。视超光速运动同理：横向视速度 β_app=βsinθ/(1−βcosθ)，θ≈1/γ 时可超过 1。本页交互可复现：播放加速到 β=0.99，前方 D_front=√((1+β)/(1−β))≈14.1，一颗 K 型橙星蓝移到紫白，而后方退行星的波长被拉到可见区之外沉入深红。 取 $c=1$，比较喷流间隔 $Δ t$ 发出的两次闪光，其第二次闪光的传播路程缩短了 $βΔ tcosθ$。 Δ t_ obs=Δ t-βΔ tcosθ, Δ x_⊥=βΔ tsinθ β_ app=Δ x_⊥Δ t_ obs=(βsinθ)/(1-βcosθ) dβ_ appdθ=(β(cosθ-β))/((1-βcosθ)^2)=0 cosθ=β β_ app,max=βγ, θ=arccosβ≃γ^-1 (γ1)"},{"m":"M25","sec":"退行、趋近与横向多普勒","t":"沿视线方向（α=0，退行）： $$(ω')/(ω)=γ(1-β)=√((1-β)/(1+β))$$ β=0.6 时为 0.5，一半频率；迎面 α=180 时 √((1+β)/(1−β))=2.0。两者互为倒数：$$√((1-β)/(1+β))·√((1+β)/(1-β))=1$$ 横向情形要小心区分两个 90°。按「光线方向角」约定 α=90：ω′=γω，这是 cosα=0 的直接代入；但这颗星在你天空里的视位置 α′ 满足 cosα′=−β，即已越过侧向、位于后方 126.9°（β=0.6）。反过来，正侧方看到的星（α′=90）满足 cosα=β，收到 $$ω'=γω(1-β^2)=(ω)/(γ)$$ 这才是纯时间膨胀的横向多普勒效应，一阶效应之外唯一存留的相对论项，β=0.99 时为 0.0141 倍。"},{"m":"M25","sec":"书稿精读","t":"【方法】多普勒效应的相位推导。ω′=γω(1−βcosθ)，横向条件须注明在哪个参考系。（书稿 ch07.tex:374）"},{"m":"M26","sec":"模块概览","t":"取 $c=1$，粒子的能量与三维动量组成四动量 $P^μ=(E,p)$，满足质量壳关系 $E^2-p^2=m^2$。孤立碰撞中总四动量守恒，系统的不变质量为： $$M_inv = (∑ E_i)^2 - (∑ p_i)^2$$ ### 碰撞与质能转化 - 完全非弹性碰撞中，动能转化为内能，生成复合粒子的静质量严格等于系统不变质量 $M_inv > ∑ m_i$，其速度为 $V=P_tot/E_tot$。 - 不变质量在所有惯性系中取值相同，是连接实验室系与质心系碰撞分析的核心工具。"},{"m":"M26","sec":"固定靶阈值","t":"质量为 m_a 的入射粒子轰击静止靶 m_b，末态总静质量为 M_f 时，阈能 E_a,th=(M_f²−m_a²−m_b²)/(2m_b)，阈动能为 K_th=E_a,th−m_a。固定靶必须为末态整体运动保留额外能量，所以通常比对撞更耗能。 在 $c=1$ 下，对需要吸收入射动能的自由末态通道，阈值处各末态粒子在质心系相对静止。 s=(E_a+m_b)^2-p_a^2 s=(E_a^2-p_a^2)+m_b^2+2m_bE_a=m_a^2+m_b^2+2m_bE_a s_ th=(∑_i m_i)^2=M_f^2 E_a, th=(M_f^2-m_a^2-m_b^2)/(2m_b), K_ th=E_a, th-m_a"},{"m":"M26","sec":"书稿精读","t":"【定理】四动量与质量壳。P=(E/c,p)，E²=p²c²+m²c⁴，m为不变质量。（书稿 ch07.tex:415）"},{"m":"M26","sec":"书稿精读","t":"【极限】固定靶阈能与对撞机。E_th=(M_f²−m_a²−m_b²)c²/2m_b，对撞更省能量。（书稿 ch07.tex:822）"},{"m":"M26","sec":"书稿精读","t":"【概念】系统不变质量。M²c⁴=E_tot²−c²P_tot²，包含内部能，不等于静质量之和。（书稿 ch07.tex:459）"},{"m":"M26","sec":"书稿精读","t":"【方法】两体衰变通用解。母粒子静止时E_1*=(M²+m_1²−m_2²)c²/2M。（书稿 ch07.tex:645）"},{"m":"M27","sec":"模块概览","t":"单自由度阻尼振子在简谐外力驱动下的运动方程为： $$q + 2 + ω_0^2 q = F_0cos(ω t)$$ ### 共振、带宽与品质因数 - 稳态振幅 $A(ω)=F_0√((ω_0^2-ω^2)^2+4γ^2ω^2)$ 在 $ω_A=√(ω_0^2-2γ^2)$ 处取极大；而平均吸收功率 $P(ω)$ 精确在 $ω=ω_0$ 处共振，其半功率全宽恒为 $Δω=2γ$。 - 品质因数 $Q=ω_0/(2γ)$ 同时刻画共振峰尖锐度与单周期能量耗散比；双近频叠加则产生周期拍频现象。"},{"m":"M27","sec":"双振子、耦合摆与拍","t":"把两只相同的摆弱耦合，系统有两个简正模 ω_−<ω_+；只释放一只摆等价于两个简正模等幅叠加：q_1=cosω_−t+cosω_+t 乘积化和差得 $$q_1=2cos((ω_+-ω_-)/(2)t)cos((ω_++ω_-)/(2)t),$$ 快载波被慢包络 2cos(Δωt/2) 调制，包络每 T_b=2π/|Δω| 复原一次——这就是耦合摆「能量在两只摆之间来回传」的图像。手稿强调：包络消失（两摆位移同时为零）不代表两模能量消失，有符号包络的正负两支才是完整包络。场景3 用两个独立 RK4 积分器分别跑 ω₁、ω₂ 的简谐振动再相加，包络、分量、和曲线同屏；ω₁、ω₂ 滑块靠得越近，拍越长，与公式一致。"},{"m":"M27","sec":"能量观点：Q、ΔE/E 与耗散","t":"品质因数定义为 Q=ω₀/(2γ)。欠阻尼下取 T_d=2π/ω_d，一周期内 q 与 q̇ 都乘 e^(−γT_d)，能量乘 e^(−2γT_d)，故相对损失 $$(Δ E)/(E(t))=1-e^-2γ T_d≃ 2γ T_d≃(4πγ)/(ω_0)=(2π)/(Q).$$ 高 Q 即每周期只漏掉 2π/Q 的能量，共振峰半高宽 Δω=2γ=ω₀/Q 随之收窄。场景2 的 HUD 实时显示 Q 与 Δω：γ=0.02 时 Q=25、Δω=0.04，峰几乎成 δ 函数；γ 增大后峰矮而胖，ω_R 也左移，演示「矮胖矮到某处就没有峰」。这些量都不需要非线性：线性黏性模型已给出全部结构。"},{"m":"M27","sec":"书稿精读","t":"【定理】位移峰、功率峰与半功率带宽。位移峰在√(ω0²-2γ²)，功率峰在ω0，半功率带宽精确为2γ。（书稿 ch04.tex:214）"},{"m":"M27","sec":"平均功率与半功率带宽：2γ 是精确结果","t":"稳态下 E 一周期复原，̄Đ=0，输入平均功率等于耗散 c q̇² 的平均：$$P=(γ F_0^2ω^2/m)/((ω_0^2-ω^2)^2+4γ^2ω^2)=(γ F_0^2/m)/((ω_0^2/ω-ω)^2+4γ^2).$$ 第二个写法（分子分母同除 ω²）让 ω=ω₀ 处平方项归零，故 P̄_max=F₀²/(4mγ) 恒在 ω₀。半功率点满足 |ω₀²−ω²|=2γω，左右分别解 ω²±2γω−ω₀²=0 的正根得 $$ω_±=√(ω_0^2+γ^2)±γ (左 ω_-, 右 ω_+), ω_+-ω_-=2γ.$$ 注意这是线性黏性模型中的精确宽度，不是弱阻尼近似；两半功率点的算术中点 √(ω₀²+γ²) 只在弱阻尼时近似等于 ω₀。只有速度与驱动力同相的分量在整周期内贡献净输入功。"},{"m":"M27","sec":"数值方法与参数约定（RK4、URL、自测）","t":"三个场景共用同一四阶 Runge-Kutta：状态 (q, q̇) 以固定步长 h=0.002 推进，帧间 dt·speed 用累加器补齐，保证数值解与帧率无关。稳态测量在自测里用「先热身 t>10/γ 再对 8 个周期做均方与 cos/sin 投影」的办法反推 A 与 δ，再与解析值比对，避免瞬态污染。13 项断言覆盖：三个驱动频率的稳态幅值（relerr<10⁻³）与相位（<0.1°）、功率峰 ≈ω₀ 与幅值峰 ≈√(ω₀²−2γ²)、半功率宽度 ≈2γ、自由衰减率 ≈γ（对数斜率拟合）、拍周期 ≈2π/|Δω| 与包络幅值 2F₀。全部参数经 URL 持久化（scene/omega/omega0/gamma/f0/omega1/omega2/speed），刷新页面即可复现任意画面；默认 m=1 的无量纲制，若换手稿算例 m=1 kg、k=100 N/m、c=4 N·s/m（ω₀=10, γ=2），把全部频率除以 10 即可对照。"},{"m":"M27","sec":"受迫稳态：复数解、幅值与相位滞后","t":"外力 F₀cosωt（F₀>0, ω>0, γ>0）下，稳态取 Re[Xe^iωt]，代入 (q→Xe^iωt) 得 (ω₀²−ω²+2iγω)X=F₀/m，于是 $$A=F_0/m√((ω_0^2-ω^2)^2+4γ^2ω^2), tanδ=(2γω)/(ω_0^2-ω^2).$$ 关键是用 atan2 而非 arctan 定相位：分母 Δ=ω₀²−ω² 在 ω>ω₀ 时变负，只给 tanδ 会把高频分支错回第一象限。物理上 δ 从 ω≪ω₀ 时的 ≈0（位移与力同相，弹簧主导）连续爬到 ω=ω₀ 处的 π/2（速度与力同相），再在 ω≫ω₀ 时趋于 π（位移反相，惯性主导）。本模块场景1 把 A cos(ωt−δ) 作为虚线参考，数值解的偏离量直接显示瞬态残迹。"},{"m":"M28","sec":"模块概览","t":"支点固定在下方、质心高 $l$ 的重对称陀螺（主惯量 $I_1=I_2,I_3$）具有两个循环欧拉角 $φ,ψ$，对应守恒广义动量 $p_φ,p_ψ$，将三维转动约化为倾角 $θ$ 的一维有效势问题： $$V_eff(θ) = Mglcosθ + ((p_φ - p_ψcosθ)^2)/(2I_1sin^2θ)$$ ### 进动、章动与睡眠陀螺 - 有效势极小点给出稳恒进动（分为慢支与快支）；能量略高于极小值时，对称轴在两倾角转折点间上下章动，轴尖在球面上绘出玫瑰线。 - 竖直直立转动（睡眠陀螺）的稳定条件为 $ω_3 > ω_3c = √(4I_1 Mgl)I_3$。"},{"m":"M28","sec":"稳恒进动慢支快支","t":"稳恒进动（θ 恒定）等价于 $V_ eff'(θ_0)=0$，即进动二次方程 $I_1Ω^2cosθ_0-I_3ω_3Ω+Mgl=0$。判别式 $h^2≥4I_1Mglcosθ_0$（h=I₃ω₃）时有两根：慢支取小根，高速自转下 $Ω≈ Mgl/(I_3ω_3)$，对应 V_eff 极小、动力学稳定；快支 $Ω≈ I_3ω_3/(I_1cosθ_0)$ 对应极大、不稳定。模块用数值稳定形式 $2Mgl/(h+√(h^2-4I_1Mglcosθ_0))$ 计算小根以避免相消误差，自测检验两根回代残差。"},{"m":"M28","sec":"睡眠陀螺稳定性","t":"陀螺完全竖直时欧拉角奇异（sinθ=0），须单独线性化：以轴的小偏移 (u,v) 写方程 $I_1u+hv-Mgl u=0, I_1v-hu-Mgl v=0$，模式指数 $σ_±=i (h±√(h^2-4I_1Mgl))/(2I_1)$。$ω_3^2>4I_1Mgl/I_3^2$ 时两根纯虚、睡眠稳定；违反判据时出现正实部，倾角按 $√(4I_1Mgl-h^2)/(2I_1)$ 指数增长；临界处重根、扰动 ∝ t。默认参数 ω₃c=√2/0.6≈2.357。"},{"m":"M28","sec":"守恒量与有效势","t":"φ、ψ 为循环坐标，存在两个守恒动量：$p_ψ=I_3(ψ+φcosθ)=I_3ω_3=L_3$（轴向）与 $p_φ=I_1φsin^2θ+p_ψcosθ=L_z$（竖直）。Routh 约化把三维姿态问题化为 $I_1θ=-V_ eff'(θ)$，其中 $V_ eff=((p_φ-p_ψcosθ)^2)/(2I_1sin^2θ)+Mglcosθ$，能量约束为 $12 I_1θ^2+V_ eff=E-(p_ψ^2)/(2I_3)$。转折点 $V_ eff=E'$ 界定允许区，θ 只能在带内往复。"},{"m":"M28","sec":"章动频率","t":"偏离稳恒点释放时，θ 在极小 θ* 附近小幅振荡，章动频率 $ω_n=V_ eff''(θ_*)/I_1=√((h/I_1-2Ωcosθ_0)^2+Ω^2sin^2θ_0)$。球面玫瑰线即快小幅（章动）叠慢大幅（进动）的轨迹；由静止释放（φ̇₀=0）时轴尖先向下摆过目标纬线再抬升，形成经典摆线状章动——这是支点约束下“下落—抬升”的能量再分配。自测以 θ 速度换号测周期并与闭式比较。"},{"m":"M28","sec":"与自由刚体的关系","t":"力矩自由极限 Mgl→0 时 V_eff 退化为纯离心项，稳恒运动变为轴绕固定角动量 L 的锥面进动：$φ=L_z/I_1$、$L_z=L_3/cosα$（α 为轴与 L 的夹角）——与自由刚体的 Poinsot 运动（模块 17）一致，θ 扰动则表现为对锥面的章动振荡。自测 ST6 由 φ 累计测进动速率并与 L_z/I₁ 对照；ST2 检验 V_eff′(θ*)=0 恒等；ST4 验证沿轨迹 E、L_z 相对漂移小于 1e-8，确认约化与重构自洽。"},{"m":"M28","sec":"书稿精读","t":"【方法】拉格朗日陀螺有效势。用两个循环动量把重陀螺约化为θ方向的一维有效势。（书稿 ch05.tex:1466）"},{"m":"M29","sec":"模块概览","t":"勒让德变换将速度变量 $q$ 对偶置换为正则动量 $p=∂ L/$，得到哈密顿量与正则方程： $$H(q,p,t) = ∑_i p_iq_i - L(q,q,t), q_i = (∂ H)/(∂ p_i), p_i = -(∂ H)/(∂ q_i)$$ ### 切线几何与罗斯约化 - 几何上，$H(p)$ 是凸函数 $L(q)$ 的切线截距对偶，做两次变换精确回到原函数。 - 若仅对循环坐标做部分勒让德变换，构造罗斯函数 $R=L-∑ p__α$，即可将守恒动量作为参数折入有效势，实现系统降维。"},{"m":"M29","sec":"勒让德变换：从速度变量换到动量变量","t":"正则动量定义为 p = ∂L/∂q̇（手稿记号 L_q̇）。对谐振子 L=½mq̇²−½kq² 得 p=mq̇；对单摆 L=½ml²θ̇²+mgl·cosθ 得 p_θ=ml²θ̇——动量是速度的线性函数，其斜率即惯性系数（m 或 ml²）。勒让德变换定义 H = p q̇ − L，右侧必须先用 p=∂L/∂q̇ 把 q̇ 消去：H 是 (q,p) 的函数，速度不再是独立变量。凸性条件 ∂²L/∂q̇²>0 保证 p↔q̇ 全局可逆，变换对合（自逆），自检用嵌套三分搜索数值验证了 L→H→L 复原。微分恒等式 dH = q̇ dp − (∂L/∂q) dq 是全部结构关系的来源。"},{"m":"M29","sec":"罗斯约化：固定动量的勒让德翻转","t":"对循环坐标 y（速度 ẏ、守恒动量 μ=∂L/∂ẏ），罗斯函数取部分勒让德变换：拉格朗日型 R(x,ẋ,μ) = L − Σμαẏα，其余非循环坐标仍保留速度变量。关键点：只有循环坐标才能把 ẏ 消去、把 μ 当常数参数固定住；对非循环坐标做同样操作会丢失信息。变分原理 δ∫R dt = 0 对 x 给 EL 方程，对 μ 给约束 ∂R/∂μ = −ẏ。符号约定务必核对：本模块与手稿取 R = L − μẏ；另一些文献取相反号的 Routhian（记 R_H = −R），照抄公式时离心项会错号——这是手稿专门标出的坑。"},{"m":"M29","sec":"正则方程：从恒等式到最后取路径","t":"由 dH = q̇ dp − (∂L/∂q)dq 与 dL = (∂L/∂q)dq + (∂L/∂q̇)dq̇ 对比可得两条偏导恒等式：∂H/∂p = q̇、∂H/∂q = −∂L/∂q。此时还未用运动方程；最后一步代入 EL 方程 d/dt(∂L/∂q̇)=∂L/∂q，把 ∂L/∂q 换成 ṗ，才得到哈密顿正则方程 q̇ = ∂H/∂p、ṗ = −∂H/∂q。模块场景2 强调这个「最后才取路径」的顺序：先构造 (q,p) 相空间上的 H，再令系统沿 H 的哈密顿流走。正则方程是一阶对称体系，相体积守恒（刘维尔定理的起点），对谐振子给出相空间椭圆轨道，对单摆给出含分界线的摆线族。"},{"m":"M29","sec":"书稿精读","t":"【定理】勒让德变换与正则方程。在速度海森矩阵可逆处消去速度，得q̇=H_p、ṗ=−H_q。（书稿 ch06.tex:35）"},{"m":"M29","sec":"数值方法与参数约定（RK4、URL、自测）","t":"积分一律四阶 Runge-Kutta：正则/EL 双列各以 h≈T/1600（T 为估计周期，单摆用 AGM 估计）独立推进 10 个周期，两解偏差与两个能量漂移全程显示（偏差 0、漂移 1e-12 即验证等价与守恒）；中心力场全 2D 与约化 1D 各以 h=0.0012 双轨积分，径向周期由 V_eff 转折点间的数值求积估计。URL 参数：scene、sys、pot、q、qd、q0、qd0、turns、lz、r0、rd0、speed。?selftest=1 输出 14 条断言：中心差分 vs 解析动量（1e-13）、勒让德恒等式（0）、对合复原（1e-15）、正则=EL 两解重合（0）、单摆 H 漂移（3e-12）、约化 vs 全 2D 径向偏差（7e-11）、末态能量一致（1e-11）、力律残差（5e-11）、Lz 守恒（5e-12）。"},{"m":"M29","sec":"中心力场约化与有效势的离心项符号","t":"对平面中心力场做罗斯约化：θ 循环、μ=Lz=mr²θ̇，反解 θ̇=Lz/(mr²) 代回，得 R = ½mṙ² − [V(r) + Lz²/(2mr²)]。括号内第二项即有效势 V_eff 的离心项。约化径向方程 m r̈ = −dV_eff/dr = −V′(r) + Lz²/(mr³)：离心项取正号、等效为排斥，来自「固定动量的变分问题」这一正确构造；若偷懒直接把 θ̇=Lz/(mr²) 代入能量而忘记勒让德翻转，同一项会以错误符号出现。场景3 用全 2D 极坐标积分与约化 1D 积分双轨对照：金线（全轨道的 r(t)）与青虚线（约化 r(t)）重合，转折点 r±、径向周期 T_r 与 V_eff 极小同时给出，自检 ST5/ST6 以 1e-11 残差核验力律与 Lz 守恒。"},{"m":"M30","sec":"快度与速度合成","t":"定义快度 $η=artanhv$，则 $v=tanhη$、$γ=coshη$、$γ v=sinhη$，洛伦兹推进是双曲旋转。恒固有加速度时 $dη/dτ=a$，故 $η=aτ$ 严格随固有时线性——场景2 内嵌图即此直线；而 $η(t)=arsinh(at)$ 随坐标时只对数增长。手稿 modernbox 强调：同向连续推进快度相加，$v=tanh(η_1+η_2)=(v_1+v_2)/(1+v_1v_2)$，速度合成公式就是双曲加法公式。故反复加速永不超光速：加的是无界的 $η$，测到的是有界的 $tanhη$。自测 ST4 对三组 $(η_1,η_2)$ 验证该式到 $10^-9$。"},{"m":"M30","sec":"模块概览","t":"在自身瞬时静止系中始终保持恒定固有加速度 $a$ 的粒子，在惯性系中的世界线是一条渐近于光锥的双曲线： $$x^2 - (ct)^2 = ((c^2)/(a))^2, x(τ)=(c^2)/(a)cosh(aτ)/(c), ct(τ)=(c^2)/(a)sinh(aτ)/(c)$$ ### 快度与 Rindler 视界 - 快度 $η=aτ/c$ 随固有时线性增长，坐标速度 $v=ctanh(aτ/c)$ 渐近趋于光速而不越界。 - 渐近光锥 $x=ct$ 构成加速观察者的事件视界（Rindler 视界），其后方发出的光信号永远无法追上该粒子；在 $aτ c$ 时退化为牛顿匀加速抛物线。"},{"m":"M30","sec":"牛顿极限","t":"手稿强调恒力运动的低速极限：$Ft mc$（即 $at1$）时 $u=Ft/m$、$x=Ft^2/(2m)$ 复原伽利略结果；本页起点 $x_0=1/a$，对应 $x≈1/a+12 at^2$、$v≈ at$。场景2 把牛顿线 $v=at$ 与相对论曲线画在同屏：它在 $t=1/a$ 处越出光速上界（图上红色叉号标记失效点），此后完全错误；而 $p=Ft$ 线性增长依然成立，错的只是把 $p$ 换成 $mv$。坐标加速度 $dv/dt=a(1-v^2)^3/2=a/γ^3$ 随 $γ$ 三次方衰减——恒固有加速度绝不意味着恒坐标加速度，这正是「加速度的相对论」最容易被公式 $F=ma$ 误导的地方。自测 ST6 对两组 $at≤0.1$ 的算例比对牛顿近似，相对误差均小于 1%。"},{"m":"M30","sec":"固有时与双生子","t":"理想钟读数是沿世界线的积分 $τ=∫_t_A^t_B√(1-v^2(t)) dt$（手稿式，$c=1$）。对恒固有加速度运动 $v=t/√(t^2+1/a^2)$，积分闭式 $τ(t)=arsinh(at)/a$；反解即 $t=sinh(aτ)/a$：钟只线性走，坐标时却双曲增长。场景3 同时画加速者 $τ(t)$ 与惯性留守者 $τ=t$：固定两端事件之间直线世界线固有时最大（手稿数学注记），所以加速的那位必定更年轻。$t1/a$ 时 $τ≈ln(2at)/a$：留守者过了 $t_ end$，飞船钟只老 $∼ln t_ end/a$。自测 ST3 在三个时刻比对积分与闭式到 $10^-6$。"},{"m":"M30","sec":"双曲世界线","t":"一维恒定固有加速度 $α$（手稿记 $α=√(-A· A)$，恒力例 $α=F/m$）从静止出发，积分得 $χ=ατ/c$、$t=(c/α)sinh(ατ/c)$、$x=(c^2/α)(cosh(ατ/c)-1)$；本页取 $c=1$ 且起点取 $x_0=1/a$，于是 $(t,x)=(sinh aτ/a, cosh aτ/a)$ 精确落在双曲线 $x^2-t^2=1/a^2$ 上，世界线始终类时、在光锥内。数值上用 RK4 联立积分 $dv/dt=a(1-v^2)^3/2$、$dx/dt=v$，页面同屏画解析双曲线（虚线）与数值轨迹（实线）供对照；自测 ST1 直接检查 $|x^2-t^2-1/a^2|<10^-8$。"},{"m":"M30","sec":"数值方法与参数约定（RK4、URL、自测）","t":"三个场景共用同一四阶 Runge-Kutta：状态 $(v,x,τ)$ 以固定步长 $h=0.001$ 对自变量 $t$ 联立推进（$dv/dt=a(1-v^2)^3/2$、$dx/dt=v$、$dτ/dt=√(1-v^2)$），帧间时间用累加器补齐，保证画面与帧率无关。$v$ 一旦达到 $1-10^-12$ 即截断并在 HUD 提示「已触发」：不加防护时 $1-v^2$ 可能因舍入变负导致开方 NaN。19 项断言覆盖：双曲不变量残差 $<10^-8$、$v<1$ 全程、$v$ 与 $τ$ 对闭式到 $10^-6$、快度加法到 $10^-9$、光子间距三重检验、牛顿极限 1%。全部参数经 URL 持久化（scene/a/vi/photon/tend/speed），非法值自动回退默认。"},{"m":"M30","sec":"光追逐与Rindler视界","t":"$t=0$ 从原点发出的光子走 $x=t$，加速者与它的间距 $Δ(t)=√(t^2+1/a^2)-t=e^-aτ/a$：随观察者固有时指数衰减、趋于 0 但严格大于 0——光子永远追不上双曲线。原因一目了然：$x=t$ 正是双曲线 $x^2-t^2=1/a^2$ 的渐近线，即观察者未来事件视界（Rindler 视界）的生成线。凡位于区域 $x<t$（含整个 $ct$ 轴方向）的事件，其未来光锥都碰不到这条世界线：那里发出的任何信号都无法影响加速观察者，页面用淡青色阴影标出该区域。反过来，观察者能看到视界以内的全部历史。自测 ST5 检查 $t=100$ 时间距仍为正、数值间距与 $√(t^2+1/a^2)-t$ 及 $e^-aτ/a$ 一致到 $10^-6$。"},{"m":"S7","sec":"三维力与功率","t":"在指定惯性系中定义三维力为动量对坐标时的变化率。对恒定不变质量的粒子，把力沿瞬时速度方向与垂直方向分解：F∥ = mγ³a∥，F⊥ = mγa⊥。因此一般不能写 F = ma，也不能靠统一引入“相对论质量”同时解决两个方向的关系。对质量壳关系求导并利用 u = c²p/E，得功率定理：dE/dt = F·u。四力定义为 f = dP/dτ = γ(F·u/c, F)，满足 f·U = 0，这一正交性用了质量恒定的假设。例题：一维恒力 F 作用于初始静止的粒子，p = Ft，速度 u(t) = (Ft/m)/√(1 + (Ft/mc)²)，位置 x(t) = (mc²/F)(√(1 + (Ft/mc)²) − 1)。短时恢复 x ≈ Ft²/(2m)；任意有限时刻 u < c，长期作用使动量与能量持续增大而速度渐近趋于 c。 对 $p=m$ 求导，再沿瞬时速度作投影。 γ=(γ^3)/(c^2)u F=m+(mγ^3)/(c^2)(u)u F_⊥=mγ a_⊥, F_∥=mγ(1+γ^2(u^2)/(c^2))a_∥=mγ^3a_∥"},{"m":"S7","sec":"系统的不变质量","t":"不与外界交换能量和动量的系统，碰撞前后四动量相等，入射方总和等于出射方总和。由总能量 E总与总动量 P总定义系统不变质量 M：M²c⁴ = E总² − c²P总²。它一般不等于各粒子静质量之和，因为质心系内的运动能与相互作用能也贡献系统质量；在总动量为零的参考系中，质心系总能量等于 Mc²。例题：两粒子各质量 m，在质心系以速率 u 相向运动，碰后结合成静止复合体且不向外辐射；初动量相消，总能量为 2γmc²，复合体质量 M = 2γm > 2m，初始动能转化为内能，质量增量为 2(γ − 1)m。守恒的是总四动量，不是各物体静质量之和；若有光子逸出，必须把它们的四动量计入末态。"},{"m":"S7","sec":"四位置、四速度与四动量","t":"定义四位置 (ct, x, y, z)，度规 η = diag(1, −1, −1, −1)，两四矢量的点积为时间分量乘积减去空间点积；与四位置按同一线性规则变换的量才是四矢量，不是任意四个数都能构成。对有不变质量且速率低于 c 的粒子，用固有时定义四速度 U = dx/dτ，满足 U·U = c²。四动量 P = mU 的时间分量为 E/c、空间分量为动量p，其中 动量p = γmu、E = γmc²，低速下 动量p 趋于 mu。由 P·P = m²c² 得质量壳关系 E² = (pc)² + (mc²)²；静止时 E₀ = mc²，动能 K = E − mc²，低速展开恢复牛顿动能加小修正。光子没有静止系与固有时，不能用速度展开定义其能量，应直接用 m = 0 的质量壳关系 E = pc，并结合量子关系 E = ℏω。"},{"m":"S7","sec":"模块概览","t":"狭义相对论建立在相对性原理与光速不变原理之上，以洛伦兹变换取代伽利略变换，重构了时间、空间与动力学： $$t' = γ(t - (vx)/(c^2)), x' = γ(x - vt), γ = 1√(1-β^2)$$ ### 全章主线 - **时空几何**：同时性的相对性、钟慢尺缩、不变时空间隔 $Δ s^2=c^2Δ t^2-^2$ 与光锥因果结构。 - **波动与动力学**：速度合成、波四矢量多普勒频移、四维动量 $P^μ=(E/c,p)$、质能关系 $E^2=(pc)^2+(mc^2)^2$ 与相对论碰撞。"},{"m":"S7","sec":"加速器中的磁刚度","t":"粒子垂直进入匀强磁场，忽略辐射损失。洛伦兹力大小 |q|uB 使动量方向以角速率 u/ρ 转动，动量变化率大小等于 pu/ρ，得 p = |q|Bρ：由弯转半径即可推算动量，再经质量壳关系换算能量，这就是磁刚度。回旋角频率为 |q|B/(γm)，不再与能量无关——能量越高转得越慢，这是同步加速思想的起点。所需基础只是圆周运动与本章的动量定义；高精度束流分析还需要第六章的正则动力学。"},{"m":"S7","sec":"洛伦兹变换的推导","t":"设 S' 沿 S 的 +x 方向以速度 v 匀速运动，坐标轴平行，原点在 t = t' = 0 重合。时空均匀性要求变换是线性的，结合 S' 原点满足 x = vt，写成 x' = A(x − vt)、t' = Bt + Dx。对沿正、负 x 传播的光线分别代入 x = ±ct 与 x' = ±ct'，解出 B = A、D = −Av/c²；再由空间各向同性与惯性系互易性要求逆变换同形式、速度改为 −v，定出系数。定义 β = v/c、γ = 1/√(1 − β²)，得洛伦兹变换：x' = γ(x − vt)，t' = γ(t − vx/c²)，y' = y，z' = z。逆变换只需把 v 改为 −v 并交换撇号。运动方向上空间与时间坐标混合，横向坐标不变；当 |v| 远小于 c 且 vx/c² 可忽略时，恢复伽利略变换。"},{"m":"S7","sec":"事件、时钟同步与两个基本原理","t":"事件是在确定地点和时刻发生的事情，例如一次闪光或两粒子相遇，惯性系用 (t, x, y, z) 标记它；t 是该地点静止且已同步的时钟读数，不是远处观察者收到光信号的时刻。异地时钟按爱因斯坦约定同步：光在 t₁ 发出、经反射后 t₂ 返回，把反射时刻定义为 (t₁ + t₂)/2。伽利略变换给出速度法则 u' = u − v，与真空光速不变不能同时成立，因此必须重新审视绝对时间，而不是把牛顿方程中的质量随意改成速度函数。狭义相对论的两个基本原理：物理定律在所有惯性系中形式相同；真空光速为 c，与光源运动无关。c 同时是时空结构中的不变速度，限制局域信息传播；介质中的光速可以小于 c，不能代入时空变换。"},{"m":"M31","sec":"模块概览","t":"火箭依靠向后高速喷射工质获得推力，是典型的开放变质量系统。取火箭本体为控制体，计入喷出质量流带走的动量通量（相对喷速 $v_e$），得运动方程与齐奥尔科夫斯基火箭方程： $$mdvdt = -v_edmdt Δ v = v_e ln(m_0)/(m)$$ ### 关键结论 - 推进剂质量占比为 $ϵ = 1 - m/m_0 = 1 - e^-Δ v/v_e$。 - 质量比每翻倍，速度增量仅线性增加 $v_eln 2$；因此提升比冲（喷气速度 $v_e$）或采用多级抛弃死重，远比单纯堆砌单级燃料更高效。"},{"m":"M31","sec":"书稿精读","t":"【定理】火箭方程。计入喷气动量通量得 Δv=vₑ ln(m₀/m)；推进剂占比 ε=1−m/m₀。（书稿 ch01.tex:1322）"},{"m":"M31","sec":"操作提示","t":"拖动喷气速度与质量比，观察曲线与当前工作点；点击播放看质量比从 1 增长到目标值。"},{"m":"M31","sec":"核心结果","t":"质量比每翻倍，速度增量增加 vₑ ln2；提高喷气速度比单纯增加推进剂更高效。"},{"m":"M32","sec":"模块概览","t":"平面二连杆机械臂（杆长 $l_1,l_2$，关节角 $θ_1,θ_2$）将关节空间映射至末端工作空间，微小位移与速度由雅可比矩阵 $J$ 联系： $$ = J(θ) δθ, det J = l_1 l_2 sinθ_2$$ ### 奇异位形与自由度退化 - 当 $θ_2 = 0$（完全伸直）或 $θ_2 = π$（完全折叠）时，$det J=0$，雅可比矩阵降秩。 - 在奇异位形处，末端速度可操作椭球压扁成一条线段，机构瞬间丧失沿径向方向的瞬时可控速度，揭示了广义坐标映射的局部几何奇异性。"},{"m":"M32","sec":"书稿精读","t":"【方法】二连杆雅可比与奇异位形。关节速度经雅可比映射为末端速度，detJ=0 时失去一方向运动能力。（书稿 ch01.tex:532）"},{"m":"M32","sec":"核心结果","t":"det J=l₁l₂ sinθ₂；θ₂=0 或 π 时雅可比降秩，末端速度椭圆压成线段。"},{"m":"M32","sec":"操作提示","t":"拖动两个关节角，观察末端速度椭圆；点击扫过奇异位形。"},{"m":"M33","sec":"模块概览","t":"质量 $m$、半径 $R$、绕质心转动惯量 $I=kmR^2$ 的圆柱体沿倾角 $α$ 的粗糙斜面滚下。无滑纯滚动约束 $a=β R$ 由静摩擦力 $f_s$ 维持： $$a = (gsinα)/(1+k), f_s = (k)/(1+k)mgsinα$$ ### 惯量系数与纯滚动判据 - 质心平动动能与绕质心转动动能之比恒为 $1:k$；实心球（$k=2/5$）、实心圆柱（$k=1/2$）、空心圆筒（$k=1$）的下滑加速度依次递减。 - 维持纯滚动要求静摩擦系数满足 $μ ≥ (k)/(1+k)tanα$；否则圆柱发生边滚边滑，机械能因滑动摩擦耗散。"},{"m":"M33","sec":"核心结果","t":"令 k=I/(mR²)，纯滚动时 a=g sinα/(1+k)，要求 μ≥k tanα/(1+k)。"},{"m":"M33","sec":"书稿精读","t":"【例题】圆柱沿斜面纯滚动。用转动惯量写出沿斜面加速度与纯滚动条件。（书稿 ch05.tex:990）"},{"m":"M33","sec":"操作提示","t":"调节斜面角、惯量系数与摩擦系数，观察从纯滚动切换到滑动+转动。"},{"m":"M34","sec":"模块概览","t":"高能光子（初能量 $E=hc/λ$）与静止自由电子（静质量 $m_e$）发生弹性碰撞，联立能量守恒与三维动量守恒（即四动量守恒 $P_γ+P_e=P'_γ+P'_e$），消去反冲电子动量即得康普顿散射公式： $$Δλ = λ' - λ = λ_C(1 - cosθ), λ_C = (h)/(m_e c) ≈ 2.426 pm$$ ### 散射能量与反冲 - 散射光子能量为 $E' = (E)/(1 + (E/m_ec^2)(1-cosθ))$，反冲电子获得动能 $T_e = E - E'$。 - 波长增量仅取决于散射角 $θ$ 而与入射波长无关，背散射（$θ=π$）时电子带走最大动能（康普顿边缘）。"},{"m":"M34","sec":"核心结果","t":"Δλ=λ_C(1−cosθ)，λ_C=2.426 pm；E′=E/[1+(E/mₑc²)(1−cosθ)]。"},{"m":"M34","sec":"书稿精读","t":"【例题】康普顿散射运动学。由四动量守恒求散射光子能量与电子反冲。（书稿 ch07.tex:735）"},{"m":"M34","sec":"操作提示","t":"改变入射能量与散射角，比较散射光波长波形与反冲电子能量。"},{"m":"M35","sec":"模块概览","t":"由质量 $m$、间距 $a$、劲度 $K$ 的弹簧串联而成的无限一维周期原子链，代入行波试探解 $u_n∝ e^i(kna-ω t)$ 得色散关系与群速度： $$ω(k) = 2√((K)/(m))|sin(ka)/(2)|, v_g = dωdk = a√((K)/(m))cos(ka)/(2)$$ ### 长波声速与布里渊区边界 - **长波极限**（$ka 1$）：色散趋于线性 $ω≈ c_s |k|$，相速度与群速度重合为连续介质声速 $c_s = a√(K/m)$。 - **布里渊区边界**（$k=±π/a$）：群速度 $v_g=0$，相邻原子严格反相振动形成驻波，存在最高截止频率 $ω_max=2√(K/m)$。"},{"m":"M35","sec":"书稿精读","t":"【定理】周期链色散与群速度。ω(k)=2√(K/m)|sin(ka/2)|，长波极限给出声速。（书稿 ch04.tex:698）"},{"m":"M35","sec":"核心结果","t":"群速度 v_g=a√(K/m)cos(ka/2)；q→0 为声速，q→1 时驻波。"},{"m":"M35","sec":"操作提示","t":"拖动刚度与波数，观察色散曲线上的工作点和下方链上的波包。"},{"m":"M36","sec":"模块概览","t":"对在幂次中心势 $V(r)=α r^n$ 中做有界运动的系统，构造位力函数 $G=_i_i$ 并取长时间平均，由 $⟩=0$ 导出位力定理： $$2⟨ T⟩ = n⟨ V⟩$$ ### 典型幂次势验证 - **开普勒引力势**（$n=-1$）：$2⟨ T⟩ = -⟨ V⟩$，总能量 $E = -⟨ T⟩ = (1)/(2)⟨ V⟩ < 0$。 - **简谐振子势**（$n=2$）：$⟨ T⟩ = ⟨ V⟩$，动能与势能时间平均严格均分；数值积分的残差可直接检验轨道是否束缚。"},{"m":"M36","sec":"书稿精读","t":"【定理】位力定理。幂次势 V∝rⁿ 的束缚运动满足 2⟨T⟩=n⟨V⟩。（书稿 ch01.tex:1731）"},{"m":"M36","sec":"核心结果","t":"n=−1 时 2⟨T⟩=−⟨V⟩；n=2 时 2⟨T⟩=2⟨V⟩；偏差可用来判断轨道是否束缚或平均是否收敛。"},{"m":"M36","sec":"操作提示","t":"切换幂次 n 与初速，观察动能/势能读数和偏差。"},{"m":"M37","sec":"模块概览","t":"线密度为 $λ$ 的均匀柔绳悬挂于两点之间，在给定总绳长约束下极小化重力势能泛函 $V[y]=∫λ g y√(1+y'^2) dx$，由欧拉–拉格朗日方程导出悬链线（catenary）： $$y(x) = acosh(x)/(a), a = (T_0)/(λ g)$$ ### 几何参数与张力分布 - 参数 $a$ 等于最低点水平张力 $T_0$ 与单位长度重力之比；给定跨距 $L$ 与下垂量 $s$ 可由 $s=a[cosh(L)/(2a)-1]$ 反解 $a$。 - 绳长为 $2asinh(L)/(2a)$，绳上任意点张力 $T(x)=λ g y(x)$，越靠近悬点张力越大。"},{"m":"M37","sec":"书稿精读","t":"【例题】悬链线的双曲余弦解。均匀柔绳在重力下的平衡曲线为 y=a cosh(x/a)。（书稿 ch02.tex:455）"},{"m":"M37","sec":"核心结果","t":"s=a[cosh(L/2a)−1] 决定参数 a=T₀/(λg)；绳长为 2a sinh(L/2a)。"},{"m":"M37","sec":"操作提示","t":"固定跨度改变下垂量，比较曲线、绳长与底部张力。"},{"m":"M38","sec":"模块概览","t":"三个等质量 $m$ 的质点由相同弹簧（劲度 $K$）串联，构成三自由度耦合振子系统。通过质量加权刚度矩阵对角化，得到三个正交简正模与本征频率： $$ω_p = 2√((K)/(m))sin(pπ)/(8) (p=1,2,3)$$ ### 简正振型与有限到无限 - $p=1$ 为全链同相低频呼吸模，$p=2$ 为中间质点静止、两端反相模，$p=3$ 为相邻质点严格反相的高频模。 - 任意初始位移与速度均可唯一分解为这三种简正模的线性叠加，且离散频率点正好落在无限周期链色散曲线的采样点上。"},{"m":"M38","sec":"核心结果","t":"ω_p=2√(K/m)sin(pπ/8)；p=1 同相低频，p=3 相邻反相高频。"},{"m":"M38","sec":"书稿精读","t":"【例题】三原子链的零模与伸缩模。质量加权本征问题给出有限个独立振型。（书稿 ch04.tex:568）"},{"m":"M38","sec":"操作提示","t":"切换模态与刚度/质量，观察频率和原子相位关系。"},{"m":"M39","sec":"模块概览","t":"长为 $L$、质量 $m$ 的均匀细杆绕距质心 $d$ 的水平光滑轴摆动。由平行轴定理 $I=(1)/(12)mL^2+md^2$，小角简谐周期与等效摆长为： $$T_0 = 2π√((I)/(mgd)) = 2π√((L^2/12 + d^2)/(gd)), l_eq = d + (L^2)/(12d)$$ ### 最短周期悬点与大角修正 - 由均值不等式，当悬点距质心 $d = L/√(12)≈ 0.2887L$ 时周期取得极小值 $T_min=2πL√(3)g$。 - 有限振幅下，复摆与等效摆长 $l_eq$ 的单摆遵循完全相同的大角修正 $T≈ T_0(1+(θ_0^2)/(16))$。"},{"m":"M39","sec":"核心结果","t":"T₀=2π√[(L²/12+d²)/(gd)]；d=L/√12 时周期最短。大角修正约 1+θ₀²/16。"},{"m":"M39","sec":"书稿精读","t":"【例题】复摆周期。周期由 I/(mgd) 决定，固定杆长时存在最短周期悬点。（书稿 ch05.tex:903）"},{"m":"M39","sec":"操作提示","t":"拖动 d/L 找最短周期，再增大振幅看有限角修正。"},{"m":"M40","sec":"模块概览","t":"高能物理中产生重粒子需要足够的质心系总能量 $√(s)$，其中洛伦兹不变量 $s=(∑ E)^2-()^2$（取 $c=1$）。对比两种加速方案： $$s_固定靶 = m_a^2 + m_b^2 + 2m_b E_lab, s_对撞机 = 4E_beam^2$$ ### 阈能标度律对比 - 固定靶实验大部分能量消耗在维持质心向前飞行的动能上，产生质量 $M$ 的新粒子所需束流能量按 $E_lab∝ M^2/(2m_b)$ 二次方增长。 - 对撞机质心静止，束流能量全部用于质能转化，$E_beam∝ M/2$ 线性增长，在探索高能前沿时效率远高于固定靶。"},{"m":"M40","sec":"书稿精读","t":"【极限】固定靶阈能与对撞机。同样 √s 下，固定靶束流能量随 M² 增长。（书稿 ch07.tex:822）"},{"m":"M40","sec":"核心结果","t":"固定靶 s=mₐ²+m_b²+2m_bE；对撞机 s=4E²；产生重粒子时对撞机效率高得多。"},{"m":"M40","sec":"操作提示","t":"增大产生质量 M，比较两种方案的束流能量与比值。"}]};
